<h2 class="nobreak" title="I King Henry the Sixth." id="ida">
<span class="smaller">THE FIRST PART OF</span>
KING HENRY THE SIXTH.</h2></div>

<h3 class="h3main" title="Dramatis Personæ." id="ikh6-dp">
DRAMATIS PERSONÆ†.</h3>

<div class="dpbox">
<div class="right toppada"><small><a href="#idtoc" class="pginternal">toc</a></small></div>
<ul>
<li> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span></span> the Sixth.</li>
<li> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> uncle to the King, and Protector.</li>
<li> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">B<span>EDFORD</span>,</span> uncle to the King, and Regent of France.</li>
<li> <span class="smcaps">T<span>HOMAS</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> Duke of Exeter, great-uncle to the King.</li>
<li> <span class="smcaps">H<span>ENRY</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> great-uncle to the King, Bishop of Winchester, and afterwards Cardinal.</li>
<li> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> Earl, afterwards Duke, of Somerset.</li>
<li> <span class="smcaps">R<span>ICHARD</span></span> <span class="smcaps">P<span>LANTAGENET</span>,</span> son of Richard late Earl of Cambridge, afterwards Duke of York.</li>
<li> <span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">W<span>ARWICK</span></span>.</li>
<li> <span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">S<span>ALISBURY</span></span>.</li>
<li> <span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">S<span>UFFOLK</span></span>.</li>
<li> <span class="smcaps">L<span>ORD</span></span> <span class="smcaps">T<span>ALBOT</span>,</span> afterwards Earl of Shrewsbury.</li>
<li> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">T<span>ALBOT</span>,</span> his son.</li>
<li> <span class="smcaps">E<span>DMUND</span></span> <span class="smcaps">M<span>ORTIMER</span>,</span> Earl of March.</li>
<li> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">F<span>ASTOLFE</span></span>.</li>
<li> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">L<span>UCY</span></span>.</li>
<li> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">G<span>LANSDALE</span></span>.</li>
<li> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">T<span>HOMAS</span></span> <span class="smcaps">G<span>ARGRAVE</span></span>.</li>
<li> Mayor of London.</li>
<li> <span class="smcaps">W<span>OODVILE</span>,</span> Lieutenant of the Tower.</li>
<li> <span class="smcaps">V<span>ERNON</span>,</span> of the White-rose or York Faction.</li>
<li> <span class="smcaps">B<span>ASSET</span>,</span> of the Red-Rose or Lancaster faction.</li>
<li> A Lawyer. Mortimer’s Keepers.</li>
<li> <span class="smcaps">C<span>HARLES</span>,</span> Dauphin, and afterwards King, of France.</li>
<li> <span class="smcaps">R<span>EIGNIER</span>,</span> Duke of Anjou, and titular King of Naples.</li>
<li> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">B<span>URGUNDY</span></span>.</li>
<li> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">A<span>LENÇON</span></span>.</li>
<li> <span class="smcaps">B<span>ASTARD</span></span> <span class="smmaj">OF</span> <span class="smcaps">O<span>RLEANS</span></span>.</li>
<li> Governor of Paris.</li>
<li> Master-Gunner of Orleans, and his Son.</li>
<li> General of the French forces in Bourdeaux.</li>
<li> A French Sergeant. A Porter.</li>
<li> An old Shepherd, father to Joan la Pucelle.</li>
<li> <span class="smcaps">M<span>ARGARET</span>,</span> daughter to Reignier, afterwards married to King Henry.</li>
<li> <span class="smcaps">C<span>OUNTESS</span></span> <span class="smmaj">OF</span> <span class="smcaps">A<span>UVERGNE</span></span>.</li>
<li> <span class="smcaps">J<span>OAN</span></span> <span class="smmaj">LA</span> <span class="smcaps">P<span>UCELLE</span>,</span> commonly called Joan of Arc.</li>
</ul></div>

<div class="djust">Lords, Warders of the Tower, Heralds, Officers, Soldiers, Messengers,
and Attendants.</div>

<div class="toppada">Fiends appearing to La Pucelle.</div>

<div class="toppada"><span class="smcaps">S<span>CENE</span>:</span> Partly in England, and partly in France.</div>

<p class="footnote"> <span class="fnline"> </span>
 † First given, imperfectly, by Rowe. See note (I).</p>

<h3 class="pgbrk" title="ACT I.">
THE FIRST PART OF
<span class="larger">KING HENRY VI.</span>
ACT I.</h3>

<h4 class="h4main" id="aaa001">
<span class="dnavigate">aaa</span>
<span class="smcaps">S<span>CENE</span></span> I.
<i>Westminster Abbey</i>.</h4>

<div class="sd-schg"><span class="nowrap"><i>Dead March.</i></span>
<i>Enter the Funeral of</i>
<span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span></span> the Fifth, <i>attended
on by the</i> <span class="smcaps">D<span>UKE</span></span> of
<span class="smcaps">B<span>EDFORD</span>,</span> <i>Regent of
France; the</i> <span class="smcaps">D<span>UKE</span></span>
of <span class="smcaps">G<span>LOUCESTER</span>,</span>
<i>Protector; the</i> <span class="smcaps">D<span>UKE</span></span>
of <span class="smcaps">E<span>XETER</span>,</span>
<i>the</i> <span class="smcaps">E<span>ARL</span></span> of
<span class="smcaps">W<span>ARWICK</span>,</span> <i>the</i>
<span class="smcaps">B<span>ISHOP</span></span> of <span class="smcaps">W<span>INCHESTER</span>,</span> Heralds, <i>&amp;c.</i></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa001" id="lnum-aaa001">♦</a>
 <span class="sd-cn">Bed.</span>
 Hung be the heavens with black, yield day to night!</div>
<div class="dverse">Comets, importing change of times and states,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa003" id="lnum-aaa003">♦</a> Brandish your crystal tresses in the sky,</div>
<div class="dverse"> And with them scourge the bad revolting stars</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa005" id="lnum-aaa005">5</a> That have consented unto Henry’s death!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa006" id="lnum-aaa006">♦</a> King Henry the Fifth, too famous to live long!</div>
<div class="dverse"> England ne’er lost a king of so much worth.</div>

<div class="dverse1"><span class="sd-cn">Glou</span>. England ne’er had a king until his time.</div>
<div class="dverse"> Virtue he had, deserving to command:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa010" id="lnum-aaa010">10</a> His brandish’d sword did blind men with his beams:</div>
<div class="dverse"> His arms spread wider than a dragon’s wings;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa012" id="lnum-aaa012">♦</a> His sparkling eyes, replete with wrathful fire,</div>
<div class="dverse"> More dazzled and drove back his enemies</div>
<div class="dverse"> Than mid-day sun fierce bent against their faces.</div>
<div class="dverse"><span class="lnum">15</span> What should I say? his deeds exceed all speech:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa016" id="lnum-aaa016">♦</a> He ne’er lift up his hand but conquered.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span> We mourn in black: why mourn we not in blood?</div>
<div class="dverse"> Henry is dead and never shall revive:</div>
<div class="dverse"> Upon a wooden coffin we attend,</div>
<div class="dverse"><span class="lnum">20</span> And death’s dishonourable victory</div>
<div class="dverse"> We with our stately presence glorify,</div>
<div class="dverse"> Like captives bound to a triumphant car.</div>
<div class="dverse"> What! shall we curse the planets of mishap</div>
<div class="dverse"> That plotted thus our glory’s overthrow?</div>
<div class="dverse"><span class="lnum">25</span> Or shall we think the subtle-witted French</div>
<div class="dverse"> Conjurers and sorcerers, that afraid of him</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa027" id="lnum-aaa027">♦</a> By magic verses have contrived his end?</div>

<div class="dverse1"><span class="sd-cn">Win.</span> He was a king bless’d of the King of kings.</div>
<div class="dverse"> Unto the French the dreadful judgement-day</div>
<div class="dverse"><span class="lnum">30</span> So dreadful will not be as was his sight.</div>
<div class="dverse"> The battles of the Lord of hosts he fought:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa032" id="lnum-aaa032">♦</a> The church’s prayers made him so prosperous.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa033" id="lnum-aaa033">♦</a>
 <span class="sd-cn">Glou.</span>
 The church! where is it? Had not churchmen pray’d,</div>
<div class="dverse"> His thread of life had not so soon decay’d:</div>
<div class="dverse"><span class="lnum">35</span> None do you like but an effeminate prince,</div>
<div class="dverse"> Whom, like a school-boy, you may over-awe.</div>

<div class="dverse1"><span class="sd-cn">Win.</span> Gloucester, whate’er we like, thou art Protector</div>
<div class="dverse"> And lookest to command the prince and realm.</div>
<div class="dverse"> Thy wife is proud; she holdeth thee in awe,</div>
<div class="dverse"><span class="lnum">40</span> More than God or religious churchmen may.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> Name not religion, for thou lovest the flesh,</div>
<div class="dverse"> And ne’er throughout the year to church thou go’st</div>
<div class="dverse"> Except it be to pray against thy foes.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span> Cease, cease these jars and rest your minds in peace:</div>
<div class="dverse"><span class="lnum">45</span> Let’s to the altar: heralds, wait on us:</div>
<div class="dverse"> Instead of gold, we’ll offer up our arms;</div>
<div class="dverse"> Since arms avail not now that Henry’s dead.</div>
<div class="dverse"> Posterity, await for wretched years,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa049" id="lnum-aaa049">♦</a> When at their mothers’ moist eyes babes shall suck,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa050" id="lnum-aaa050">50</a> Our isle be made a nourish of salt tears,</div>
<div class="dverse"> And none but women left to wail the dead.</div>
<div class="dverse"> Henry the Fifth, thy ghost I invocate:</div>
<div class="dverse"> Prosper this realm, keep it from civil broils,</div>
<div class="dverse"> Combat with adverse planets in the heavens!</div>
<div class="dverse"><span class="lnum">55</span> A far more glorious star thy soul will make</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa056" id="lnum-aaa056">♦</a> Than Julius Cæsar or bright ——</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa057" id="lnum-aaa057">♦</a>
 <span class="sd-cn">Mess.</span>
 My honourable lords, health to you all!</div>
<div class="dverse">Sad tidings bring I to you out of France,</div>
<div class="dverse">Of loss, of slaughter and discomfiture:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa060" id="lnum-aaa060">60</a>Guienne, Champagne, Rheims, Orleans,</div>
<div class="dverse">Paris, Guysors, Poictiers, are all quite lost.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa062" id="lnum-aaa062">♦</a>
 <span class="sd-cn">Bed.</span>
What say’st thou, man, before dead Henry’s corse?</div>
<div class="dverse">Speak softly; or the loss of those great towns</div>
<div class="dverse">Will make him burst his lead and rise from death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa065" id="lnum-aaa065">65</a>
 <span class="sd-cn">Glou.</span>
Is Paris lost? is Rouen yielded up?</div>
<div class="dverse">If Henry were recall’d to life again,</div>
<div class="dverse">These news would cause him once more yield the ghost.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span> How were they lost? what treachery was used?</div>

<div class="dverse1"><span class="sd-cn">Mess.</span> No treachery; but want of men and money.</div>
<div class="dverse"><span class="lnum">70</span>Amongst the soldiers this is muttered,</div>
<div class="dverse">That here you maintain several factions,</div>
<div class="dverse">And whilst a field should be dispatch’d and fought,</div>
<div class="dverse">You are disputing of your generals:</div>
<div class="dverse">One would have lingering wars with little cost;</div>
<div class="dverse"><span class="lnum">75</span>Another would fly swift, but wanteth wings;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa076" id="lnum-aaa076">♦</a>
A third thinks, without expense at all,</div>
<div class="dverse">By guileful fair words peace may be obtain’d.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa078" id="lnum-aaa078">♦</a>
Awake, awake, English nobility!</div>
<div class="dverse">Let not sloth dim your honours new-begot:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa080" id="lnum-aaa080">80</a>
Cropp’d are the flower-de-luces in your arms;</div>
<div class="dverse">Of England’s coat one half is cut away.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span> Were our tears wanting to this funeral,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa083" id="lnum-aaa083">♦</a>
These tidings would call forth their flowing tides.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span> Me they concern; Regent I am of France.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa085" id="lnum-aaa085">85</a>
Give me my steeled coat. I’ll fight for France.</div>
<div class="dverse">Away with these disgraceful wailing robes!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa087" id="lnum-aaa087">♦</a>
Wounds will I lend the French instead of eyes,</div>
<div class="dverse">To weep their intermissive miseries.</div>

<div class="sd-entry"><i>Enter to them another</i> Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa089" id="lnum-aaa089">♦</a>
 <span class="sd-cn">Mess.</span>
Lords, view these letters full of bad mischance.</div>
<div class="dverse"><span class="lnum">90</span>France is revolted from the English quite,</div>
<div class="dverse">Except some petty towns of no import:</div>
<div class="dverse">The Dauphin Charles is crowned king in Rheims;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa093" id="lnum-aaa093">♦</a>The Bastard of Orleans with him is join’d;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa094" id="lnum-aaa094">♦</a>Reignier, Duke of Anjou, doth take his part;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa095" id="lnum-aaa095">95</a>The Duke of Alençon flieth to his side.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa096" id="lnum-aaa096">♦</a>
 <span class="sd-cn">Exe.</span>The Dauphin crowned king! all fly to him!</div>
<div class="dverse">O, whither shall we fly from this reproach?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> We will not fly, but to our enemies’ throats.</div>
<div class="dverse">Bedford, if thou be slack, I’ll fight it out.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Bed.</span> Gloucester, why doubt’st thou of my forwardness?</div>
<div class="dverse">An army have I muster’d in my thoughts,</div>
<div class="dverse">Wherewith already France is overrun.</div>

<div class="sd-entry"><i>Enter another</i> Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa103" id="lnum-aaa103">♦</a>
 <span class="sd-cn">Mess.</span> My gracious lords, to add to your laments,</div>
<div class="dverse">Wherewith you now bedew King Henry’s hearse,</div>
<div class="dverse"><span class="lnum">105</span>I must inform you of a dismal fight</div>
<div class="dverse">Betwixt the stout Lord Talbot and the French.</div>

<div class="dverse1"><span class="sd-cn">Win.</span> What! wherein Talbot overcame? is’t so?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa108" id="lnum-aaa108">♦</a>
 <span class="sd-cn">Mess.</span> O, no; wherein Lord Talbot was o’erthrown:</div>
<div class="dverse">The circumstance I’ll tell you more at large.</div>
<div class="dverse"><span class="lnum">110</span>The tenth of August last this dreadful lord,</div>
<div class="dverse">Retiring from the siege of Orleans,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa112" id="lnum-aaa112">♦</a>Having full scarce six thousand in his troop,</div>
<div class="dverse">By three and twenty thousand of the French</div>
<div class="dverse">Was round encompassed and set upon.</div>
<div class="dverse"><span class="lnum">115</span>No leisure had he to enrank his men;</div>
<div class="dverse">He wanted pikes to set before his archers;</div>
<div class="dverse">Instead whereof sharp stakes pluck’d out of hedges</div>
<div class="dverse">They pitched in the ground confusedly,</div>
<div class="dverse">To keep the horsemen off from breaking in.</div>
<div class="dverse"><span class="lnum">120</span>More than three hours the fight continued;</div>
<div class="dverse">Where valiant Talbot above human thought</div>
<div class="dverse">Enacted wonders with his sword and lance:</div>
<div class="dverse">Hundreds he sent to hell, and none durst stand him;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa124" id="lnum-aaa124">♦</a>Here, there, and every where, enraged he flew:</div>
<div class="dverse"><span class="lnum">125</span>The French exclaim’d, the devil was in arms;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa126" id="lnum-aaa126">♦</a>All the whole army stood agazed on him:</div>
<div class="dverse">His soldiers spying his undaunted spirit</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa128" id="lnum-aaa128">♦</a>A Talbot! a Talbot! cried out amain</div>
<div class="dverse">And rush’d into the bowels of the battle.</div>
<div class="dverse"><span class="lnum">130</span>Here had the conquest fully been seal’d up,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa131" id="lnum-aaa131">♦</a>If Sir John Fastolfe had not play’d the coward:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa132" id="lnum-aaa132">♦</a>He, being in the vaward, placed behind</div>
<div class="dverse">With purpose to relieve and follow them,</div>
<div class="dverse">Cowardly fled, not having struck one stroke.</div>
<div class="dverse"><span class="lnum">135</span>Hence grew the general wreck and massacre;</div>
<div class="dverse">Enclosed were they with their enemies:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa137" id="lnum-aaa137">♦</a>A base Walloon, to win the Dauphin’s grace,</div>
<div class="dverse">Thrust Talbot with a spear into the back,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa139" id="lnum-aaa139">♦</a>Whom all France with their chief assembled strength</div>
<div class="dverse"><span class="lnum">140</span>Durst not presume to look once in the face.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa141" id="lnum-aaa141">♦</a>
 <span class="sd-cn">Bed.</span> Is Talbot slain? then I will slay myself,</div>
<div class="dverse">For living idly here in pomp and ease,</div>
<div class="dverse">Whilst such a worthy leader, wanting aid,</div>
<div class="dverse">Unto his dastard foemen is betray’d.</div>

<div class="dverse1"><span class="lnum">145</span>
 <span class="sd-cn">Mess.</span> O no, he lives; but is took prisoner,</div>
<div class="dverse">And Lord Scales with him and Lord Hungerford:</div>
<div class="dverse">Most of the rest slaughter’d or took likewise.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span> His ransom there is none but I shall pay:</div>
<div class="dverse">I’ll hale the Dauphin headlong from his throne:</div>
<div class="dverse"><span class="lnum">150</span>His crown shall be the ransom of my friend;</div>
<div class="dverse">Four of their lords I’ll change for one of ours.</div>
<div class="dverse">Farewell, my masters; to my task will I;</div>
<div class="dverse">Bonfires in France forthwith I am to make,</div>
<div class="dverse">To keep our great Saint George’s feast withal:</div>
<div class="dverse"><span class="lnum">155</span>Ten thousand soldiers with me I will take,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa156" id="lnum-aaa156">♦</a>Whose bloody deeds shall make all Europe quake.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa157" id="lnum-aaa157">♦</a>
 <span class="sd-cn">Mess.</span> So you had need; for Orleans is besieged;</div>
<div class="dverse">The English army is grown weak and faint:</div>
<div class="dverse">The Earl of Salisbury craveth supply,</div>
<div class="dverse"><span class="lnum">160</span>And hardly keeps his men from mutiny,</div>
<div class="dverse">Since they, so few, watch such a multitude.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa162" id="lnum-aaa162">♦</a>
 <span class="sd-cn">Exe.</span> Remember, lords, your oaths to Henry sworn,</div>
<div class="dverse">Either to quell the Dauphin utterly,</div>
<div class="dverse">Or bring him in obedience to your yoke.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaa165" id="lnum-aaa165">165</a>
 <span class="sd-cn">Bed.</span> I do remember it; and here take my leave,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa166" id="lnum-aaa166">♦</a>
 To go about my preparation.
 <span class="sd-verseend">[<i>Exit</i>.</span></div>

<div class="dverse1"><span class="sd-cn">Glou.</span> I’ll to the Tower with all the haste I can,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa168" id="lnum-aaa168">♦</a>To view the artillery and munition;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa169" id="lnum-aaa169">♦</a>
 And then I will proclaim young Henry king.
 <span class="sd-verseend">[<i>Exit</i>.</span></div>

<div class="dverse1"><span class="lnum">170</span>
 <span class="sd-cn">Exe.</span> To Eltham will I, where the young king is,</div>
<div class="dverse">Being ordain’d his special governor,</div>
<div class="dverse">And for his safety there I’ll best devise. <span class="sd-verseend">[<i>Exit</i>.</span></div>

<div class="dverse1"><span class="sd-cn">Win.</span> Each hath his place and function to attend:</div>
<div class="dverse">I am left out; for me nothing remains.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa175" id="lnum-aaa175">175</a> But long I will not be Jack out of office:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa176" id="lnum-aaa176">♦</a> The king from Eltham I intend to steal</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaa177" id="lnum-aaa177">♦</a> And sit at chiefest stern of public weal.
  <span class="sd-verseend">[<i>Exeunt</i>.</span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aab</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>France. Before Orleans</i>.
</h4>

<div class="sd-schg"><i>Sound a Flourish.
Enter</i> <span class="smcaps">C<span>HARLES</span>,</span>
<span class="smcaps">A<span>LENÇON</span>,</span> <i>and</i>
<span class="smcaps">R<span>EIGNIER</span>,</span>
<i>marching with Drum and Soldiers</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab001" id="lnum-aab001">♦</a>
 <span class="sd-cn">Char.</span> Mars his true moving, even as in the heavens</div>
<div class="dverse">So in the earth, to this day is not known:</div>
<div class="dverse">Late did he shine upon the English side;</div>
<div class="dverse">Now we are victors; upon us he smiles.</div>
<div class="dverse"><span class="lnum">5</span> What towns of any moment but we have?</div>
<div class="dverse">At pleasure here we lie near Orleans;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab007" id="lnum-aab007">♦</a> Otherwhiles the famish’d English, like pale ghosts,</div>
<div class="dverse">Faintly besiege us one hour in a month.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span> They want their porridge and their fat bull-beeves:</div>
<div class="dverse"><span class="lnum">10</span> Either they must be dieted like mules</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab011" id="lnum-aab011">♦</a> And have their provender tied to their mouths</div>
<div class="dverse">Or piteous they will look, like drowned mice.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab013" id="lnum-aab013">♦</a>
 <span class="sd-cn">Reig.</span> Let’s raise the siege: why live we idly here?</div>
<div class="dverse">Talbot is taken, whom we wont to fear:</div>
<div class="dverse"><span class="lnum">15</span>Remaineth none but mad-brain’d Salisbury;</div>
<div class="dverse">And he may well in fretting spend his gall,</div>
<div class="dverse">Nor men nor money hath he to make war.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> Sound, sound alarum! we will rush on them.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab019" id="lnum-aab019">♦</a> Now for the honour of the forlorn French!</div>
<div class="dverse"><span class="lnum">20</span> Him I forgive my death that killeth me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab021" id="lnum-aab021">♦</a>
When he sees me go back one foot or fly.
<span class="sd-verseend">[<i>Exeunt</i>.</span></div>

<div class="sd-entry"><i>Here Alarum; they are beaten back by the English with great loss. Re-enter</i> <span class="smcaps">C<span>HARLES</span>,</span>
<span class="smcaps">A<span>LENÇON</span>,</span> <i>and</i> <span class="smcaps">R<span>EIGNIER</span></span>.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> Who ever saw the like? what men have I!</div>
<div class="dverse">Dogs! cowards! dastards! I would ne’er have fled,</div>
<div class="dverse">But that they left me ’midst my enemies.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Reig.</span>  Salisbury is a desperate homicide;</div>
<div class="dverse">He fighteth as one weary of his life.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab027" id="lnum-aab027">♦</a> The other lords, like lions wanting food,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab028" id="lnum-aab028">♦</a> Do rush upon us as their hungry prey.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab029" id="lnum-aab029">♦</a>
 <span class="sd-cn">Alen.</span>
 Froissart, a countryman of ours, records,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab030" id="lnum-aab030">30</a>
 England all Olivers and Rowlands bred</div>
<div class="dverse">During the time Edward the Third did reign.</div>
<div class="dverse">More truly now may this be verified;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab033" id="lnum-aab033">♦</a>
 For none but Samsons and Goliases</div>
<div class="dverse">It sendeth forth to skirmish. One to ten!</div>
<div class="dverse"><span class="lnum">35</span>
 Lean raw-boned rascals! who would e’er suppose</div>
<div class="dverse">They had such courage and audacity?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab037" id="lnum-aab037">♦</a>
 <span class="sd-cn">Char.</span>
 Let’s leave this town; for they are hare-brain’d  slaves,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab038" id="lnum-aab038">♦</a>
 And hunger will enforce them to be more eager:</div>
<div class="dverse">Of old I know them; rather with their teeth</div>
<div class="dverse"><span class="lnum">40</span>
 The walls they’ll tear down than forsake the siege.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab041" id="lnum-aab041">♦</a>
 <span class="sd-cn">Reig.</span>
 I think, by some odd gimmors or device</div>
<div class="dverse">Their arms are set like clocks, still to strike on;</div>
<div class="dverse">Else ne’er could they hold out so as they do.</div>
<div class="dverse">By my consent, we’ll even let them alone.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Alen.</span>
 Be it so.</div>

<div class="sd-entry"><i>Enter the</i> <span class="smcaps">B<span>ASTARD</span></span> of Orleans.</div>

<div class="dverse1"><span class="sd-cn">Bast.</span> Where’s the Prince Dauphin? I have news for him.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> Bastard of Orleans, thrice welcome to us.</div>

<div class="dverse1"><span class="sd-cn">Bast.</span> Methinks your looks are sad, your cheer appall’d:</div>
<div class="dverse">Hath the late overthrow wrought this offence?</div>
<div class="dverse"><span class="lnum">50</span> Be not dismay’d, for succour is at hand:</div>
<div class="dverse">A holy maid hither with me I bring,</div>
<div class="dverse">Which by a vision sent to her from heaven</div>
<div class="dverse">Ordained is to raise this tedious siege</div>
<div class="dverse">And drive the English forth the bounds of France.</div>
<div class="dverse"><span class="lnum">55</span>
 The spirit of deep prophecy she hath,</div>
<div class="dverse">Exceeding the nine sibyls of old Rome:</div>
<div class="dverse">What’s past and what’s to come she can descry.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab058" id="lnum-aab058">♦</a>
 Speak, shall I call her in? Believe my words,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab059" id="lnum-aab059">♦</a>
 For they are certain and unfallible.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab060" id="lnum-aab060">60</a>
 <span class="sd-cn">Char.</span>
 Go, call her in. <span class="sd-inline">[<i>Exit Bastard.</i>]</span>
 But first, to try her skill,</div>
<div class="dverse">Reignier, stand thou as Dauphin in my place:</div>
<div class="dverse">Question her proudly; let thy looks be stern:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab063" id="lnum-aab063">♦</a>By this means shall we sound what skill she hath.</div>

 <div class="sd-entry"><i>Re-enter the</i> <span class="smcaps">B<span>ASTARD</span></span> of Orleans, <i>with</i>
 <span class="smcaps">J<span>OAN</span></span>
 <span class="smmaj">LA</span>
 <span class="smcaps">P<span>UCELLE</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab064" id="lnum-aab064">♦</a>
 <span class="sd-cn">Reig.</span> Fair maid, is’t thou wilt do these wondrous feats?</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">Puc.</span> Reignier, is’t thou that thinkest to beguile me?</div>
<div class="dverse">Where is the Dauphin? Come, come from behind;</div>
<div class="dverse">I know thee well, though never seen before.</div>
<div class="dverse">Be not amazed, there’s nothing hid from me:</div>
<div class="dverse">In private will I talk with thee apart.</div>
<div class="dverse"><span class="lnum">70</span>Stand back, you lords, and give us leave awhile.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> She takes upon her bravely at first dash.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>  Dauphin, I am by birth a shepherd’s daughter,</div>
<div class="dverse">My wit untrain’d in any kind of art.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab074" id="lnum-aab074">♦</a>Heaven and our Lady gracious hath it pleased</div>
<div class="dverse"><span class="lnum">75</span>To shine on my contemptible estate:</div>
<div class="dverse">Lo, whilst I waited on my tender lambs,</div>
<div class="dverse">And to sun’s parching heat display’d my cheeks,</div>
<div class="dverse">God’s mother deigned to appear to me</div>
<div class="dverse">And in a vision full of majesty</div>
<div class="dverse"><span class="lnum">80</span>Will’d me to leave my base vocation</div>
<div class="dverse">And free my country from calamity:</div>
<div class="dverse">Her aid she promised and assured success:</div>
<div class="dverse">In complete glory she reveal’d herself;</div>
<div class="dverse">And, whereas I was black and swart before,</div>
<div class="dverse"><span class="lnum">85</span>With those clear rays which she infused on me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab086" id="lnum-aab086">♦</a>That beauty am I bless’d with which you see.</div>
<div class="dverse">Ask me what question thou canst possible,</div>
<div class="dverse">And I will answer unpremeditated:</div>
<div class="dverse">My courage try by combat, if thou darest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab090" id="lnum-aab090">90</a>And thou shalt find that I exceed my sex.</div>
<div class="dverse">Resolve on this, thou shalt be fortunate,</div>
<div class="dverse">If thou receive me for thy warlike mate.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> Thou hast astonish’d me with thy high terms:</div>
<div class="dverse">Only this proof I’ll of thy valour make,</div>
<div class="dverse"><span class="lnum">95</span>In single combat thou shalt buckle with me,</div>
<div class="dverse">And if thou vanquishest, thy words are true;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab097" id="lnum-aab097">♦</a>Otherwise I renounce all confidence.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span> I am prepared: here is my keen-edged sword,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab099" id="lnum-aab099">♦</a>Deck’d with five flower-de-luces on each side;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab100" id="lnum-aab100">100</a>The which at Touraine, in Saint Katharine’s churchyard,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab101" id="lnum-aab101">♦</a>Out of a great deal of old iron I chose forth.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab102" id="lnum-aab102">♦</a>
 <span class="sd-cn">Char.</span> Then come, o’ God’s name; I fear no woman.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab103" id="lnum-aab103">♦</a>
 <span class="sd-cn">Puc.</span>
 And while I live, I’ll ne’er fly from a man.
 <span class="sd-verseend">[<i>Here they fight, and Joan La Pucelle overcomes.</i></span></div>

<div class="dverse1"><span class="sd-cn">Char.</span> Stay, stay thy hands! thou art an Amazon,</div>
<div class="dverse"><span class="lnum">105</span>And fightest with the sword of Deborah.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span> Christ’s mother helps me, else I were too weak.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> Whoe’er helps thee, ’tis thou that must help me:</div>
<div class="dverse">Impatiently I burn with thy desire;</div>
<div class="dverse">My heart and hands thou hast at once subdued.</div>
<div class="dverse"><span class="lnum">110</span>Excellent Pucelle, if thy name be so,</div>
<div class="dverse">Let me thy servant and not sovereign be:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab112" id="lnum-aab112">♦</a>’Tis the French Dauphin sueth to thee thus.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab113" id="lnum-aab113">♦</a>
 <span class="sd-cn">Puc.</span>  I must not yield to any rites of love,</div>
<div class="dverse">For my profession’s sacred from above:</div>
<div class="dverse"><span class="lnum">115</span>When I have chased all thy foes from hence,</div>
<div class="dverse">Then will I think upon a recompense.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> Meantime look gracious on thy prostrate thrall.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> My lord, methinks, is very long in talk.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span> Doubtless he shrives this woman to her smock;</div>
<div class="dverse"><span class="lnum">120</span>Else ne’er could he so long protract his speech.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> Shall we disturb him, since he keeps no mean?</div>

<div class="dverse1"><span class="sd-cn">Alen.</span> He may mean more than we poor men do know:</div>
<div class="dverse">These women are shrewd tempters with their tongues.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> My lord, where are you? what devise you on?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab125" id="lnum-aab125">125</a>Shall we give over Orleans, or no?</div>

<div class="dverse1"><span class="sd-cn">Puc.</span> Why, no, I say, distrustful recreants!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab127" id="lnum-aab127">♦</a>Fight till the last gasp; I will be your guard.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> What she says I’ll confirm: we’ll fight it out.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab129" id="lnum-aab129">♦</a>
 <span class="sd-cn">Puc.</span> Assign’d am I to be the English scourge.</div>
<div class="dverse"><span class="lnum">130</span>This night the siege assuredly I’ll raise:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab131" id="lnum-aab131">♦</a>Expect Saint Martin’s summer, halcyon days,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab132" id="lnum-aab132">♦</a>Since I have entered into these wars.</div>
<div class="dverse">Glory is like a circle in the water,</div>
<div class="dverse">Which never ceaseth to enlarge itself</div>
<div class="dverse"><span class="lnum">135</span>Till by broad spreading it disperse to nought.</div>
<div class="dverse">With Henry’s death the English circle ends;</div>
<div class="dverse">Dispersed are the glories it included.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab138" id="lnum-aab138">♦</a>Now am I like that proud insulting ship</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab139" id="lnum-aab139">♦</a>Which Cæsar and his fortune bare at once.</div>

<div class="dverse1"><span class="lnum">140</span>
 <span class="sd-cn">Char.</span> Was Mahomet inspired with a dove?</div>
<div class="dverse">Thou with an eagle art inspired then.</div>
<div class="dverse">Helen, the mother of great Constantine,</div>
<div class="dverse">Nor yet Saint Philip’s daughters, were like thee.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab144" id="lnum-aab144">♦</a>Bright star of Venus, fall’n down on the earth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab145" id="lnum-aab145">145</a>How may I reverently worship thee enough?</div>

<div class="dverse1"><span class="sd-cn">Alen.</span>
Leave off delays, and let us raise the siege.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> Woman, do what thou canst to save our honours;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab148" id="lnum-aab148">♦</a>Drive them from Orleans and be immortalized.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aab149" id="lnum-aab149">♦</a>
 <span class="sd-cn">Char.</span> Presently we’ll try: come, let’s away about it:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aab150" id="lnum-aab150">150</a>
No prophet will I trust, if she prove false. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aac</span> <span class="smcaps">S<span>CENE</span></span> III. <i>London. Before the
Tower</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">D<span>UKE</span></span>
of <span class="smcaps">G<span>LOUCESTER</span>,</span> <i>with his</i>
Serving-men <i>in blue coats</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac001" id="lnum-aac001">♦</a>
 <span class="sd-cn">Glou.</span> I am come to survey the Tower this day:</div>
<div class="dverse">Since Henry’s death, I fear, there is conveyance.</div>
<div class="dverse">Where be these warders, that they wait not here?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac004" id="lnum-aac004">♦</a>Open the gates; ’tis Gloucester that calls.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac005" id="lnum-aac005">5</a>
 <span class="sd-cn">First Warder.</span>
<span class="sd-inline">[<i>Within</i>]</span>
Who’s there that knocks so imperiously?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac006" id="lnum-aac006">♦</a>
 <span class="sd-cn">First Serv.</span> It is the noble Duke of Gloucester.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac007" id="lnum-aac007">♦</a>
 <span class="sd-cn">Second Warder.</span>
<span class="sd-inline">[<i>Within</i>]</span>
Whoe’er he be, you may not be let in.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac008" id="lnum-aac008">♦</a>
 <span class="sd-cn">First Serv.</span> Villains, answer you so the lord protector?</div>

<div class="dverse1"><span class="sd-cn">First Warder.</span>
<span class="sd-inline">[<i>Within</i>]</span>
The Lord protect him! so we answer him:</div>
<div class="dverse"><span class="lnum">10</span>
We do no otherwise than we are will’d.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac011" id="lnum-aac011">♦</a>
 <span class="sd-cn">Glou.</span> Who willed you? or whose will stands but mine?</div>
<div class="dverse">There’s none protector of the realm but I.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac013" id="lnum-aac013">♦</a>Break up the gates, I’ll be your warrantize:</div>
<div class="dverse">Shall I be flouted thus by dunghill grooms?
<span class="sd-verseend">[<i>Gloucester’s men rush at the Tower Gates, and Woodvile the Lieutenant speaks within.</i></span></div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Woodv.</span> What noise is this? what traitors have we here?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> Lieutenant, is it you whose voice I hear?</div>
<div class="dverse">Open the gates; here’s Gloucester that would enter.</div>

<div class="dverse1"><span class="sd-cn">Woodv.</span> Have patience, noble duke; I may not open;</div>
<div class="dverse">The Cardinal of Winchester forbids:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac020" id="lnum-aac020">20</a>From him I have express commandment</div>
<div class="dverse">That thou nor none of thine shall be let in.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> Faint-hearted Woodvile, prizest him ’fore me?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac023" id="lnum-aac023">♦</a>Arrogant Winchester, that haughty prelate,</div>
<div class="dverse">Whom Henry, our late sovereign, ne’er could brook?</div>
<div class="dverse"><span class="lnum">25</span>Thou art no friend to God or to the king:</div>
<div class="dverse">Open the gates, or I’ll shut thee out shortly.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac027" id="lnum-aac027">♦</a>
 <span class="sd-cn">Serving-men.</span> Open the gates unto the lord protector,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac028" id="lnum-aac028">♦</a>Or we’ll burst them open, if that you come not quickly.</div>

<div class="sd-entry"><i>Enter to the Protector at the Tower Gates</i> <span class="smcaps">W<span>INCHESTER</span></span> <i>and his men in tawny coats</i>. </div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac029" id="lnum-aac029">♦</a>
 <span class="sd-cn">Win.</span> How now, ambitious Humphry! what means this?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac030" id="lnum-aac030">30</a>
 <span class="sd-cn">Glou.</span> Peel’d priest, dost thou command me to be shut out?</div>

<div class="dverse1"><span class="sd-cn">Win.</span> I do, thou most usurping proditor,</div>
<div class="dverse">And not protector, of the king or realm.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> Stand back, thou manifest conspirator,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac034" id="lnum-aac034">♦</a>Thou that contrivedst to murder our dead lord;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac035" id="lnum-aac035">35</a>Thou that givest whores indulgences to sin:</div>
<div class="dverse">I’ll canvass thee in thy broad cardinal’s hat,</div>
<div class="dverse">If thou proceed in this thy insolence.</div>

<div class="dverse1"><span class="sd-cn">Win.</span> Nay, stand thou back; I will not budge a foot:</div>
<div class="dverse">This be Damascus, be thou cursed Cain,</div>
<div class="dverse"><span class="lnum">40</span>To slay thy brother Abel, if thou wilt.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac041" id="lnum-aac041">♦</a>
 <span class="sd-cn">Glou.</span> I will not slay thee, but I’ll drive thee back:</div>
<div class="dverse">Thy scarlet robes as a child’s bearing-cloth</div>
<div class="dverse">I’ll use to carry thee out of this place.</div>

<div class="dverse1"><span class="sd-cn">Win.</span> Do what thou darest; I beard thee to thy face.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Glou.</span> What! am I dared and bearded to my face?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac046" id="lnum-aac046">♦</a>Draw, men, for all this privileged place;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac047" id="lnum-aac047">♦</a>Blue coats to tawny coats. Priest, beware your beard;</div>
<div class="dverse">I mean to tug it and to cuff you soundly:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac049" id="lnum-aac049">♦</a>Under my feet I stamp thy cardinal’s hat:</div>
<div class="dverse"><span class="lnum">50</span>In spite of pope or dignities of church,</div>
<div class="dverse">Here by the cheeks I’ll drag thee up and down.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac052" id="lnum-aac052">♦</a>
 <span class="sd-cn">Win.</span> Gloucester, thou wilt answer this before the pope.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> Winchester goose, I cry, a rope! a rope!</div>
<div class="dverse">Now beat them hence; why do you let them stay?</div>
<div class="dverse"><span class="lnum">55</span>Thee I’ll chase hence, thou wolf in sheep’s array.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac056" id="lnum-aac056">♦</a>Out, tawny coats! out, scarlet hypocrite!</div>

<div class="sd-entry"><i>Here Gloucester’s men beat out the Cardinal’s men, and enter in the hurly-burly the</i> Mayor of London <i>and his</i> Officers. </div>

<div class="dverse1"><span class="sd-cn">May.</span> Fie, lords! that you, being supreme magistrates,</div>
<div class="dverse">Thus contumeliously should break the peace!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac059" id="lnum-aac059">♦</a>
 <span class="sd-cn">Glou.</span> Peace, mayor! thou know’st little of my wrongs:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac060" id="lnum-aac060">60</a>Here’s Beaufort, that regards nor God nor king,</div>
<div class="dverse">Hath here distrain’d the Tower to his use.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac062" id="lnum-aac062">♦</a>
 <span class="sd-cn">Win.</span> Here’s Gloucester, a foe to citizens,</div>
<div class="dverse">One that still motions war and never peace,</div>
<div class="dverse">O’ercharging your free purses with large fines,</div>
<div class="dverse"><span class="lnum">65</span>That seeks to overthrow religion,</div>
<div class="dverse">Because he is protector of the realm,</div>
<div class="dverse">And would have armour here out of the Tower,</div>
<div class="dverse">To crown himself king and suppress the prince.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> I will not answer thee with words, but blows. <span class="sd-verseend">[<i>Here they skirmish again.</i></span></div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">May.</span> Nought rests for me in this tumultuous strife</div>
<div class="dverse">But to make open proclamation:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac072" id="lnum-aac072">♦</a>Come, officer; as loud as e’er thou canst:</div>
<div class="dverse">Cry.</div>

<div class="dprose1 lhclose"><a class="lnum pginternal" href="#lnote-aac074" id="lnum-aac074">♦</a>
<span class="sd-cn">Off.</span>
<span class="smprint">All manner of men assembled here in arms this day against
<span class="lnum">75</span>
God’s peace and the king’s, we charge and command you, in his highness’
name, to repair to your several dwelling-places; and not to wear, handle,
or use any sword, weapon, or dagger, henceforward, upon pain of death.</span>
</div>

<div class="dverse1"><span class="sd-cn">Glou.</span> Cardinal, I’ll be no breaker of the law:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac080" id="lnum-aac080">80</a>But we shall meet, and break our minds at large.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac081" id="lnum-aac081">♦</a>
 <span class="sd-cn">Win.</span> Gloucester, we will meet; to thy cost, be sure:</div>
<div class="dverse">Thy heart-blood I will have for this day’s work.</div>

<div class="dverse1"><span class="sd-cn">May.</span> I’ll call for clubs, if you will not away.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac084" id="lnum-aac084">♦</a>This cardinal’s more haughty than the devil.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aac085" id="lnum-aac085">85</a>
 <span class="sd-cn">Glou.</span> Mayor, farewell: thou dost but what thou mayst.</div>

<div class="dverse1"><span class="sd-cn">Win.</span> Abominable Gloucester, guard thy head;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac087" id="lnum-aac087">♦</a>
 For I intend to have it ere long.
 <span class="sd-verseend">[<i>Exeunt, severally, Gloucester and Winchester with their Serving-men.</i></span></div>

<div class="dverse1"><span class="sd-cn">May.</span> See the coast clear’d, and then we will depart.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aac089" id="lnum-aac089">♦</a>Good God, these nobles should such stomachs bear!</div>
<div class="dverse"><span class="lnum">90</span>
I myself fight not once in forty year. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section"><h4 class="h4main"><span class="dnavigate">aad</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>Orleans</i>.</h4>

<div class="sd-schg"><i>Enter, on the walls, a</i> Master
Gunner <i>and his</i> Boy.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aad001" id="lnum-aad001">♦</a>
 <span class="sd-cn">M. Gun.</span> Sirrah, thou know’st how Orleans is besieged,</div>
<div class="dverse">And how the English have the suburbs won.</div>

<div class="dverse1"><span class="sd-cn">Boy.</span> Father, I know; and oft have shot at them,</div>
<div class="dverse">Howe’er unfortunate I miss’d my aim.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">M. Gun.</span> But now thou shalt not. Be thou ruled by me:</div>
<div class="dverse">Chief master-gunner am I of this town;</div>
<div class="dverse">Something I must do to procure me grace.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad008" id="lnum-aad008">♦</a>The prince’s espials have informed me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad009" id="lnum-aad009">♦</a>How the English, in the suburbs close intrench’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad010" id="lnum-aad010">10</a>Wont through a secret grate of iron bars</div>
<div class="dverse">In yonder tower to overpeer the city</div>
<div class="dverse">And thence discover how with most advantage</div>
<div class="dverse">They may vex us with shot or with assault.</div>
<div class="dverse">To intercept this inconvenience,</div>
<div class="dverse"><span class="lnum">15</span>A piece of ordnance ’gainst it I have placed;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad016" id="lnum-aad016">♦</a>And even these three days have I watch’d,</div>
<div class="dverse">If I could see them.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad018" id="lnum-aad018">♦</a>Now do thou watch, for I can stay no longer.</div>
<div class="dverse">If thou spy’st any, run and bring me word;</div>
<div class="dverse"><span class="lnum">20</span> And thou shalt find me at the governor’s.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Boy.</span> Father, I warrant you; take you no care;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad022" id="lnum-aad022">♦</a>
I’ll never trouble you, if I may spy them. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Enter, on the turrets, the</i> <span class="smcaps">L<span>ORDS</span></span> <span class="smcaps">S<span>ALISBURY</span></span> <i>and</i>
<span class="smcaps">T<span>ALBOT</span>,</span>
<span class="smcaps">S<span>IR</span></span> <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">G<span>LANSDALE</span>,</span>
<span class="smcaps">S<span>IR</span></span> <span class="smcaps">T<span>HOMAS</span></span> <span class="smcaps">G<span>ARGRAVE</span>,</span> <i>and others</i>. </div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aad023" id="lnum-aad023">♦</a>
 <span class="sd-cn">Sal.</span> Talbot, my life, my joy, again return’d!</div>
<div class="dverse">How wert thou handled being prisoner?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad025" id="lnum-aad025">25</a>Or by what means got’st thou to be released?</div>
<div class="dverse">Discourse, I prithee, on this turret’s top.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aad027" id="lnum-aad027">♦</a>
 <span class="sd-cn">Tal.</span> The Duke of Bedford had a prisoner</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad028" id="lnum-aad028">♦</a>Call’d the brave Lord Ponton de Santrailles;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad029" id="lnum-aad029">♦</a>For him was I exchanged and ransomed.</div>
<div class="dverse"><span class="lnum">30</span>But with a baser man of arms by far</div>
<div class="dverse">Once in contempt they would have barter’d me:</div>
<div class="dverse">Which I disdaining scorn’d and craved death</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad033" id="lnum-aad033">♦</a>Rather than I would be so vile-esteem’d.</div>
<div class="dverse">In fine, redeem’d I was as I desired.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad035" id="lnum-aad035">35</a>But, O! the treacherous Fastolfe wounds my heart,</div>
<div class="dverse">Whom with my bare fists I would execute,</div>
<div class="dverse">If I now had him brought into my power.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span> Yet tell’st thou not how thou wert entertain’d.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span> With scoffs and scorns and contumelious taunts.</div>
<div class="dverse"><span class="lnum">40</span>In open market-place produced they me,</div>
<div class="dverse">To be a public spectacle to all:</div>
<div class="dverse">Here, said they, is the terror of the French,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad043" id="lnum-aad043">♦</a>The scarecrow that affrights our children so.</div>
<div class="dverse">Then broke I from the officers that led me,</div>
<div class="dverse"><span class="lnum">45</span>And with my nails digg’d stones out of the ground,</div>
<div class="dverse">To hurl at the beholders of my shame:</div>
<div class="dverse">My grisly countenance made others fly;</div>
<div class="dverse">None durst come near for fear of sudden death.</div>
<div class="dverse">In iron walls they deem’d me not secure;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad050" id="lnum-aad050">50</a>So great fear of my name ’mongst them was spread</div>
<div class="dverse">That they supposed I could rend bars of steel</div>
<div class="dverse">And spurn in pieces posts of adamant:</div>
<div class="dverse">Wherefore a guard of chosen shot I had</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad054" id="lnum-aad054">♦</a>That walked about me every minute while;</div>
<div class="dverse"><span class="lnum">55</span>And if I did but stir out of my bed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad056" id="lnum-aad056">♦</a>Ready they were to shoot me to the heart.</div>

<div class="sd-entry"><i>Enter the</i> Boy <i>with a linstock</i>.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span> I grieve to hear what torments you endured,</div>
<div class="dverse">But we will be revenged sufficiently.</div>
<div class="dverse">Now it is supper-time in Orleans:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad060" id="lnum-aad060">60</a>Here, through this grate, I count each one</div>
<div class="dverse">And view the Frenchmen how they fortify:</div>
<div class="dverse">Let us look in; the sight will much delight thee.</div>
<div class="dverse">Sir Thomas Gargrave, and Sir William Glansdale,</div>
<div class="dverse">Let me have your express opinions</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad065" id="lnum-aad065">65</a>Where is best place to make our battery next.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aad066" id="lnum-aad066">♦</a>
 <span class="sd-cn">Gar.</span> I think, at the north gate; for there stand lords.</div>

<div class="dverse1"><span class="sd-cn">Glan.</span> And I, here, at the bulwark of the bridge.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span> For aught I see, this city must be famish’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad069" id="lnum-aad069">♦</a>
 Or with light skirmishes enfeebled.
 <span class="sd-verseend">[<i>Here they shoot. Salisbury and Gargrave fall.</i></span></div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Sal.</span> O Lord, have mercy on us, wretched sinners!</div>

<div class="dverse1"><span class="sd-cn">Gar.</span> O Lord, have mercy on me, woful man!</div>

<div class="dverse1"><span class="sd-cn">Tal.</span> What chance is this that suddenly hath cross’d us?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad073" id="lnum-aad073">♦</a>Speak, Salisbury; at least, if thou canst speak:</div>
<div class="dverse">How farest thou, mirror of all martial men?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad075" id="lnum-aad075">75</a>One of thy eyes and thy cheek’s side struck off!</div>
<div class="dverse">Accursed tower! accursed fatal hand</div>
<div class="dverse">That hath contrived this woful tragedy!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad078" id="lnum-aad078">♦</a>In thirteen battles Salisbury o’ercame;</div>
<div class="dverse">Henry the Fifth he first train’d to the wars;</div>
<div class="dverse"><span class="lnum">80</span>Whilst any trump did sound, or drum struck up,</div>
<div class="dverse">His sword did ne’er leave striking in the field.</div>
<div class="dverse">Yet livest thou, Salisbury? though thy speech doth fail,</div>
<div class="dverse">One eye thou hast, to look to heaven for grace:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad084" id="lnum-aad084">♦</a>The sun with one eye vieweth all the world.</div>
<div class="dverse"><span class="lnum">85</span>Heaven, be thou gracious to none alive,</div>
<div class="dverse">If Salisbury wants mercy at thy hands!</div>
<div class="dverse">Bear hence his body; I will help to bury it.</div>
<div class="dverse">Sir Thomas Gargrave, hast thou any life?</div>
<div class="dverse">Speak unto Talbot; nay, look up to him.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad090" id="lnum-aad090">90</a>Salisbury, cheer thy spirit with this comfort;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad091" id="lnum-aad091">♦</a>Thou shalt not die whiles—</div>
<div class="dverse">He beckons with his hand and smiles on me,</div>
<div class="dverse">As who should say ‘When I am dead and gone,</div>
<div class="dverse">Remember to avenge me on the French.’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad095" id="lnum-aad095">95</a>Plantagenet, I will; and like thee, Nero,</div>
<div class="dverse">Play on the lute, beholding the towns burn:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad097" id="lnum-aad097">♦</a> Wretched shall France be only in my name.
 <span class="sd-verseend">[<i>Here an alarum, and it thunders and lightens.</i></span></div>
<div class="dverse">What stir is this? what tumult’s in the heavens?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad099" id="lnum-aad099">♦</a>Whence cometh this alarum, and the noise?</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Mess.</span>  My lord, my lord, the French have gather’d head:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad101" id="lnum-aad101">♦</a>The Dauphin, with one Joan la Pucelle join’d,</div>
<div class="dverse">A holy prophetess new risen up,</div>
<div class="dverse">Is come with a great power to raise the siege.
 <span class="sd-verseend">[<i>Here Salisbury lifteth himself up and groans.</i></span></div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
  Hear, hear how dying Salisbury doth groan!</div>
<div class="dverse"><span class="lnum">105</span>It irks his heart he cannot be revenged.</div>
<div class="dverse">Frenchmen, I’ll be a Salisbury to you:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad107" id="lnum-aad107">♦</a>Pucelle or puzzel, dolphin or dogfish,</div>
<div class="dverse">Your hearts I’ll stamp out with my horse’s heels,</div>
<div class="dverse">And make a quagmire of your mingled brains.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad110" id="lnum-aad110">110</a>Convey me Salisbury into his tent,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aad111" id="lnum-aad111">♦</a>
 And then we’ll try what these dastard Frenchmen dare.
 <span class="sd-verseend">[<i>Alarum. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aae</span>
<span class="smcaps">S<span>CENE</span></span> V. <i>The same</i>.</h4>

<div class="sd-schg"><i>Here an Alarum again: and</i> <span class="smcaps">T<span>ALBOT</span></span> <i>pursueth the</i> <span class="smcaps">D<span>AUPHIN</span>,</span> <i>and driveth him: then enter</i> <span class="smcaps">J<span>OAN</span></span>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <i>driving Englishmen before her, and exit after them: then re-enter</i> <span class="smcaps">T<span>ALBOT</span>.</span>
</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aae001" id="lnum-aae001">♦</a>
 <span class="sd-cn">Tal.</span>  Where is my strength, my valour, and my force?</div>
<div class="dverse">Our English troops retire, I cannot stay them;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aae003" id="lnum-aae003">♦</a>A woman clad in armour chaseth them.</div>

<div class="sd-entry"><i>Re-enter</i> <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span></span>.</div>

<div class="dverse">Here, here she comes. I’ll have a bout with thee;</div>
<div class="dverse"><span class="lnum">5</span>Devil or devil’s dam, I’ll conjure thee:</div>
<div class="dverse">Blood will I draw on thee, thou art a witch,</div>
<div class="dverse">And straightway give thy soul to him thou servest.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span> Come, come, ’tis only I that must disgrace thee.
 <span class="sd-verseend">[<i>Here they fight.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aae009" id="lnum-aae009">♦</a>
 <span class="sd-cn">Tal.</span> Heavens, can you suffer hell so to prevail?</div>
<div class="dverse"><span class="lnum">10</span>My breast I’ll burst with straining of my courage</div>
<div class="dverse">And from my shoulders crack my arms asunder,</div>
<div class="dverse">But I will chastise this high-minded strumpet.
 <span class="sd-verseend">[<i>They fight again.</i></span></div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Talbot, farewell; thy hour is not yet come:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aae014" id="lnum-aae014">♦</a>
 I must go victual Orleans forthwith.
 <span class="sd-verseend">[<i>A short alarum: then
 enter the town with soldiers.</i></span></div>
<div class="dverse"><span class="lnum">15</span>
 O’ertake me, if thou canst; I scorn thy strength.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aae016" id="lnum-aae016">♦</a>
 Go, go, cheer up thy hungry-starved men;</div>
<div class="dverse">Help Salisbury to make his testament:</div>
<div class="dverse">This day is ours, as many more shall be.
<span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Tal.</span> My thoughts are whirled like a potter’s wheel;</div>
<div class="dverse"><span class="lnum">20</span>I know not where I am, nor what I do:</div>
<div class="dverse">A witch, by fear, not force, like Hannibal,</div>
<div class="dverse">Drives back our troops and conquers as she lists:</div>
<div class="dverse">So bees with smoke and doves with noisome stench</div>
<div class="dverse">Are from their hives and houses driven away.</div>
<div class="dverse"><span class="lnum">25</span>They call’d us for our fierceness English dogs;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aae026" id="lnum-aae026">♦</a>
 Now, like to whelps, we crying run away.
 <span class="sd-verseend">[<i>A short alarum.</i></span></div>
<div class="dverse">Hark, countrymen! either renew the fight,</div>
<div class="dverse">Or tear the lions out of England’s coat;</div>
<div class="dverse">Renounce your soil, give sheep in lions’ stead:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aae030" id="lnum-aae030">30</a>Sheep run not half so treacherous from the wolf,</div>
<div class="dverse">Or horse or oxen from the leopard,</div>
<div class="dverse">As you fly from your oft-subdued slaves.
 <span class="sd-verseend">[<i>Alarum. Here another skirmish.</i></span></div>
<div class="dverse">It will not be: retire into your trenches:</div>
<div class="dverse">You all consented unto Salisbury’s death,</div>
<div class="dverse"><span class="lnum">35</span>For none would strike a stroke in his revenge.</div>
<div class="dverse">Pucelle is enter’d into Orleans,</div>
<div class="dverse">In spite of us or aught that we could do.</div>
<div class="dverse">O, would I were to die with Salisbury!</div>
<div class="dverse">The shame hereof will make me hide my head.
<span class="sd-verseend">[<i>Exit Talbot. Alarum; retreat; flourish.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aaf</span>
<span class="smcaps">S<span>CENE</span></span> VI. <i>The same</i>.</h4>

<div class="sd-schg"><i>Enter, on the walls</i>, <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <span class="smcaps">C<span>HARLES</span>,</span> <span class="smcaps">R<span>EIGNIER</span>,</span> <span class="smcaps">A<span>LENÇON</span>,</span> <i>and Soldiers</i>. </div>
</div>
<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaf001" id="lnum-aaf001">♦</a>
 <span class="sd-cn">Puc.</span> Advance our waving colours on the walls;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf002" id="lnum-aaf002">♦</a>Rescued is Orleans from the English:</div>
<div class="dverse">Thus Joan la Pucelle hath perform’d her word.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaf004" id="lnum-aaf004">♦</a>
 <span class="sd-cn">Char.</span> Divinest creature, Astræa’s daughter,</div>
<div class="dverse"><span class="lnum">5</span>How shall I honour thee for this success?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf006" id="lnum-aaf006">♦</a>Thy promises are like Adonis’ gardens</div>
<div class="dverse">That one day bloom’d and fruitful were the next.</div>
<div class="dverse">France, triumph in thy glorious prophetess!</div>
<div class="dverse">Recover’d is the town of Orleans:</div>
<div class="dverse"><span class="lnum">10</span>More blessed hap did ne’er befall our state.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aaf011" id="lnum-aaf011">♦</a>
 <span class="sd-cn">Reig.</span> Why ring not out the bells aloud throughout the  town?</div>
<div class="dverse">Dauphin, command the citizens make bonfires</div>
<div class="dverse">And feast and banquet in the open streets,</div>
<div class="dverse">To celebrate the joy that God hath given us.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Alen.</span> All France will be replete with mirth and joy,</div>
<div class="dverse">When they shall hear how we have play’d the men.</div>

<div class="dverse1"><span class="sd-cn">Char.</span> ’Tis Joan, not we, by whom the day is won;</div>
<div class="dverse">For which I will divide my crown with her,</div>
<div class="dverse">And all the priests and friars in my realm</div>
<div class="dverse"><span class="lnum">20</span>Shall in procession sing her endless praise.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf021" id="lnum-aaf021">♦</a>A statelier pyramis to her I’ll rear</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf022" id="lnum-aaf022">♦</a>Than Rhodope’s or Memphis’ ever was:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf023" id="lnum-aaf023">♦</a> In memory of her when she is dead,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf024" id="lnum-aaf024">♦</a> Her ashes, in an urn more precious</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf025" id="lnum-aaf025">25</a> Than the rich-jewel’d coffer of Darius,</div>
<div class="dverse">Transported shall be at high festivals</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aaf027" id="lnum-aaf027">♦</a> Before the kings and queens of France.</div>
<div class="dverse">No longer on Saint Denis will we cry,</div>
<div class="dverse">But Joan la Pucelle shall be France’s saint.</div>
<div class="dverse"><span class="lnum">30</span> Come in, and let us banquet royally,</div>
<div class="dverse">After this golden day of victory.
 <span class="sd-inline">[<i>Flourish. Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT II.</h3>

<h4 class="h4main"><span class="dnavigate">aba</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>Before Orleans</i>.</h4>

<div class="sd-schg"><i>Enter a</i> Sergeant <i>of a band, with two</i>
Sentinels.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba001" id="lnum-aba001">♦</a>
 <span class="sd-cn">Serg.</span>  Sirs, take your places and be vigilant:</div>
<div class="dverse">If any noise or soldier you perceive</div>
<div class="dverse">Near to the walls, by some apparent sign</div>
<div class="dverse">Let us have knowledge at the court of guard.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">First Sent.</span> Sergeant, you shall.
 <span class="sd-inline">[<i>Exit Sergeant</i>.]</span> Thus are poor servitors,</div>
<div class="dverse">When others sleep upon their quiet beds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aba007" id="lnum-aba007">♦</a>
 Constrain’d to watch in darkness, rain and cold.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">T<span>ALBOT</span>,</span>
<span class="smcaps">B<span>EDFORD</span>,</span> <span class="smcaps">B<span>URGUNDY</span>,</span> <i>and forces, with scaling-ladders, their drums beating a dead march</i>. </div>

<div class="dverse1"><span class="sd-cn">Tal.</span> Lord Regent, and redoubted Burgundy,</div>
<div class="dverse">By whose approach the regions of Artois,</div>
<div class="dverse"><span class="lnum">10</span> Wallon and Picardy are friends to us,</div>
<div class="dverse">This happy night the Frenchmen are secure,</div>
<div class="dverse">Having all day caroused and banqueted:</div>
<div class="dverse">Embrace we then this opportunity</div>
<div class="dverse">As fitting best to quittance their deceit</div>
<div class="dverse"><span class="lnum">15</span> Contrived by art and baleful sorcery.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span> Coward of France! how much he wrongs his fame,</div>
<div class="dverse">Despairing of his own arm’s fortitude,</div>
<div class="dverse">To join with witches and the help of hell!</div>

<div class="dverse1"><span class="sd-cn">Bur.</span> Traitors have never other company.</div>
<div class="dverse"><span class="lnum">20</span> But what’s that Pucelle whom they term so pure?</div>

<div class="dverse1"><span class="sd-cn">Tal.</span> A maid, they say.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span>
 <span class="i10"> </span>
 A maid! and be so martial!</div>

<div class="dverse1"><span class="sd-cn">Bur.</span> Pray God she prove not masculine ere long,</div>
<div class="dverse">If underneath the standard of the French</div>
<div class="dverse">She carry armour as she hath begun.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Tal.</span>  Well, let them practise and converse with spirits:</div>
<div class="dverse">God is our fortress, in whose conquering name</div>
<div class="dverse">Let us resolve to scale their flinty bulwarks.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span> Ascend, brave Talbot; we will follow thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba029" id="lnum-aba029">♦</a>
 <span class="sd-cn">Tal.</span>  Not all together: better far, I guess,</div>
<div class="dverse"><span class="lnum">30</span> That we do make our entrance several ways;</div>
<div class="dverse">That, if it chance the one of us do fail,</div>
<div class="dverse">The other yet may rise against their force.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span> Agreed: I’ll to yond corner.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
<span class="i16"> </span><a class="lnum pginternal" href="#lnote-aba033" id="lnum-aba033">♦</a>
And I to this. </div>

<div class="dverse1"><span class="sd-cn">Tal.</span> And here will Talbot mount, or make his grave.</div>
<div class="dverse"><span class="lnum">35</span> Now, Salisbury, for thee, and for the right</div>
<div class="dverse">Of English Henry, shall this night appear</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aba037" id="lnum-aba037">♦</a>
 How much in duty I am bound to both.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba038" id="lnum-aba038">♦</a>
 <span class="sd-cn">Sent.</span>
 Arm! arm! the enemy doth make assault!
 <span class="sd-verseend">[<i>Cry: ‘St George,’ ‘A Talbot.’</i></span></div>

<div class="sd-entry"><i>The French leap over the walls in their shirts. Enter, several ways, the</i> <span class="smcaps">B<span>ASTARD</span></span> of Orleans, <span class="smcaps">A<span>LENÇON</span>,</span> <i>and</i> <span class="smcaps">R<span>EIGNIER</span>,</span> <i>half ready, and half unready</i>. </div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba039" id="lnum-aba039">♦</a>
 <span class="sd-cn">Alen.</span>  How now, my lords! what, all unready so?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba040" id="lnum-aba040">40</a>
 <span class="sd-cn">Bast.</span>  Unready! ay, and glad we ’scaped so well.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> ’Twas time, I trow, to wake and leave our beds,</div>
<div class="dverse">Hearing alarums at our chamber-doors.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span> Of all exploits since first I follow’d arms,</div>
<div class="dverse">Ne’er heard I of a warlike enterprise</div>
<div class="dverse"><span class="lnum">45</span> More venturous or desperate than this.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba046" id="lnum-aba046">♦</a>
 <span class="sd-cn">Bast.</span>  I think this Talbot be a fiend of hell.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span> If not of hell, the heavens, sure, favour him.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span> Here cometh Charles: I marvel how he sped.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba049" id="lnum-aba049">♦</a>
 <span class="sd-cn">Bast.</span>  Tut, holy Joan was his defensive guard.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>HARLES</span></span>
<i>and</i> <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>.</span>
</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Char.</span>  Is this thy cunning, thou deceitful dame?</div>
<div class="dverse">Didst thou at first, to flatter us withal,</div>
<div class="dverse">Make us partakers of a little gain,</div>
<div class="dverse">That now our loss might be ten times so much?</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Wherefore is Charles impatient with his friend?</div>
<div class="dverse"><span class="lnum">55</span> At all times will you have my power alike?</div>
<div class="dverse">Sleeping or waking must I still prevail,</div>
<div class="dverse">Or will you blame and lay the fault on me?</div>
<div class="dverse">Improvident soldiers! had your watch been good,</div>
<div class="dverse">This sudden mischief never could have fall’n.</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Char.</span>  Duke of Alençon, this was your default,</div>
<div class="dverse">That, being captain of the watch to-night,</div>
<div class="dverse">Did look no better to that weighty charge.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba063" id="lnum-aba063">♦</a>
 <span class="sd-cn">Alen.</span>  Had all your quarters been as safely kept</div>
<div class="dverse">As that whereof I had the government,</div>
<div class="dverse"><span class="lnum">65</span> We had not been thus shamefully surprised.</div>

<div class="dverse1"><span class="sd-cn">Bast.</span> Mine was secure.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
  <span class="i09"> </span>
  And so was mine, my lord.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 And, for myself, most part of all this night,</div>
<div class="dverse">Within her quarter and mine own precinct</div>
<div class="dverse">I was employ’d in passing to and fro,</div>
<div class="dverse"><span class="lnum">70</span> About relieving of the sentinels:</div>
<div class="dverse">Then how or which way should they first break in?</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Question, my lords, no further of the case,</div>
<div class="dverse">How or which way: ’tis sure they found some place</div>
<div class="dverse">But weakly guarded, where the breach was made.</div>
<div class="dverse"><span class="lnum">75</span> And now there rests no other shift but this;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aba076" id="lnum-aba076">♦</a> To gather our soldiers, scatter’d and dispersed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aba077" id="lnum-aba077">♦</a> And lay new platforms to endamage them.</div>

<div class="sd-entry"><i>Alarum. Enter an</i> English Soldier, <i>crying ‘A Talbot! a Talbot!’ They fly, leaving their clothes behind</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aba078" id="lnum-aba078">♦</a>
 <span class="sd-cn">Sold.</span>  I’ll be so bold to take what they have left.</div>
<div class="dverse">The cry of Talbot serves me for a sword;</div>
<div class="dverse"><span class="lnum">80</span> For I have loaden me with many spoils,</div>
<div class="dverse">Using no other weapon but his name.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">abb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>Orleans.
Within the town</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">T<span>ALBOT</span>,</span>
<span class="smcaps">B<span>EDFORD</span>,</span> <span class="smcaps">B<span>URGUNDY</span>,</span> <i>a</i> Captain, <i>and others</i>. </div>
</div>
<div class="dverse1"><a class="lnum pginternal" href="#lnote-abb001" id="lnum-abb001">♦</a>
 <span class="sd-cn">Bed.</span>  The day begins to break, and night is fled,</div>
<div class="dverse">Whose pitchy mantle over-veil’d the earth.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb003" id="lnum-abb003">♦</a>
 Here sound retreat, and cease our hot pursuit.
 <span class="sd-verseend">[<i>Retreat sounded.</i></span></div>

<div class="dverse1"><span class="sd-cn">Tal.</span> Bring forth the body of old Salisbury,</div>
<div class="dverse"><span class="lnum">5</span> And here advance it in the market-place,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb006" id="lnum-abb006">♦</a> The middle centre of this cursed town.</div>
<div class="dverse">Now have I paid my vow unto his soul;</div>
<div class="dverse">For every drop of blood was drawn from him</div>
<div class="dverse">There hath at least five Frenchmen died to-night.</div>
<div class="dverse"><span class="lnum">10</span> And that hereafter ages may behold</div>
<div class="dverse">What ruin happen’d in revenge of him,</div>
<div class="dverse">Within their chiefest temple I’ll erect</div>
<div class="dverse">A tomb, wherein his corpse shall be interr’d:</div>
<div class="dverse">Upon the which, that every one may read,</div>
<div class="dverse"><span class="lnum">15</span> Shall be engraved the sack of Orleans,</div>
<div class="dverse">The treacherous manner of his mournful death</div>
<div class="dverse">And what a terror he had been to France.</div>
<div class="dverse">But, lords, in all our bloody massacre,</div>
<div class="dverse">I muse we met not with the Dauphin’s grace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb020" id="lnum-abb020">20</a> His new-come champion, virtuous Joan of Arc,</div>
<div class="dverse">Nor any of his false confederates.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span>
 ’Tis thought, Lord Talbot, when the fight began,</div>
<div class="dverse">Roused on the sudden from their drowsy beds,</div>
<div class="dverse">They did amongst the troops of armed men</div>
<div class="dverse"><span class="lnum">25</span> Leap o’er the walls for refuge in the field.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Myself, as far as I could well discern</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb027" id="lnum-abb027">♦</a> For smoke and dusky vapours of the night,</div>
<div class="dverse">Am sure I scared the Dauphin and his trull,</div>
<div class="dverse">When arm in arm they both came swiftly running,</div>
<div class="dverse"><span class="lnum">30</span> Like to a pair of loving turtle-doves</div>
<div class="dverse">That could not live asunder day or night.</div>
<div class="dverse">After that things are set in order here,</div>
<div class="dverse">We’ll follow them with all the power we have.</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abb034" id="lnum-abb034">♦</a>
 <span class="sd-cn">Mess.</span>  All hail, my lords! Which of this princely train</div>
<div class="dverse"><span class="lnum">35</span> Call ye the warlike Talbot, for his acts</div>
<div class="dverse">So much applauded through the realm of France?</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Here is the Talbot: who would speak with him?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abb038" id="lnum-abb038">♦</a>
 <span class="sd-cn">Mess.</span>  The virtuous lady, Countess of Auvergne,</div>
<div class="dverse">With modesty admiring thy renown,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb040" id="lnum-abb040">40</a> By me entreats, great lord, thou wouldst vouchsafe</div>
<div class="dverse">To visit her poor castle where she lies,</div>
<div class="dverse">That she may boast she hath beheld the man</div>
<div class="dverse">Whose glory fills the world with loud report.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Is it even so? Nay, then, I see our wars</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb045" id="lnum-abb045">45</a> Will turn unto a peaceful comic sport,</div>
<div class="dverse">When ladies crave to be encounter’d with.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb047" id="lnum-abb047">♦</a> You may not, my lord, despise her gentle suit.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abb048" id="lnum-abb048">♦</a>
 <span class="sd-cn">Tal.</span>  Ne’er trust me then; for when a world of men</div>
<div class="dverse">Could not prevail with all their oratory,</div>
<div class="dverse"><span class="lnum">50</span> Yet hath a woman’s kindness over-ruled:</div>
<div class="dverse">And therefore tell her I return great thanks,</div>
<div class="dverse">And in submission will attend on her.</div>
<div class="dverse">Will not your honours bear me company?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abb054" id="lnum-abb054">♦</a>
 <span class="sd-cn">Bed.</span>  No, truly; it is more than manners will:</div>
<div class="dverse"><span class="lnum">55</span> And I have heard it said, unbidden guests</div>
<div class="dverse">Are often welcomest when they are gone.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Well then, alone, since there’s no remedy,</div>
<div class="dverse">I mean to prove this lady’s courtesy.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abb059" id="lnum-abb059">♦</a>
 Come hither, captain.
 <span class="sd-inline">[<i>Whispers.</i>]</span>
 You perceive my mind?</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Capt.</span>
 I do, my lord, and mean accordingly.
<span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">abc</span>
<span class="smcaps">S<span>CENE</span></span> III.
 <i>Auvergne. The Countess’s castle</i>.</h4>

<div class="sd-schg"><i>Enter the</i>
<span class="smcaps">C<span>OUNTESS</span></span> <i>and her</i>
Porter.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc001" id="lnum-abc001">♦</a>
 <span class="sd-cn">Count.</span>  Porter, remember what I gave in charge;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc002" id="lnum-abc002">♦</a> And when you have done so, bring the keys to me.</div>

<div class="dverse1"><span class="sd-cn">Port.</span>
 Madam, I will. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 The plot is laid: if all things fall out right,</div>
<div class="dverse"><span class="lnum">5</span> I shall as famous be by this exploit</div>
<div class="dverse">As Scythian Tomyris by Cyrus’ death.</div>
<div class="dverse">Great is the rumour of this dreadful knight,</div>
<div class="dverse">And his achievements of no less account:</div>
<div class="dverse">Fain would mine eyes be witness with mine ears,</div>
<div class="dverse"><span class="lnum">10</span>
 To give their censure of these rare reports. </div>

<div class="sd-entry"><i>Enter</i> Messenger <i>and</i>
<span class="smcaps">T<span>ALBOT</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc011" id="lnum-abc011">♦</a>
 <span class="sd-cn">Mess.</span>  Madam,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc012" id="lnum-abc012">♦</a> According as your ladyship desired,</div>
<div class="dverse">By message craved, so is Lord Talbot come.</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 And he is welcome. What! is this the man?</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 Madam, it is.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Count.</span>
 <span class="i07"> </span> Is this the scourge of France?</div>
<div class="dverse">Is this the Talbot, so much fear’d abroad</div>
<div class="dverse">That with his name the mothers still their babes?</div>
<div class="dverse">I see report is fabulous and false:</div>
<div class="dverse">I thought I should have seen some Hercules,</div>
<div class="dverse"><span class="lnum">20</span> A second Hector, for his grim aspect,</div>
<div class="dverse">And large proportion of his strong-knit limbs.</div>
<div class="dverse">Alas, this is a child, a silly dwarf!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc023" id="lnum-abc023">♦</a> It cannot be this weak and writhled shrimp</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc024" id="lnum-abc024">♦</a> Should strike such terror to his enemies.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Tal.</span> Madam, I have been bold to trouble you;</div>
<div class="dverse">But since your ladyship is not at leisure,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc027" id="lnum-abc027">♦</a> I’ll sort some other time to visit you.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc028" id="lnum-abc028">♦</a>
 <span class="sd-cn">Count.</span>  What means he now? Go ask him whither he goes.</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 Stay, my Lord Talbot; for my lady craves</div>
<div class="dverse"><span class="lnum">30</span> To know the cause of your abrupt departure.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Marry, for that she’s in a wrong belief,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc032" id="lnum-abc032">♦</a> I go to certify her Talbot’s here.</div>

<div class="sd-entry"><i>Re-enter</i> Porter <i>with keys</i>.</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 If thou be he, then art thou prisoner.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Prisoner! to whom?</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 <span class="i09"> </span> To me, blood-thirsty lord;</div>
<div class="dverse"><span class="lnum">35</span> And for that cause I train’d thee to my house.</div>
<div class="dverse">Long time thy shadow hath been thrall to me,</div>
<div class="dverse">For in my gallery thy picture hangs:</div>
<div class="dverse">But now the substance shall endure the like,</div>
<div class="dverse">And I will chain these legs and arms of thine,</div>
<div class="dverse"><span class="lnum">40</span> That hast by tyranny these many years</div>
<div class="dverse">Wasted our country, slain our citizens</div>
<div class="dverse">And sent our sons and husbands captivate.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Ha, ha, ha!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc044" id="lnum-abc044">♦</a>
 <span class="sd-cn">Count.</span>  Laughest thou, wretch? thy mirth shall turn to moan.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Tal.</span>  I laugh to see your ladyship so fond</div>
<div class="dverse">To think that you have aught but Talbot’s shadow</div>
<div class="dverse">Whereon to practise your severity.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc048" id="lnum-abc048">♦</a>
 <span class="sd-cn">Count.</span>  Why, art not thou the man?</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 <span class="i16"> </span>
 I am indeed.</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 Then have I substance too.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Tal.</span>  No, no, I am but shadow of myself:</div>
<div class="dverse">You are deceived, my substance is not here;</div>
<div class="dverse">For what you see is but the smallest part</div>
<div class="dverse">And least proportion of humanity:</div>
<div class="dverse">I tell you, madam, were the whole frame here,</div>
<div class="dverse"><span class="lnum">55</span> It is of such a spacious lofty pitch,</div>
<div class="dverse">Your roof were not sufficient to contain ’t.</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 This is a riddling merchant for the nonce;</div>
<div class="dverse">He will be here, and yet he is not here:</div>
<div class="dverse">How can these contrarieties agree?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc060" id="lnum-abc060">60</a>
 <span class="sd-cn">Tal.</span>
 That will I show you presently.
 <span class="sd-verseend">[<i>Winds his horn. Drums strike up: a peal of ordnance. Enter Soldiers.</i></span></div>
<div class="dverse">How say you, madam? are you now persuaded</div>
<div class="dverse">That Talbot is but shadow of himself?</div>
<div class="dverse">These are his substance, sinews, arms and strength,</div>
<div class="dverse">With which he yoketh your rebellious necks,</div>
<div class="dverse"><span class="lnum">65</span> Razeth your cities and subverts your towns</div>
<div class="dverse">And in a moment makes them desolate.</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 Victorious Talbot! pardon my abuse:</div>
<div class="dverse">I find thou art no less than fame hath bruited</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc069" id="lnum-abc069">♦</a> And more than may be gather’d by thy shape.</div>
<div class="dverse"><span class="lnum">70</span> Let my presumption not provoke thy wrath;</div>
<div class="dverse">For I am sorry that with reverence</div>
<div class="dverse">I did not entertain thee as thou art.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abc073" id="lnum-abc073">♦</a>
 <span class="sd-cn">Tal.</span>  Be not dismay’d, fair lady; nor misconstrue</div>
<div class="dverse">The mind of Talbot, as you did mistake</div>
<div class="dverse"><span class="lnum">75</span> The outward composition of his body.</div>
<div class="dverse">What you have done hath not offended me;</div>
<div class="dverse">Nor other satisfaction do I crave,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abc078" id="lnum-abc078">♦</a> But only, with your patience, that we may</div>
<div class="dverse">Taste of your wine and see what cates you have;</div>
<div class="dverse"><span class="lnum">80</span> For soldiers’ stomachs always serve them well.</div>

<div class="dverse1"><span class="sd-cn">Count.</span>
 With all my heart, and think me honoured</div>
<div class="dverse">To feast so great a warrior in my house.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">abd</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>London.
The Temple-garden</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">E<span>ARLS</span></span> of <span class="smcaps">S<span>OMERSET</span>,</span> <span class="smcaps">S<span>UFFOLK</span>,</span> <i>and</i>
<span class="smcaps">W<span>ARWICK</span>;</span>
<span class="smcaps">R<span>ICHARD</span></span>
<span class="smcaps">P<span>LANTAGENET</span>,</span>
<span class="smcaps">V<span>ERNON</span>,</span> <i>and another</i>
Lawyer.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd001" id="lnum-abd001">♦</a>
 <span class="sd-cn">Plan.</span>  Great lords and gentlemen, what means this silence?</div>
<div class="dverse">Dare no man answer in a case of truth?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Within the Temple-hall we were too loud;</div>
<div class="dverse">The garden here is more convenient.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Plan.</span>  Then say at once if I maintain’d the truth;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd006" id="lnum-abd006">♦</a> Or else was wrangling Somerset in the error?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Faith, I have been a truant in the law,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd008" id="lnum-abd008">♦</a> And never yet could frame my will to it;</div>
<div class="dverse">And therefore frame the law unto my will.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Som.</span>  Judge you, my lord of Warwick, then, between us.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Between two hawks, which flies the higher pitch;</div>
<div class="dverse">Between two dogs, which hath the deeper mouth;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd013" id="lnum-abd013">♦</a> Between two blades, which bears the better temper:</div>
<div class="dverse">Between two horses, which doth bear him best;</div>
<div class="dverse"><span class="lnum">15</span> Between two girls, which hath the merriest eye;</div>
<div class="dverse">I have perhaps some shallow spirit of judgement:</div>
<div class="dverse">But in these nice sharp quillets of the law,</div>
<div class="dverse">Good faith, I am no wiser than a daw.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 Tut, tut, here is a mannerly forbearance:</div>
<div class="dverse"><span class="lnum">20</span> The truth appears so naked on my side</div>
<div class="dverse">That any purblind eye may find it out.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 And on my side it is so well apparell’d,</div>
<div class="dverse">So clear, so shining and so evident</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd024" id="lnum-abd024">♦</a> That it will glimmer through a blind man’s eye.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Plan.</span>  Since you are tongue-tied and so loath to speak,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd026" id="lnum-abd026">♦</a> In dumb significants proclaim your thoughts:</div>
<div class="dverse">Let him that is a true-born gentleman,</div>
<div class="dverse">And stands upon the honour of his birth,</div>
<div class="dverse">If he suppose that I have pleaded truth,</div>
<div class="dverse"><span class="lnum">30</span> From off this brier pluck a white rose with me.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd031" id="lnum-abd031">♦</a>
 <span class="sd-cn">Som.</span>  Let him that is no coward nor no flatterer,</div>
<div class="dverse">But dare maintain the party of the truth,</div>
<div class="dverse">Pluck a red rose from off this thorn with me.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 I love no colours, and without all colour</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd035" id="lnum-abd035">35</a> Of base insinuating flattery</div>
<div class="dverse">I pluck this white rose with Plantagenet.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I pluck this red rose with young Somerset</div>
<div class="dverse">And say withal I think he held the right.</div>

<div class="dverse1"><span class="sd-cn">Ver.</span>
 Stay, lords and gentlemen, and pluck no more,</div>
<div class="dverse"><span class="lnum">40</span> Till you conclude that he upon whose side</div>
<div class="dverse">The fewest roses are cropp’d from the tree</div>
<div class="dverse">Shall yield the other in the right opinion.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Good Master Vernon, it is well objected:</div>
<div class="dverse">If I have fewest, I subscribe in silence.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Plan.</span>  And I.</div>

<div class="dverse1"><span class="sd-cn">Ver.</span>
 Then for the truth and plainness of the case,</div>
<div class="dverse">I pluck this pale and maiden blossom here,</div>
<div class="dverse">Giving my verdict on the white rose side.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd049" id="lnum-abd049">♦</a>
 <span class="sd-cn">Som.</span>  Prick not your finger as you pluck it off,</div>
<div class="dverse"><span class="lnum">50</span> Lest bleeding you do paint the white rose red</div>
<div class="dverse">And fall on my side so, against your will.</div>

<div class="dverse1"><span class="sd-cn">Ver.</span>
 If I, my lord, for my opinion bleed,</div>
<div class="dverse">Opinion shall be surgeon to my hurt</div>
<div class="dverse">And keep me on the side where still I am.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Som.</span>  Well, well, come on: who else?</div>

<div class="dverse1"><span class="sd-cn">Law.</span>
 Unless my study and my books be false,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd057" id="lnum-abd057">♦</a>
The argument you held was wrong in you;
<span class="sd-inline">[<i>To Somerset.</i></span></div>
<div class="dverse">In sign whereof I pluck a white rose too.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 Now, Somerset, where is your argument?</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Som.</span>  Here in my scabbard, meditating that</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd061" id="lnum-abd061">♦</a>
Shall dye your white rose in a bloody red.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd062" id="lnum-abd062">♦</a>
 <span class="sd-cn">Plan.</span>
Meantime your cheeks do counterfeit our roses;</div>
<div class="dverse">For pale they look with fear, as witnessing</div>
<div class="dverse">The truth on our side.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 <span class="i09"> </span>  No, Plantagenet,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd065" id="lnum-abd065">65</a>
’Tis not for fear but anger that thy cheeks</div>
<div class="dverse">Blush for pure shame to counterfeit our roses,</div>
<div class="dverse">And yet thy tongue will not confess thy error.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 Hath not thy rose a canker, Somerset?</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Hath not thy rose a thorn, Plantagenet?</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Plan.</span>  Ay, sharp and piercing, to maintain his truth;</div>
<div class="dverse">Whiles thy consuming canker eats his falsehood.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Well, I’ll find friends to wear my bleeding roses,</div>
<div class="dverse">That shall maintain what I have said is true,</div>
<div class="dverse">Where false Plantagenet dare not be seen.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Plan.</span>  Now, by this maiden blossom in my hand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd076" id="lnum-abd076">♦</a>
I scorn thee and thy fashion, peevish boy.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Turn not thy scorns this way, Plantagenet.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 Proud Pole, I will, and scorn both him and thee.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I’ll turn my part thereof into thy throat.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Som.</span>  Away, away, good William de la Pole!</div>
<div class="dverse">We grace the yeoman by conversing with him.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Now, by God’s will, thou wrong’st him, Somerset;</div>
<div class="dverse">His grandfather was Lionel Duke of Clarence,</div>
<div class="dverse">Third son to the third Edward King of England:</div>
<div class="dverse"><span class="lnum">85</span> Spring crestless yeomen from so deep a root?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd086" id="lnum-abd086">♦</a>
 <span class="sd-cn">Plan.</span>
He bears him on the place’s privilege,</div>
<div class="dverse">Or durst not, for his craven heart, say thus.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 By him that made me, I’ll maintain my words</div>
<div class="dverse">On any plot of ground in Christendom.</div>
<div class="dverse"><span class="lnum">90</span> Was not thy father, Richard Earl of Cambridge,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd091" id="lnum-abd091">♦</a>
For treason executed in our late king’s days?</div>
<div class="dverse">And, by his treason, stand’st not thou attainted,</div>
<div class="dverse">Corrupted, and exempt from ancient gentry?</div>
<div class="dverse">His trespass yet lives guilty in thy blood;</div>
<div class="dverse"><span class="lnum">95</span> And, till thou be restored, thou art a yeoman.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 My father was attached, not attainted,</div>
<div class="dverse">Condemn’d to die for treason, but no traitor;</div>
<div class="dverse">And that I’ll prove on better men than Somerset,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd099" id="lnum-abd099">♦</a>
Were growing time once ripen’d to my will.</div>
<div class="dverse"><span class="lnum">100</span> For your partaker Pole and you yourself,</div>
<div class="dverse">I’ll note you in my book of memory,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd102" id="lnum-abd102">♦</a>
To scourge you for this apprehension:</div>
<div class="dverse">Look to it well and say you are well warn’d.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Ah, thou shalt find us ready for thee still;</div>
<div class="dverse"><span class="lnum">105</span> And know us by these colours for thy foes,</div>
<div class="dverse">For these my friends in spite of thee shall wear.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 And, by my soul, this pale and angry rose,</div>
<div class="dverse">As cognizance of my blood-drinking hate,</div>
<div class="dverse">Will I for ever and my faction wear,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd110" id="lnum-abd110">110</a>
Until it wither with me to my grave</div>
<div class="dverse">Or flourish to the height of my degree.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Go forward and be choked with thy ambition!</div>
<div class="dverse">And so farewell until I meet thee next.
<span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Have with thee, Pole.  Farewell, ambitious Richard.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="lnum">115</span>
 <span class="sd-cn">Plan.</span>  How I am braved and must perforce endure it!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 This blot that they object against your house</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd117" id="lnum-abd117">♦</a>
Shall be wiped out in the next parliament</div>
<div class="dverse">Call’d for the truce of Winchester and Gloucester;</div>
<div class="dverse">And if thou be not then created York,</div>
<div class="dverse"><span class="lnum">120</span> I will not live to be accounted Warwick.</div>
<div class="dverse">Meantime, in signal of my love to thee,</div>
<div class="dverse">Against proud Somerset and William Pole,</div>
<div class="dverse">Will I upon thy party wear this rose:</div>
<div class="dverse">And here I prophesy: this brawl to-day,</div>
<div class="dverse"><span class="lnum">125</span> Grown to this faction in the Temple-garden,</div>
<div class="dverse">Shall send between the red rose and the white</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abd127" id="lnum-abd127">♦</a>
A thousand souls to death and deadly night.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd128" id="lnum-abd128">♦</a>
 <span class="sd-cn">Plan.</span>
Good Master Vernon, I am bound to you,</div>
<div class="dverse">That you on my behalf would pluck a flower.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Ver.</span>  In your behalf still will I wear the same.</div>

<div class="dverse1"><span class="sd-cn">Law.</span>
 And so will I.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abd132" id="lnum-abd132">♦</a>
 <span class="sd-cn">Plan.</span>
Thanks, gentle sir.</div>
<div class="dverse">Come, let us four to dinner: I dare say</div>
<div class="dverse">This quarrel will drink blood another day.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">abe</span>
<span class="smcaps">S<span>CENE</span></span> V.
<i>The Tower of London</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">M<span>ORTIMER</span>,</span> <i>brought in a chair, and</i>
Gaolers.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe001" id="lnum-abe001">♦</a>
 <span class="sd-cn">Mor.</span>
Kind keepers of my weak decaying age,</div>
<div class="dverse">Let dying Mortimer here rest himself.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe003" id="lnum-abe003">♦</a>
Even like a man new haled from the rack,</div>
<div class="dverse">So fare my limbs with long imprisonment;</div>
<div class="dverse"><span class="lnum">5</span> And these grey locks, the pursuivants of death,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe006" id="lnum-abe006">♦</a>
Nestor-like aged in an age of care,</div>
<div class="dverse">Argue the end of Edmund Mortimer.</div>
<div class="dverse">These eyes, like lamps whose wasting oil is spent,</div>
<div class="dverse">Wax dim, as drawing to their exigent;</div>
<div class="dverse"><span class="lnum">10</span> Weak shoulders, overborne with burthening grief,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe011" id="lnum-abe011">♦</a>
And pithless arms, like to a wither’d vine</div>
<div class="dverse">That droops his sapless branches to the ground:</div>
<div class="dverse">Yet are these feet, whose strengthless stay is numb,</div>
<div class="dverse">Unable to support this lump of clay,</div>
<div class="dverse"><span class="lnum">15</span> Swift-winged with desire to get a grave,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe016" id="lnum-abe016">♦</a>
As witting I no other comfort have.</div>
<div class="dverse">But tell me, keeper, will my nephew come?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe018" id="lnum-abe018">♦</a>
 <span class="sd-cn">First Gaol.</span>
Richard Plantagenet, my lord, will come:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe019" id="lnum-abe019">♦</a>
We sent unto the Temple, unto his chamber;</div>
<div class="dverse"><span class="lnum">20</span> And answer was return’d that he will come.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe021" id="lnum-abe021">♦</a>
 <span class="sd-cn">Mor.</span>
Enough: my soul shall then be satisfied.</div>
<div class="dverse">Poor gentleman! his wrong doth equal mine.</div>
<div class="dverse">Since Henry Monmouth first began to reign,</div>
<div class="dverse">Before whose glory I was great in arms,</div>
<div class="dverse"><span class="lnum">25</span> This loathsome sequestration have I had;</div>
<div class="dverse">And even since then hath Richard been obscured,</div>
<div class="dverse">Deprived of honour and inheritance.</div>
<div class="dverse">But now the arbitrator of despairs,</div>
<div class="dverse">Just death, kind umpire of men’s miseries,</div>
<div class="dverse"><span class="lnum">30</span> With sweet enlargement doth dismiss me hence:</div>
<div class="dverse">I would his troubles likewise were expired,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe032" id="lnum-abe032">♦</a>
That so he might recover what was lost.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">R<span>ICHARD</span></span> <span class="smcaps">P<span>LANTAGENET</span>.</span></div>

<div class="dverse1"><span class="sd-cn">First Gaol.</span>
 My lord, your loving nephew now is come.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe034" id="lnum-abe034">♦</a>
 <span class="sd-cn">Mor.</span>
Richard Plantagenet, my friend, is he come?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe035" id="lnum-abe035">35</a>
 <span class="sd-cn">Plan.</span>
Ay, noble uncle, thus ignobly used,</div>
<div class="dverse">Your nephew, late despised Richard, comes.</div>

<div class="dverse1"><span class="sd-cn">Mor.</span>
 Direct mine arms I may embrace his neck,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe038" id="lnum-abe038">♦</a>
And in his bosom spend my latter gasp:</div>
<div class="dverse">O, tell me when my lips do touch his cheeks,</div>
<div class="dverse"><span class="lnum">40</span> That I may kindly give one fainting kiss.</div>
<div class="dverse">And now declare, sweet stem from York’s great stock,</div>
<div class="dverse">Why didst thou say, of late thou wert despised?</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 First, lean thine aged back against mine arm;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe044" id="lnum-abe044">♦</a>
And, in that ease, I’ll tell thee my disease.</div>
<div class="dverse"><span class="lnum">45</span> This day, in argument upon a case,</div>
<div class="dverse">Some words there grew ’twixt Somerset and me;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe047" id="lnum-abe047">♦</a>
Among which terms he used his lavish tongue</div>
<div class="dverse">And did upbraid me with my father’s death:</div>
<div class="dverse">Which obloquy set bars before my tongue,</div>
<div class="dverse"><span class="lnum">50</span> Else with the like I had requited him.</div>
<div class="dverse">Therefore, good uncle, for my father’s sake,</div>
<div class="dverse">In honour of a true Plantagenet</div>
<div class="dverse">And for alliance sake, declare the cause</div>
<div class="dverse">My father, Earl of Cambridge, lost his head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe055" id="lnum-abe055">55</a>
 <span class="sd-cn">Mor.</span>
That cause, fair nephew, that imprison’d me</div>
<div class="dverse">And hath detain’d me all my flowering youth</div>
<div class="dverse">Within a loathsome dungeon, there to pine,</div>
<div class="dverse">Was cursed instrument of his decease.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 Discover more at large what cause that was,</div>
<div class="dverse"><span class="lnum">60</span> For I am ignorant and cannot guess.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe061" id="lnum-abe061">♦</a>
 <span class="sd-cn">Mor.</span>
I will, if that my fading breath permit</div>
<div class="dverse">And death approach not ere my tale be done.</div>
<div class="dverse">Henry the Fourth, grandfather to this king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe064" id="lnum-abe064">♦</a>
Deposed his nephew Richard, Edward’s son,</div>
<div class="dverse"><span class="lnum">65</span> The first-begotten and the lawful heir</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe066" id="lnum-abe066">♦</a>
Of Edward king, the third of that descent:</div>
<div class="dverse">During whose reign the Percies of the north,</div>
<div class="dverse">Finding his usurpation most unjust,</div>
<div class="dverse">Endeavour’d my advancement to the throne:</div>
<div class="dverse"><span class="lnum">70</span> The reason moved these warlike lords to this</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe071" id="lnum-abe071">♦</a>
Was, for that—young King Richard thus removed,</div>
<div class="dverse">Leaving no heir begotten of his body—</div>
<div class="dverse">I was the next by birth and parentage;</div>
<div class="dverse">For by my mother I derived am</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe075" id="lnum-abe075">75</a>
From Lionel Duke of Clarence, the third son</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe076" id="lnum-abe076">♦</a>
To King Edward the Third; whereas he</div>
<div class="dverse">From John of Gaunt doth bring his pedigree,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe078" id="lnum-abe078">♦</a>
Being but fourth of that heroic line.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe079" id="lnum-abe079">♦</a>
But mark: as in this haughty great attempt</div>
<div class="dverse"><span class="lnum">80</span> They laboured to plant the rightful heir,</div>
<div class="dverse">I lost my liberty and they their lives.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe082" id="lnum-abe082">♦</a>
Long after this, when Henry the Fifth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe083" id="lnum-abe083">♦</a>
Succeeding his father Bolingbroke, did reign,</div>
<div class="dverse">Thy father, Earl of Cambridge, then derived</div>
<div class="dverse"><span class="lnum">85</span> From famous Edmund Langley, Duke of York,</div>
<div class="dverse">Marrying my sister that thy mother was,</div>
<div class="dverse">Again in pity of my hard distress</div>
<div class="dverse">Levied an army, weening to redeem</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe089" id="lnum-abe089">♦</a>
And have install’d me in the diadem:</div>
<div class="dverse"><span class="lnum">90</span> But, as the rest, so fell that noble earl</div>
<div class="dverse">And was beheaded. Thus the Mortimers,</div>
<div class="dverse">In whom the title rested, were suppress’d.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe093" id="lnum-abe093">♦</a>
 <span class="sd-cn">Plan.</span>
Of which, my lord, your honour is the last.</div>

<div class="dverse1"><span class="sd-cn">Mor.</span>
 True; and them seest that I no issue have</div>
<div class="dverse"><span class="lnum">95</span> And that my fainting words do warrant death:</div>
<div class="dverse">Thou art my heir; the rest I wish thee gather:</div>
<div class="dverse">But yet be wary in thy studious care.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 Thy grave admonishments prevail with me:</div>
<div class="dverse">But yet, methinks, my father’s execution</div>
<div class="dverse"><span class="lnum">100</span> Was nothing less than bloody tyranny.</div>

<div class="dverse1"><span class="sd-cn">Mor.</span>
 With silence, nephew, be thou politic:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe102" id="lnum-abe102">♦</a>
Strong-fixed is the house of Lancaster</div>
<div class="dverse">And like a mountain, not to be removed.</div>
<div class="dverse">But now thy uncle is removing hence;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe105" id="lnum-abe105">105</a>
As princes do their courts, when they are cloy’d</div>
<div class="dverse">With long continuance in a settled place.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 O, uncle, would some part of my young years</div>
<div class="dverse">Might but redeem the passage of your age!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-abe109" id="lnum-abe109">♦</a>
 <span class="sd-cn">Mor.</span>
Thou dost then wrong me, as that slaughterer doth</div>
<div class="dverse"><span class="lnum">110</span> Which giveth many wounds when one will kill.</div>
<div class="dverse">Mourn not, except thou sorrow for my good;</div>
<div class="dverse">Only give order for my funeral:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe113" id="lnum-abe113">♦</a>
And so farewell, and fair be all thy hopes</div>
<div class="dverse">And prosperous be thy life in peace and war!
 <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="lnum">115</span>
 <span class="sd-cn">Plan.</span>  And peace, no war, befall thy parting soul!</div>
<div class="dverse">In prison hast thou spent a pilgrimage</div>
<div class="dverse">And like a hermit overpass’d thy days.</div>
<div class="dverse">Well, I will lock his counsel in my breast;</div>
<div class="dverse">And what I do imagine let that rest.</div>
<div class="dverse"><span class="lnum">120</span> Keepers, convey him hence, and I myself</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe121" id="lnum-abe121">♦</a>
 Will see his burial better than his life.
 <span class="sd-verseend">[<i>Exeunt Gaolers, bearing out the body of Mortimer.</i></span></div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-abe122" id="lnum-abe122">♦</a>
Here dies the dusky torch of Mortimer,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe123" id="lnum-abe123">♦</a>
Choked with ambition of the meaner sort:</div>
<div class="dverse">And for those wrongs, those bitter injuries,</div>
<div class="dverse"><span class="lnum">125</span> Which Somerset hath offer’d to my house,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe126" id="lnum-abe126">♦</a>
I doubt not but with honour to redress;</div>
<div class="dverse">And therefore haste I to the parliament,</div>
<div class="dverse">Either to be restored to my blood,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-abe129" id="lnum-abe129">♦</a>
Or make my ill the advantage of my good.
<span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h3 class="h3main">ACT III.</h3>

<h4 class="h4main"><span class="dnavigate">aca</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>London.
The Parliament-house</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">E<span>XETER</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <i>and</i>
<span class="smcaps">S<span>UFFOLK</span>;</span> <i>the</i>
<span class="smcaps">B<span>ISHOP</span></span> of <span class="smcaps">W<span>INCHESTER</span>,</span>
<span class="smcaps">R<span>ICHARD</span></span>
<span class="smcaps">P<span>LANTAGENET</span>,</span> <i>and others.</i>
<span class="smcaps">G<span>LOUCESTER</span></span> <i>offers to put up a bill;</i>
<span class="smcaps">W<span>INCHESTER</span></span> <i>snatches it, tears it</i>.
</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca001" id="lnum-aca001">♦</a>
 <span class="sd-cn">Win.</span>
Comest thou with deep premeditated lines,</div>
<div class="dverse">With written pamphlets studiously devised,</div>
<div class="dverse">Humphrey of Gloucester? If thou canst accuse,</div>
<div class="dverse">Or aught intend’st to lay unto my charge,</div>
<div class="dverse"><span class="lnum">5</span> Do it without invention, suddenly;</div>
<div class="dverse">As I with sudden and extemporal speech</div>
<div class="dverse">Purpose to answer what thou canst object.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Presumptuous priest! this place commands my patience,</div>
<div class="dverse">Or thou shouldst find thou hast dishonour’d me.</div>
<div class="dverse"><span class="lnum">10</span> Think not, although in writing I preferr’d</div>
<div class="dverse">The manner of thy vile outrageous crimes,</div>
<div class="dverse">That therefore I have forged, or am not able</div>
<div class="dverse">Verbatim to rehearse the method of my pen:</div>
<div class="dverse">No, prelate; such is thy audacious wickedness,</div>
<div class="dverse"><span class="lnum">15</span> Thy lewd, pestiferous and dissentious pranks,</div>
<div class="dverse">As very infants prattle of thy pride.</div>
<div class="dverse">Thou art a most pernicious usurer,</div>
<div class="dverse">Froward by nature, enemy to peace;</div>
<div class="dverse">Lascivious, wanton, more than well beseems</div>
<div class="dverse"><span class="lnum">20</span> A man of thy profession and degree;</div>
<div class="dverse">And for thy treachery, what’s more manifest?</div>
<div class="dverse">In that thou laid’st a trap to take my life,</div>
<div class="dverse">As well at London-bridge as at the Tower.</div>
<div class="dverse">Beside, I fear me, if thy thoughts were sifted,</div>
<div class="dverse"><span class="lnum">25</span> The king, thy sovereign, is not quite exempt</div>
<div class="dverse">From envious malice of thy swelling heart.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca027" id="lnum-aca027">♦</a>
 <span class="sd-cn">Win.</span>
Gloucester, I do defy thee. Lords, vouchsafe</div>
<div class="dverse">To give me hearing what I shall reply.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca029" id="lnum-aca029">♦</a>
If I were covetous, ambitious or perverse,</div>
<div class="dverse"><span class="lnum">30</span> As he will have me, how am I so poor?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca031" id="lnum-aca031">♦</a>
Or how haps it I seek not to advance</div>
<div class="dverse">Or raise myself, but keep my wonted calling?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca033" id="lnum-aca033">♦</a>
And for dissension, who preferreth peace</div>
<div class="dverse">More than I do?—except I be provoked.</div>
<div class="dverse"><span class="lnum">35</span> No, my good lords, it is not that offends;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca036" id="lnum-aca036">♦</a>
It is not that that hath incensed the duke:</div>
<div class="dverse">It is, because no one should sway but he;</div>
<div class="dverse">No one but he should be about the king;</div>
<div class="dverse">And that engenders thunder in his breast</div>
<div class="dverse"><span class="lnum">40</span> And makes him roar these accusations forth.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca041" id="lnum-aca041">♦</a>
But he shall know I am as good—</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 <span class="i15"> </span> As good!</div>
<div class="dverse">Thou bastard of my grandfather!</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 Ay, lordly sir; for what are you, I pray,</div>
<div class="dverse">But one imperious in another’s throne?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca045" id="lnum-aca045">45</a>
 <span class="sd-cn">Glou.</span>
Am I not protector, saucy priest?</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 And am not I a prelate of the church?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Yes, as an outlaw in a castle keeps</div>
<div class="dverse">And useth it to patronage his theft.</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 Unreverent Gloster!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca049" id="lnum-aca049">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="i10"> </span> Thou art reverent</div>
<div class="dverse"><span class="lnum">50</span>
 Touching thy spiritual function, not thy life.</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 Rome shall remedy this.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca051" id="lnum-aca051">♦</a>
 <span class="sd-cn">War.</span>
 <span class="i13"> </span> Roam thither, then.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 My lord, it were your duty to forbear.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca053" id="lnum-aca053">♦</a>
 <span class="sd-cn">War.</span>
Ay, see the bishop be not overborne.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Methinks my lord should be religious</div>
<div class="dverse"><span class="lnum">55</span> And know the office that belongs to such.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca056" id="lnum-aca056">♦</a>
 <span class="sd-cn">War.</span>
Methinks his lordship should be humbler;</div>
<div class="dverse">It fitteth not a prelate so to plead.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Yes, when his holy state is touch’d so near.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 State holy or unhallow’d, what of that?</div>
<div class="dverse"><span class="lnum">60</span> Is not his grace protector to the king?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca061" id="lnum-aca061">♦</a>
 <span class="sd-cn">Plan.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
Plantagenet, I see, must hold his tongue,</div>
<div class="dverse">Lest it be said ‘Speak, sirrah, when you should;</div>
<div class="dverse">Must your bold verdict enter talk with lords?’</div>
<div class="dverse">Else would I have a fling at Winchester.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca065" id="lnum-aca065">65</a>
 <span class="sd-cn">King.</span>
Uncles of Gloucester and of Winchester,</div>
<div class="dverse">The special watchmen of our English weal,</div>
<div class="dverse">I would prevail, if prayers might prevail,</div>
<div class="dverse">To join your hearts in love and amity.</div>
<div class="dverse">O, what a scandal is it to our crown,</div>
<div class="dverse"><span class="lnum">70</span> That two such noble peers as ye should jar!</div>
<div class="dverse">Believe me, lords, my tender years can tell</div>
<div class="dverse">Civil dissension is a viperous worm</div>
<div class="dverse">That gnaws the bowels of the commonwealth.
 <span class="sd-verseend">[<i>A noise within,</i> ‘Down with the tawny-coats!’</span></div>
<div class="dverse">What tumult’s this?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <span class="i07"> </span>
 An uproar, I dare warrant,</div>
<div class="dverse"><span class="lnum">75</span>
 Begun through malice of the bishop’s men.
<span class="sd-verseend">[<i>A noise again,</i> ‘Stones! stones!’</span></div>

<div class="sd-entry"><i>Enter Mayor</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca076" id="lnum-aca076">♦</a>
 <span class="sd-cn">May.</span>
O, my good lords, and virtuous Henry,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca077" id="lnum-aca077">♦</a>
Pity the city of London, pity us!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca078" id="lnum-aca078">♦</a>
The bishop and the Duke of Gloucester’s men,</div>
<div class="dverse">Forbidden late to carry any weapon,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca080" id="lnum-aca080">80</a>
Have fill’d their pockets full of pebble stones</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca081" id="lnum-aca081">♦</a>
And banding themselves in contrary parts</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca082" id="lnum-aca082">♦</a>
Do pelt so fast at one another’s pate</div>
<div class="dverse">That many have their giddy brains knock’d out:</div>
<div class="dverse">Our windows are broke down in every street</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca085" id="lnum-aca085">85</a>
And we for fear compell’d to shut our shops.</div>

<div class="sd-entry"><i>Enter</i> Serving-men, <i>in skirmish, with bloody pates</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca086" id="lnum-aca086">♦</a>
 <span class="sd-cn">King.</span>
We charge you, on allegiance to ourself,</div>
<div class="dverse">To hold your slaughtering hands and keep the peace.</div>
<div class="dverse">Pray, uncle Gloucester, mitigate this strife.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca089" id="lnum-aca089">♦</a>
 <span class="sd-cn">First Serv.</span>
Nay, if we be forbidden stones, we’ll fall</div>
<div class="dverse"><span class="lnum">90</span> to it with our teeth.</div>

<div class="dverse1"><span class="sd-cn">Sec. Serv.</span>
 Do what ye dare, we are as resolute.
 <span class="sd-verseend">[<i>Skirmish again.</i></span></div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 You of my household, leave this peevish broil</div>
<div class="dverse">And set this unaccustom’d fight aside.</div>

<div class="dverse1"><span class="sd-cn">Third Serv.</span>
 My lord, we know your grace to be a man</div>
<div class="dverse"><span class="lnum">95</span> Just and upright; and, for your royal birth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca096" id="lnum-aca096">♦</a>
Inferior to none but to his majesty:</div>
<div class="dverse">And ere that we will suffer such a prince,</div>
<div class="dverse">So kind a father of the commonweal,</div>
<div class="dverse">To be disgraced by an inkhorn mate,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca100" id="lnum-aca100">100</a>
We and our wives and children all will fight</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca101" id="lnum-aca101">♦</a>
And have our bodies slaughter’d by thy foes.</div>

<div class="dverse1"><span class="sd-cn">First Serv.</span>
 Ay, and the very parings of our nails</div>
<div class="dverse">Shall pitch a field when we are dead.
 <span class="sd-verseend">[<i>Begin again.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca103" id="lnum-aca103">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="i16"> </span> Stay, stay, I say!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca104" id="lnum-aca104">♦</a>
And if you love me, as you say you do,</div>
<div class="dverse"><span class="lnum">105</span> Let me persuade you to forbear awhile.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O, how this discord doth afflict my soul!</div>
<div class="dverse">Can you, my Lord of Winchester, behold</div>
<div class="dverse">My sighs and tears and will not once relent?</div>
<div class="dverse">Who should be pitiful, if you be not?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca110" id="lnum-aca110">110</a>
Or who should study to prefer a peace,</div>
<div class="dverse">If holy churchmen take delight in broils?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca112" id="lnum-aca112">♦</a>
 <span class="sd-cn">War.</span>
Yield, my lord protector; yield, Winchester;</div>
<div class="dverse">Except you mean with obstinate repulse</div>
<div class="dverse">To slay your sovereign and destroy the realm.</div>
<div class="dverse"><span class="lnum">115</span> You see what mischief and what murder too</div>
<div class="dverse">Hath been enacted through your enmity;</div>
<div class="dverse">Then be at peace, except ye thirst for blood.</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 He shall submit, or I will never yield.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Compassion on the king commands me stoop;</div>
<div class="dverse"><span class="lnum">120</span> Or I would see his heart out, ere the priest</div>
<div class="dverse">Should ever get that privilege of me.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Behold, my Lord of Winchester, the duke</div>
<div class="dverse">Hath banish’d moody discontented fury,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca124" id="lnum-aca124">♦</a>
As by his smoothed brows it doth appear:</div>
<div class="dverse"><span class="lnum">125</span> Why look you still so stern and tragical?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Here, Winchester, I offer thee my hand.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Fie, uncle Beaufort! I have heard you preach</div>
<div class="dverse">That malice was a great and grievous sin;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca129" id="lnum-aca129">♦</a>
And will not you maintain the thing you teach,</div>
<div class="dverse"><span class="lnum">130</span> But prove a chief offender in the same?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca131" id="lnum-aca131">♦</a>
 <span class="sd-cn">War.</span>
Sweet king! the bishop hath a kindly gird.</div>
<div class="dverse">For shame, my lord of Winchester, relent!</div>
<div class="dverse">What, shall a child instruct you what to do?</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 Well, Duke of Gloucester, I will yield to thee;</div>
<div class="dverse"><span class="lnum">135</span> Love for thy love and hand for hand I give.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca136" id="lnum-aca136">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Ay, but, I fear me, with a hollow heart.</div>
<div class="dverse">See here, my friends and loving countrymen;</div>
<div class="dverse">This token serveth for a flag of truce</div>
<div class="dverse">Betwixt ourselves and all our followers:</div>
<div class="dverse"><span class="lnum">140</span> So help me God, as I dissemble not!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca141" id="lnum-aca141">♦</a>
 <span class="sd-cn">Win.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 So help me God, as I intend it not!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca142" id="lnum-aca142">♦</a>
 <span class="sd-cn">King.</span>
O loving uncle, kind Duke of Gloucester,</div>
<div class="dverse">How joyful am I made by this contract!</div>
<div class="dverse">Away, my masters! trouble us no more;</div>
<div class="dverse"><span class="lnum">145</span> But join in friendship, as your lords have done.</div>

<div class="dverse1"><span class="sd-cn">First Serv.</span>
 Content: I’ll to the surgeon’s.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca146" id="lnum-aca146">♦</a>
 <span class="sd-cn">Sec. Serv.</span>
 <span class="i16"> </span> And so will I.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca147" id="lnum-aca147">♦</a>
 <span class="sd-cn">Third Serv.</span>
And I will see what physic the tavern</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca148" id="lnum-aca148">♦</a>
affords. <span class="sd-verseend">[<i>Exeunt Serving-men, Mayor, &amp;c.</i></span>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca149" id="lnum-aca149">♦</a>
 <span class="sd-cn">War.</span>
Accept this scroll, most gracious sovereign,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca150" id="lnum-aca150">150</a>
Which in the right of Richard Plantagenet</div>
<div class="dverse">We do exhibit to your majesty.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Well urged, my Lord of Warwick: for, sweet prince,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca153" id="lnum-aca153">♦</a>
An if your grace mark every circumstance,</div>
<div class="dverse">You have great reason to do Richard right;</div>
<div class="dverse"><span class="lnum">155</span> Especially for those occasions</div>
<div class="dverse">At Eltham Place I told your majesty.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 And those occasions, uncle, were of force:</div>
<div class="dverse">Therefore, my loving lords, our pleasure is</div>
<div class="dverse">That Richard be restored to his blood.</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">War.</span>  Let Richard be restored to his blood;</div>
<div class="dverse">So shall his father’s wrongs be recompensed.</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 As will the rest, so willeth Winchester.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca163" id="lnum-aca163">♦</a>
 <span class="sd-cn">King.</span>
If Richard will be true, not that alone</div>
<div class="dverse">But all the whole inheritance I give</div>
<div class="dverse"><span class="lnum">165</span> That doth belong unto the house of York,</div>
<div class="dverse">From whence you spring by lineal descent.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca167" id="lnum-aca167">♦</a>
 <span class="sd-cn">Plan.</span>
Thy humble servant vows obedience</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca168" id="lnum-aca168">♦</a>
And humble service till the point of death.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Stoop then and set your knee against my foot;</div>
<div class="dverse"><span class="lnum">170</span> And, in reguerdon of that duty done,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca171" id="lnum-aca171">♦</a>
I gird thee with the valiant sword of York:</div>
<div class="dverse">Rise, Richard, like a true Plantagenet,</div>
<div class="dverse">And rise created princely Duke of York.</div>

<div class="dverse1"><span class="sd-cn">Plan.</span>
 And so thrive Richard as thy foes may fall!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca175" id="lnum-aca175">175</a>
And as my duty springs, so perish they</div>
<div class="dverse">That grudge one thought against your majesty!</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Welcome, high prince, the mighty Duke of York!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca178" id="lnum-aca178">♦</a>
 <span class="sd-cn">Som.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Perish, base prince, ignoble Duke of York!</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Now will it best avail your majesty</div>
<div class="dverse"><span class="lnum">180</span> To cross the seas and to be crown’d in France:</div>
<div class="dverse">The presence of a king engenders love</div>
<div class="dverse">Amongst his subjects and his loyal friends,</div>
<div class="dverse">As it disanimates his enemies.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 When Gloucester says the word, King Henry goes;</div>
<div class="dverse"><span class="lnum">185</span> For friendly counsel cuts off many foes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca186" id="lnum-aca186">♦</a>
 <span class="sd-cn">Glou.</span>
Your ships already are in readiness.
 <span class="sd-verseend">[<i>Sennet. Flourish. Exeunt all but Exeter.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aca187" id="lnum-aca187">♦</a>
 <span class="sd-cn">Exe.</span>
Ay, we may march in England or in France,</div>
<div class="dverse">Not seeing what is likely to ensue.</div>
<div class="dverse">This late dissension grown betwixt the peers</div>
<div class="dverse"><span class="lnum">190</span> Burns under feigned ashes of forged love</div>
<div class="dverse">And will at last break out into a flame:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca192" id="lnum-aca192">♦</a>
As fester’d members rot but by degree,</div>
<div class="dverse">Till bones and flesh and sinews fall away,</div>
<div class="dverse">So will this base and envious discord breed.</div>
<div class="dverse"><span class="lnum">195</span> And now I fear that fatal prophecy</div>
<div class="dverse">Which in the time of Henry named the fifth</div>
<div class="dverse">Was in the mouth of every sucking babe;</div>
<div class="dverse">That Henry born at Monmouth should win all</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aca199" id="lnum-aca199">♦</a>
And Henry born at Windsor lose all:</div>
<div class="dverse"><span class="lnum">200</span> Which is so plain that Exeter doth wish</div>
<div class="dverse">His days may finish ere that hapless time.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">acb</span>
<span class="smcaps">S<span>CENE</span></span> II.
<i>France. Before Rouen</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span></span> <i>disguised, with four</i>
Soldiers <i>with sacks upon their backs</i>.</div></div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 These are the city gates, the gates of Rouen,</div>
<div class="dverse">Through which our policy must make a breach:</div>
<div class="dverse">Take heed, be wary how you place your words;</div>
<div class="dverse">Talk like the vulgar sort of market men</div>
<div class="dverse"><span class="lnum">5</span> That come to gather money for their corn.</div>
<div class="dverse">If we have entrance, as I hope we shall,</div>
<div class="dverse">And that we find the slothful watch but weak,</div>
<div class="dverse">I’ll by a sign give notice to our friends,</div>
<div class="dverse">That Charles the Dauphin may encounter them.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">First Sol.</span>  Our sacks shall be a mean to sack the city,</div>
<div class="dverse">And we be lords and rulers over Rouen;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb012" id="lnum-acb012">♦</a>
<span class="sd-inline">[<i>Knocks.</i></span> Therefore we’ll knock.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb013" id="lnum-acb013">♦</a>
 <span class="sd-cn">Watch.</span>
 <span class="sd-inline">[<i>Within</i>]</span>
Qui est là?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb014" id="lnum-acb014">♦</a>
 <span class="sd-cn">Puc.</span>
Paysans, pauvres gens de France;</div>
<div class="dverse"><span class="lnum">15</span> Poor market folks that come to sell their corn.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb016" id="lnum-acb016">♦</a>
 <span class="sd-cn">Watch.</span>
Enter, go in; the market bell is rung.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb017" id="lnum-acb017">♦</a>
 <span class="sd-cn">Puc.</span>
 Now, Rouen, I’ll shake thy bulwarks to the ground.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>HARLES</span>,</span> <i>the</i> <span class="smcaps">B<span>ASTARD</span></span> <i>of Orleans</i>, <span class="smcaps">A<span>LENÇON</span>,</span> <span class="smcaps">R<span>EIGNIER</span>,</span> <i>and forces</i>. </div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Saint Denis bless this happy stratagem!</div>
<div class="dverse">And once again we’ll sleep secuere in Rouen.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb020" id="lnum-acb020">20</a>
 <span class="sd-cn">Bast.</span>
Here enter’d Pucelle und her practisants;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb021" id="lnum-acb021">♦</a>
Now she is there, how will she specify</div>
<div class="dverse">Where is the best and safes passage in?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb023" id="lnum-acb023">♦</a>
 <span class="sd-cn">Reign.</span>
By thrusting out a torch from yonder tower;</div>
<div class="dverse">Which, once discern’d, shows that her meaning is,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb025" id="lnum-acb025">25</a>
No way to that, for weakness, which she enter’d.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span></span> <i>on the top, thrusting out a torch burning</i>.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Behold, this is the happy wedding torch</div>
<div class="dverse">That joineth Rouen unto her countrymen,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb028" id="lnum-acb028">♦</a>
 But burning fatal to the Talbotites!
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Bast.</span>
 See, noble Charles, the beacon of our friend;</div>
<div class="dverse"><span class="lnum">30</span> The burning torch in yonder turret stands.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb031" id="lnum-acb031">♦</a>
 <span class="sd-cn">Char.</span>
Now shine it like a comet of revenge,</div>
<div class="dverse">A prophet to the fall of all our foes!</div>

<div class="dverse1"><span class="sd-cn">Reign.</span>
 Defer no time, delays have dangerous ends;</div>
<div class="dverse">Enter, and cry ‘The Dauphin!’ presently,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb035" id="lnum-acb035">35</a>
And then do execution on the watch.
<span class="sd-verseend">[<i>Alarum. Exeunt.</i></span></div>

<div class="sd-entry"><i>An alarum. Enter</i> <span class="smcaps">T<span>ALBOT</span></span> <i>in an excursion</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb036" id="lnum-acb036">♦</a>
 <span class="sd-cn">Tal.</span>
France, thou shalt rue this treason with thy tears,</div>
<div class="dverse">If Talbot but survive thy treachery.</div>
<div class="dverse">Pucelle, that witch, that damned sorceress,</div>
<div class="dverse">Hath wrought this hellish mischief unawares,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb040" id="lnum-acb040">40</a>
That hardly we escaped the pride of France.
<span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>An alarum: excursions.</i> <span class="smcaps">B<span>EDFORD,</span></span> <i>brought in sick in a chair. Enter</i> <span class="smcaps">T<span>ALBOT</span></span>
<i>and</i> <span class="smcaps">B<span>URGUNDY</span></span>
<i>without: within</i> <span class="smcaps">L<span>A</span></span>
<span class="smcaps">P<span>UCELLE</span>,</span> <span class="smcaps">C<span>HARLES</span>,</span> <span class="smcaps">B<span>ASTARD</span>,</span> <span class="smcaps">A<span>LENÇON</span>,</span> <i>and</i> <span class="smcaps">R<span>EIGNIER</span>,</span> <i>on the walls</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb041" id="lnum-acb041">♦</a>
 <span class="sd-cn">Puc.</span>
Good morrow, gallants! want ye corn for bread?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb042" id="lnum-acb042">♦</a>
I think the Duke of Burgundy will fast</div>
<div class="dverse">Before he’ll buy again at such a rate:</div>
<div class="dverse">’Twas full of darnel; do you like the taste?</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Bur.</span>  Scoff on, vile fiend and shameless courtezan!</div>
<div class="dverse">I trust ere long to choke thee with thine own</div>
<div class="dverse">And make thee curse the harvest of that corn.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Your grace may starve perhaps before that time.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span>
 O, let no words, but deeds, revenge this treason!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb050" id="lnum-acb050">50</a>
 <span class="sd-cn">Puc.</span>
What will you do, good grey-beard? break a lance,</div>
<div class="dverse">And run a tilt at death within a chair?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb052" id="lnum-acb052">♦</a>
 <span class="sd-cn">Tal.</span>
Foul fiend of France, and hag of all despite,</div>
<div class="dverse">Encompass’d with thy lustful paramours!</div>
<div class="dverse">Becomes it thee to taunt his valiant age,</div>
<div class="dverse"><span class="lnum">55</span> And twit with cowardice a man half dead?</div>
<div class="dverse">Damsel, I’ll have a bout with you again,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb057" id="lnum-acb057">♦</a>
Or else let Talbot perish with this shame.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb058" id="lnum-acb058">♦</a>
 <span class="sd-cn">Puc.</span>
Are ye so hot, sir? yet, Pucelle, hold thy peace;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb059" id="lnum-acb059">♦</a>
 If Talbot do but thunder, rain will follow.
<span class="sd-verseend">[<i>The English whisper together in council.</i></span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb060" id="lnum-acb060">60</a>
God speed the parliament! who shall be the speaker?</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Dare ye come forth and meet us in the field?</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Belike your lordship takes us then for fools,</div>
<div class="dverse">To try if that our own be ours or no.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 I speak not to that railing Hecate,</div>
<div class="dverse"><span class="lnum">65</span> But unto thee, Alençon, and the rest;</div>
<div class="dverse">Will ye, like soldiers, come and fight it out?</div>

<div class="dverse1"><span class="sd-cn">Alen.</span>
 Signior, no.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb068" id="lnum-acb068">♦</a>
 <span class="sd-cn">Tal.</span>
Signior, hang! base muleters of France!</div>
<div class="dverse">Like peasant foot-boys do they keep the walls</div>
<div class="dverse"><span class="lnum">70</span> And dare not take up arms like gentlemen.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb071" id="lnum-acb071">♦</a>
 <span class="sd-cn">Puc.</span>
Away, captains! let’s get us from the walls;</div>
<div class="dverse">For Talbot means no goodness by his looks.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb073" id="lnum-acb073">♦</a>
God be wi’ you, my lord! we came but to tell you</div>
<div class="dverse">That we are here.
 <span class="sd-verseend">[<i>Exeunt from the walls.</i></span></div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Tal.</span>  And there will we be too, ere it be long,</div>
<div class="dverse">Or else reproach be Talbot’s greatest fame!</div>
<div class="dverse">Vow, Burgundy, by honour of thy house,</div>
<div class="dverse">Prick’d on by public wrongs sustain’d in France,</div>
<div class="dverse">Either to get the town again or die:</div>
<div class="dverse"><span class="lnum">80</span> And I, as sure as English Henry lives</div>
<div class="dverse">And as his father here was conqueror,</div>
<div class="dverse">As sure as in this late-betrayed town</div>
<div class="dverse">Great Cœur-de-lion’s heart was buried,</div>
<div class="dverse">So sure I swear to get the town or die.</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Bur.</span>  My vows are equal partners with thy vows.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 But, ere we go, regard this dying prince,</div>
<div class="dverse">The valiant Duke of Bedford. Come, my lord,</div>
<div class="dverse">We will bestow you in some better place,</div>
<div class="dverse">Fitter for sickness and for crazy age.</div>

<div class="dverse1"><span class="lnum">90</span>
 <span class="sd-cn">Bed.</span>  Lord Talbot, do not so dishonour me:</div>
<div class="dverse">Here will I sit before the walls of Rouen</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb092" id="lnum-acb092">♦</a>
And will be partner of your weal or woe.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Courageous Bedford, let us now persuade you.</div>

<div class="dverse1"><span class="sd-cn">Bed.</span>
 Not to be gone from hence; for once I read</div>
<div class="dverse"><span class="lnum">95</span> That stout Pendragon in his litter sick</div>
<div class="dverse">Came to the field and vanquished his foes:</div>
<div class="dverse">Methinks I should revive the soldiers’ hearts,</div>
<div class="dverse">Because I ever found them as myself.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb099" id="lnum-acb099">♦</a>
 <span class="sd-cn">Tal.</span>
Undaunted spirit in a dying breast!</div>
<div class="dverse"><span class="lnum">100</span> Then be it so: heavens keep old Bedford safe!</div>
<div class="dverse">And now no more ado, brave Burgundy,</div>
<div class="dverse">But gather we our forces out of hand</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb103" id="lnum-acb103">♦</a>
And set upon our boasting enemy.
<span class="sd-verseend">[<i>Exeunt all but Bedford and Attendants.</i></span></div>

<div class="sd-entry"><i>An alarum: excursions. Enter</i> <span class="smcaps">S<span>IR</span></span>
<span class="smcaps">J<span>OHN</span></span> <span class="smcaps">F<span>ASTOLFE</span></span> <i>and a</i> Captain.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb104" id="lnum-acb104">♦</a>
 <span class="sd-cn">Cap.</span>
Whither away, Sir John Fastolfe, in such haste?</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">Fast.</span>  Whither away! to save myself by flight:</div>
<div class="dverse">We are like to have the overthrow again.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 What! will you fly, and leave Lord Talbot?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb107" id="lnum-acb107">♦</a>
 <span class="sd-cn">Fast.</span>
 <span class="i22"> </span> Ay,</div>
<div class="dverse">All the Talbots in the world, to save my life.
 <span class="sd-verseend">[<i>Exit</i></span></div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Cowardly knight! ill fortune follow thee!
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Retreat: excursions.</i>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <span class="smcaps">A<span>LENÇON</span></span> <i>and</i> <span class="smcaps">C<span>HARLES</span></span> <i>fly</i>.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">Bed.</span>  Now, quiet soul, depart when heaven please,</div>
<div class="dverse">For I have seen our enemies’ overthrow.</div>
<div class="dverse">What is the trust or strength of foolish man?</div>
<div class="dverse">They that of late were daring with their scoffs</div>
<div class="dverse">Are glad and fain by flight to save themselves.
 <span class="sd-verseend">[<i>Bedford dies, and is carried in by two in his chair.</i></span></div>

<div class="sd-entry"><i>An alarum. Re-enter</i> <span class="smcaps">T<span>ALBOT</span>,</span> <span class="smcaps">B<span>URGUNDY</span>,</span> <i>and the rest</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb115" id="lnum-acb115">115</a>
 <span class="sd-cn">Tal.</span>
Lost, and recover’d in a day again!</div>
<div class="dverse">This is a double honour, Burgundy:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb117" id="lnum-acb117">♦</a>
Yet heavens have glory for this victory!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acb118" id="lnum-acb118">♦</a>
 <span class="sd-cn">Bur.</span>
Warlike and martial Talbot, Burgundy</div>
<div class="dverse">Enshrines thee in his heart and there erects</div>
<div class="dverse"><span class="lnum">120</span> Thy noble deeds as valour’s monuments.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Thanks, gentle duke. But where is Pucelle now?</div>
<div class="dverse">I think her old familiar is asleep:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb123" id="lnum-acb123">♦</a>
Now where’s the Bastard’s braves, and Charles his gleeks?</div>
<div class="dverse">What, all amort? Rouen hangs her head for grief</div>
<div class="dverse"><span class="lnum">125</span> That such a valiant company are fled.</div>
<div class="dverse">Now will we take some order in the town,</div>
<div class="dverse">Placing therein some expert officers,</div>
<div class="dverse">And then depart to Paris to the king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acb129" id="lnum-acb129">♦</a>
For there young Henry with his nobles lie.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Bur.</span>  What wills Lord Talbot pleaseth Burgundy.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 But yet, before we go, let’s not forget</div>
<div class="dverse">The noble Duke of Bedford late deceased,</div>
<div class="dverse">But see his exequies fulfill’d in Rouen:</div>
<div class="dverse">A braver soldier never couched lance,</div>
<div class="dverse"><span class="lnum">135</span> A gentler heart did never sway in court;</div>
<div class="dverse">But kings and mightiest potentates must die,</div>
<div class="dverse">For that’s the end of human misery.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">acc</span> <span class="smcaps">S<span>CENE</span></span> III. <i>The plains near
Rouen</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">C<span>HARLES</span>,</span> <i>the</i> <span class="smcaps">B<span>ASTARD</span></span> <i>of Orleans,</i>
<span class="smcaps">A<span>LENÇON</span>,</span>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <i>and forces</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acc001" id="lnum-acc001">♦</a>
 <span class="sd-cn">Puc.</span>
Dismay not, princes, at this accident,</div>
<div class="dverse">Nor grieve that Rouen is so recovered:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc003" id="lnum-acc003">♦</a>
Care is no cure, but rather corrosive,</div>
<div class="dverse">For things that are not to be remedied.</div>
<div class="dverse"><span class="lnum">5</span> Let frantic Talbot triumph for a while</div>
<div class="dverse">And like a peacock sweep along his tail;</div>
<div class="dverse">We’ll pull his plumes and take away his train,</div>
<div class="dverse">If Dauphin and the rest will be but ruled.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 We have been guided by thee hitherto</div>
<div class="dverse"><span class="lnum">10</span> And of thy cunning had no diffidence:</div>
<div class="dverse">One sudden foil shall never breed distrust.</div>

<div class="dverse1"><span class="sd-cn">Bast.</span>
 Search out thy wit for secret policies,</div>
<div class="dverse">And we will make thee famous through the world.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span>
 We’ll set thy statue in some holy place,</div>
<div class="dverse"><span class="lnum">15</span> And have thee reverenced like a blessed saint:</div>
<div class="dverse">Employ thee then, sweet virgin, for our good.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Then thus it must be; this doth Joan devise:</div>
<div class="dverse">By fair persuasions mix’d with sugar’d words</div>
<div class="dverse">We will entice the Duke of Burgundy</div>
<div class="dverse"><span class="lnum">20</span> To leave the Talbot and to follow us.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Ay, marry, sweeting, if we could do that,</div>
<div class="dverse">France were no place for Henry’s warriors;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc023" id="lnum-acc023">♦</a>
Nor should that nation boast it so with us,</div>
<div class="dverse">But be extirped from our provinces.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Alen.</span>
 For ever should they be expulsed from France</div>
<div class="dverse">And not have title of an earldom here.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Your honours shall perceive how I will work</div>
<div class="dverse">To bring this matter to the wished end.
 <span class="sd-verseend">[<i>Drum sounds afar off.</i></span></div>
<div class="dverse">Hark! by the sound of drum you may perceive</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc030" id="lnum-acc030">30</a>
Their powers are marching unto Paris-ward.</div>

<div class="sd-entry"><i>Here sound an English march. Enter, and pass over at a distance,</i>
 <span class="smcaps">T<span>ALBOT</span></span>
<i>and his forces.</i></div>

<div class="dverse">There goes the Talbot, with his colours spread,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc032" id="lnum-acc032">♦</a>
And all the troops of English after him.</div>

<div class="sd-entry"><i>French march. Enter the</i> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">B<span>URGUNDY</span></span> <i>and forces.</i></div>

<div class="dverse">Now in the rearward comes the duke and his:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc036" id="lnum-acc036">♦</a>
Fortune in favour makes him lag behind.</div>
<div class="dverse"><span class="lnum">35</span>
Summon a parley; we will talk with him.
<span class="sd-verseend">[<i>Trumpets sound a parley.</i></span></div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 A parley with the Duke of Burgundy!</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Who craves a parley with the Burgundy?</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 The princely Charles of France, thy countryman.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 What say’st thou, Charles? for I am marching hence.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Char.</span>  Speak, Pucelle, and enchant him with thy words.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Brave Burgundy, undoubted hope of France!</div>
<div class="dverse">Stay, let thy humble handmaid speak to thee.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Speak on; but be not over-tedious.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Look on thy country, look on fertile France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc045" id="lnum-acc045">45</a>
And see the cities and the towns defaced</div>
<div class="dverse">By wasting ruin of the cruel foe.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc047" id="lnum-acc047">♦</a>
As looks the mother on her lowly babe</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc048" id="lnum-acc048">♦</a>
When death doth close his tender dying eyes,</div>
<div class="dverse">See, see the pining malady of France;</div>
<div class="dverse"><span class="lnum">50</span> Behold the wounds, the most unnatural wounds,</div>
<div class="dverse">Which thou thyself hast given her woful breast.</div>
<div class="dverse">O, turn thy edged sword another way;</div>
<div class="dverse">Strike those that hurt, and hurt not those that help.</div>
<div class="dverse">One drop of blood drawn from thy country’s bosom</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc055" id="lnum-acc055">55</a>
Should grieve thee more than streams of foreign gore:</div>
<div class="dverse">Return thee therefore with a flood of tears,</div>
<div class="dverse">And wash away thy country’s stained spots.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Either she hath bewitch’d me with her words,</div>
<div class="dverse">Or nature makes me suddenly relent.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acc060" id="lnum-acc060">60</a>
 <span class="sd-cn">Puc.</span>
Besides, all French and France exclaims on thee,</div>
<div class="dverse">Doubting thy birth and lawful progeny.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acc062" id="lnum-acc062">♦</a>
Who join’st thou with but with a lordly nation</div>
<div class="dverse">That will not trust thee but for profit’s sake?</div>
<div class="dverse">When Talbot hath set footing once in France</div>
<div class="dverse"><span class="lnum">65</span> And fashion’d thee that instrument of ill,</div>
<div class="dverse">Who then but English Henry will be lord</div>
<div class="dverse">And thou be thrust out like a fugitive?</div>
<div class="dverse">Call we to mind, and mark but this for proof,</div>
<div class="dverse">Was not the Duke of Orleans thy foe?</div>
<div class="dverse"><span class="lnum">70</span> And was he not in England prisoner?</div>
<div class="dverse">But when they heard he was thine enemy,</div>
<div class="dverse">They set him free without his ransom paid,</div>
<div class="dverse">In spite of Burgundy and all his friends.</div>
<div class="dverse">See, then, thou fight’st against thy countrymen</div>
<div class="dverse"><span class="lnum">75</span> And join’st with them will be thy slaughter-men.</div>
<div class="dverse">Come, come, return; return, thou wandering lord;</div>
<div class="dverse">Charles and the rest will take thee in their arms.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acc078" id="lnum-acc078">♦</a>
 <span class="sd-cn">Bur.</span>
I am vanquished; these haughty words of hers</div>
<div class="dverse">Have batter’d me like roaring cannon-shot,</div>
<div class="dverse"><span class="lnum">80</span> And made me almost yield upon my knees.</div>
<div class="dverse">Forgive me, country, and sweet countrymen,</div>
<div class="dverse">And, lords, accept this hearty kind embrace:</div>
<div class="dverse">My forces and my power of men are yours:</div>
<div class="dverse">So farewell, Talbot; I’ll no longer trust thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acc085" id="lnum-acc085">85</a>
 <span class="sd-cn">Puc.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Done like a Frenchman: turn, and turn again!</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Welcome, brave duke! thy friendship makes us fresh.</div>

<div class="dverse1"><span class="sd-cn">Bast.</span>
 And doth beget new courage in our breasts.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span>
 Pucelle hath bravely play’d her part in this,</div>
<div class="dverse">And doth deserve a coronet of gold.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acc090" id="lnum-acc090">90</a>
 <span class="sd-cn">Char.</span>
Now let us on, my lords, and join our powers,</div>
<div class="dverse">And seek how we may prejudice the foe.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">acd</span> <span class="smcaps">S<span>CENE</span></span> IV. <i>Paris. The
Palace</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">B<span>ISHOP</span></span> <span class="smmaj">OF</span>
<span class="smcaps">W<span>INCHESTER</span>,</span>
<span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">S<span>UFFOLK</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">E<span>XETER</span>:</span> <span class="smcaps">V<span>ERNON</span>,</span> <span class="smcaps">B<span>ASSET</span>,</span> <i>and others. To them with
his</i> Soldiers, <span class="smcaps">T<span>ALBOT</span>.</span></div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acd001" id="lnum-acd001">♦</a>
 <span class="sd-cn">Tal.</span>
My gracious prince, and honourable peers,</div>
<div class="dverse">Hearing of your arrival in this realm,</div>
<div class="dverse">I have awhile given truce unto my wars,</div>
<div class="dverse">To do my duty to my sovereign:</div>
<div class="dverse"><span class="lnum">5</span> In sign whereof, this arm, that hath reclaim’d</div>
<div class="dverse">To your obedience fifty fortresses,</div>
<div class="dverse">Twelve cities and seven walled towns of strength,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acd008" id="lnum-acd008">♦</a>
Beside five hundred prisoners of esteem,</div>
<div class="dverse">Lets fall his sword before your highness’ feet,</div>
<div class="dverse"><span class="lnum">10</span> And with submissive loyalty of heart</div>
<div class="dverse">Ascribes the glory of his conquest got</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acd012" id="lnum-acd012">♦</a>
First to my God and next unto your grace.
<span class="sd-verseend">[<i>Kneels.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acd013" id="lnum-acd013">♦</a>
 <span class="sd-cn">King.</span>
Is this the Lord Talbot, uncle Gloucester,</div>
<div class="dverse">That hath so long been resident in France?</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Glou.</span>  Yes, if it please your majesty, my liege.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Welcome, brave captain and victorious lord!</div>
<div class="dverse">When I was young, as yet I am not old,</div>
<div class="dverse">I do remember how my father said</div>
<div class="dverse">A stouter champion never handled sword.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acd020" id="lnum-acd020">20</a>
Long since we were resolved of your truth,</div>
<div class="dverse">Your faithful service and your toil in war;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acd022" id="lnum-acd022">♦</a>
Yet never have you tasted our reward,</div>
<div class="dverse">Or been reguerdon’d with so much as thanks,</div>
<div class="dverse">Because till now we never saw your face:</div>
<div class="dverse"><span class="lnum">25</span> Therefore, stand up; and, for these good deserts,</div>
<div class="dverse">We here create you Earl of Shrewsbury;</div>
<div class="dverse">And in our coronation take your place.
 <span class="sd-verseend">[<i>Sennet. Flourish. Exeunt all but Vernon and Basset.</i></span></div>

<div class="dverse1"><span class="sd-cn">Ver.</span>
 Now, sir, to you, that were so hot at sea,</div>
<div class="dverse">Disgracing of these colours that I wear</div>
<div class="dverse"><span class="lnum">30</span> In honour of my noble Lord of York:—</div>
<div class="dverse">Darest thou maintain the former words thou spakest?</div>

<div class="dverse1"><span class="sd-cn">Bas.</span>
 Yes, sir; as well as you dare patronage</div>
<div class="dverse">The envious barking of your saucy tongue</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acd034" id="lnum-acd034">♦</a>
Against my lord the Duke of Somerset.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Ver.</span>  Sirrah, thy lord I honour as he is.</div>

<div class="dverse1"><span class="sd-cn">Bas.</span>
 Why, what is he? as good a man as York.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-acd037" id="lnum-acd037">♦</a>
 <i>Ver.</i> Hark ye; not so: in witness, take ye that.
 <span class="sd-verseend">[<i>Strikes him.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-acd038" id="lnum-acd038">♦</a>
 <span class="sd-cn">Bas.</span>
Villain, thou know’st the law of arms is such</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-acd039" id="lnum-acd039">♦</a>
That whoso draws a sword, ’tis present death,</div>
<div class="dverse"><span class="lnum">40</span> Or else this blow should broach thy dearest blood.</div>
<div class="dverse">But I’ll unto his majesty, and crave</div>
<div class="dverse">I may have liberty to venge this wrong;</div>
<div class="dverse">When thou shalt see I’ll meet thee to thy cost.</div>

<div class="dverse1"><span class="sd-cn">Ver.</span>
 Well, miscreant, I’ll be there as soon as you;</div>
<div class="dverse"><span class="lnum">45</span> And, after, meet you sooner than you would.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT IV.</h3>

<h4 class="h4main"><span class="dnavigate">ada</span> <span class="smcaps">S<span>CENE</span></span> I. <i>Paris. A hall of
state</i>.</h4>

<div class="sd-schg"><i>Enter the</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">B<span>ISHOP</span></span> <span class="smmaj">OF</span>
<span class="smcaps">W<span>INCHESTER</span>,</span>
<span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">S<span>UFFOLK</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">T<span>ALBOT</span>,</span> <span class="smcaps">E<span>XETER</span>,</span> <i>the</i> Governor of Paris,
<i>and others</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada001" id="lnum-ada001">♦</a>
 <span class="sd-cn">Glou.</span>
Lord bishop, set the crown upon his head.</div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 God save King Henry, of that name the sixth!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada003" id="lnum-ada003">♦</a>
 <span class="sd-cn">Glou.</span>
Now, governor of Paris, take your oath,</div>
<div class="dverse">That you elect no other king but him;</div>
<div class="dverse"><span class="lnum">5</span> Esteem none friends but such as are his friends,</div>
<div class="dverse">And none your foes but such as shall pretend</div>
<div class="dverse">Malicious practices against his state:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada008" id="lnum-ada008">♦</a>
This shall ye do, so help you righteous God!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">F<span>ASTOLFE</span></span>.</div>

<div class="dverse1"><span class="sd-cn">Fast.</span>
 My gracious sovereign, as I rode from Calais,</div>
<div class="dverse"><span class="lnum">10</span> To haste unto your coronation,</div>
<div class="dverse">A letter was deliver’d to my hands,</div>
<div class="dverse">Writ to your grace from the Duke of Burgundy.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Shame to the Duke of Burgundy and thee!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada014" id="lnum-ada014">♦</a>
I vow’d, base knight, when I did meet thee next,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada015" id="lnum-ada015">15</a>
 To tear the garter from thy craven’s leg,
 <span class="sd-verseend">[<i>Plucking it off.</i></span></div>
<div class="dverse">Which I have done, because unworthily</div>
<div class="dverse">Thou wast installed in that high degree.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada018" id="lnum-ada018">♦</a>
Pardon me, princely Henry, and the rest:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada019" id="lnum-ada019">♦</a>
This dastard, at the battle of Patay,</div>
<div class="dverse"><span class="lnum">20</span> When but in all I was six thousand strong</div>
<div class="dverse">And that the French were almost ten to one,</div>
<div class="dverse">Before we met or that a stroke was given,</div>
<div class="dverse">Like to a trusty squire did run away:</div>
<div class="dverse">In which assault we lost twelve hundred men:</div>
<div class="dverse"><span class="lnum">25</span> Myself and divers gentlemen beside</div>
<div class="dverse">Were there surprised and taken prisoners.</div>
<div class="dverse">Then judge, great lords, if I have done amiss;</div>
<div class="dverse">Or whether that such cowards ought to wear</div>
<div class="dverse">This ornament of knighthood, yea or no.</div>

<div class="dverse"><span class="lnum">30</span> <i>Glou</i>. To say the truth, this fact was infamous</div>
<div class="dverse">And ill beseeming any common man,</div>
<div class="dverse">Much more a knight, a captain and a leader.</div>

<div class="dverse"><i>Tal</i>. When first this order was ordain’d, my lords,</div>
<div class="dverse">Knights of the garter were of noble birth,</div>
<div class="dverse"><span class="lnum">35</span> Valiant and virtuous, full of haughty courage,</div>
<div class="dverse">Such as were grown to credit by the wars;</div>
<div class="dverse">Not fearing death, nor shrinking for distress,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada038" id="lnum-ada038">♦</a>
But always resolute in most extremes.</div>
<div class="dverse">He then that is not furnish’d in this sort</div>
<div class="dverse"><span class="lnum">40</span> Doth but usurp the sacred name of knight,</div>
<div class="dverse">Profaning this most honourable order,</div>
<div class="dverse">And should, if I were worthy to be judge,</div>
<div class="dverse">Be quite degraded, like a hedge-born swain</div>
<div class="dverse">That doth presume to boast of gentle blood.</div>

<div class="dverse"><span class="lnum">45</span> <i>King</i>. Stain to thy countrymen, thou hear’st thy doom!</div>
<div class="dverse">Be packing, therefore, thou that wast a knight:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada047" id="lnum-ada047">♦</a>
 Henceforth we banish thee, on pain of death.
 <span class="sd-verseend">[<i>Exit Fastolfe.</i></span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada048" id="lnum-ada048">♦</a>
And now, my lord protector, view the letter</div>
<div class="dverse">Sent from our uncle Duke of Burgundy.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Glou.</span>  What means his grace, that he hath changed his style?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada051" id="lnum-ada051">♦</a>
No more but, plain and bluntly, <span class="smprint">‘To the king!’</span></div>
<div class="dverse">Hath he forgot he is his sovereign?</div>
<div class="dverse">Or doth this churlish superscription</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada054" id="lnum-ada054">♦</a>
Pretend some alteration in good will?</div>
<div class="dverse lhclose"><a class="lnum pginternal" href="#lnote-ada055" id="lnum-ada055">55</a>
 What’s here?
 <span class="sd-inline">[<i>Reads</i>]</span>
 <span class="smprint">‘I have, upon especial cause,</span></div>
<div class="dverse lhclose"><a class="lnum pginternal" href="#lnote-ada056" id="lnum-ada056">♦</a>
 <span class="smprint">Moved with compassion of my country’s wreck,</span></div>
<div class="dverse lhclose">
 <span class="smprint">Together with the pitiful complaints</span></div>
<div class="dverse lhclose">
 <span class="smprint">Of such as your oppression feeds upon,</span></div>
<div class="dverse lhclose">
 <span class="smprint">Forsaken your pernicious faction</span></div>
<div class="dverse lhclose"><span class="lnum">60</span>
 <span class="smprint">And join’d with Charles, the rightful King of France.’</span></div>
<div class="dverse">O monstrous treachery! can this be so,</div>
<div class="dverse">That in alliance, amity and oaths,</div>
<div class="dverse">There should be found such false dissembling guile?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 What! doth my uncle Burgundy revolt?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada065" id="lnum-ada065">65</a>
 <span class="sd-cn">Glou.</span>
He doth, my lord, and is become your foe.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Is that the worst this letter doth contain?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 It is the worst, and all, my lord, he writes.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why, then, Lord Talbot there shall talk with him</div>
<div class="dverse">And give him chastisement for this abuse.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada070" id="lnum-ada070">70</a>
How say you, my lord? are you not content?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada071" id="lnum-ada071">♦</a>
 <span class="sd-cn">Tal.</span>
Content, my liege! yes, but that I am prevented,</div>
<div class="dverse">I should have begg’d I might have been employ’d.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Then gather strength, and march unto him straight:</div>
<div class="dverse">Let him perceive how ill we brook his treason</div>
<div class="dverse"><span class="lnum">75</span> And what offence it is to flout his friends.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 I go, my lord, in heart desiring still</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada077" id="lnum-ada077">♦</a>
 You may behold confusion of your foes.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">V<span>ERNON</span></span> <i>and</i> <span class="smcaps">B<span>ASSET</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada078" id="lnum-ada078">♦</a>
 <span class="sd-cn">Ver.</span>
Grant me the combat, gracious sovereign.</div>

<div class="dverse1"><span class="sd-cn">Bas.</span>
 And me, my lord, grant me the combat too.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">York.</span>  This is my servant: hear him, noble prince.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 And this is mine: sweet Henry, favour him.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Be patient, lords; and give them leave to speak.</div>
<div class="dverse">Say, gentlemen, what makes you thus exclaim?</div>
<div class="dverse">And wherefore crave you combat? or with whom?</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Ver.</span>  With him, my lord; for he hath done me wrong.</div>

<div class="dverse1"><span class="sd-cn">Bas.</span>
 And I with him; for he hath done me wrong.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada087" id="lnum-ada087">♦</a>
 <span class="sd-cn">K. Hen.</span>
What is that wrong whereof you both complain?</div>
<div class="dverse">First let me know, and then I’ll answer you.</div>

<div class="dverse1"><span class="sd-cn">Bas.</span>
 Crossing the sea from England into France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada090" id="lnum-ada090">90</a>
This fellow here, with envious carping tongue,</div>
<div class="dverse">Upbraided me about the rose I wear;</div>
<div class="dverse">Saying, the sanguine colour of the leaves</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada093" id="lnum-ada093">♦</a>
Did represent my master’s blushing cheeks,</div>
<div class="dverse">When stubbornly he did repugn the truth</div>
<div class="dverse"><span class="lnum">95</span> About a certain question in the law</div>
<div class="dverse">Argued betwixt the Duke of York and him;</div>
<div class="dverse">With other vile and ignominious terms:</div>
<div class="dverse">In confutation of which rude reproach</div>
<div class="dverse">And in defence of my lord’s worthiness,</div>
<div class="dverse"><span class="lnum">100</span> I crave the benefit of law of arms.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada101" id="lnum-ada101">♦</a>
 <span class="sd-cn">Ver.</span>
And that is my petition, noble lord:</div>
<div class="dverse">For though he seem with forged quaint conceit</div>
<div class="dverse">To set a gloss upon his bold intent,</div>
<div class="dverse">Yet know, my lord, I was provoked by him;</div>
<div class="dverse"><span class="lnum">105</span> And he first took exceptions at this badge,</div>
<div class="dverse">Pronouncing that the paleness of this flower</div>
<div class="dverse">Bewray’d the faintness of my master’s heart.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Will not this malice, Somerset, be left?</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Your private grudge, my Lord of York, will out,</div>
<div class="dverse"><span class="lnum">110</span> Though ne’er so cunningly you smother it.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Good Lord, what madness rules in brainsick men,</div>
<div class="dverse">When for so slight and frivolous a cause</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada113" id="lnum-ada113">♦</a>
Such factious emulations shall arise!</div>
<div class="dverse">Good cousins both, of York and Somerset,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada115" id="lnum-ada115">115</a>
Quiet yourselves, I pray, and be at peace.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Let this dissension first be tried by fight,</div>
<div class="dverse">And then your highness shall command a peace.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 The quarrel toucheth none but us alone;</div>
<div class="dverse">Betwixt ourselves let us decide it then.</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">York.</span>  There is my pledge; accept it, Somerset.</div>

<div class="dverse1"><span class="sd-cn">Ver.</span>
 Nay, let it rest where it began at first.</div>

<div class="dverse1"><span class="sd-cn">Bas.</span>
 Confirm it so, mine honourable lord.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Confirm it so! Confounded be your strife!</div>
<div class="dverse">And perish ye, with your audacious prate!</div>
<div class="dverse"><span class="lnum">125</span> Presumptuous vassals, are you not ashamed</div>
<div class="dverse">With this immodest clamorous outrage</div>
<div class="dverse">To trouble and disturb the king and us?</div>
<div class="dverse">And you, my lords, methinks you do not well</div>
<div class="dverse">To bear with their perverse objections;</div>
<div class="dverse"><span class="lnum">130</span> Much less to take occasion from their mouths</div>
<div class="dverse">To raise a mutiny betwixt yourselves:</div>
<div class="dverse">Let me persuade you take a better course.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada133" id="lnum-ada133">♦</a>
 <span class="sd-cn">Exe.</span>
It grieves his highness: good my lords, be friends.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Come hither, you that would be combatants:</div>
<div class="dverse"><span class="lnum">135</span> Henceforth I charge you, as you love our favour,</div>
<div class="dverse">Quite to forget this quarrel and the cause.</div>
<div class="dverse">And you, my lords, remember where we are;</div>
<div class="dverse">In France, amongst a fickle wavering nation:</div>
<div class="dverse">If they perceive dissension in our looks</div>
<div class="dverse"><span class="lnum">140</span> And that within ourselves we disagree,</div>
<div class="dverse">How will their grudging stomachs be provoked</div>
<div class="dverse">To wilful disobedience, and rebel!</div>
<div class="dverse">Beside, what infamy will there arise,</div>
<div class="dverse">When foreign princes shall be certified</div>
<div class="dverse"><span class="lnum">145</span> That for a toy, a thing of no regard,</div>
<div class="dverse">King Henry’s peers and chief nobility</div>
<div class="dverse">Destroy’d themselves, and lost the realm of France!</div>
<div class="dverse">O, think upon the conquest of my father,</div>
<div class="dverse">My tender years, and let us not forego</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada150" id="lnum-ada150">150</a>
That for a trifle that was bought with blood!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada151" id="lnum-ada151">♦</a>
Let me be umpire in this doubtful strife.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada152" id="lnum-ada152">♦</a>
 I see no reason, if I wear this rose,
 <span class="sd-verseend">[<i>Putting on a red rose.</i></span></div>
<div class="dverse">That any one should therefore be suspicious</div>
<div class="dverse">I more incline to Somerset than York:</div>
<div class="dverse"><span class="lnum">155</span> Both are my kinsmen, and I love them both:</div>
<div class="dverse">As well they may upbraid me with my crown,</div>
<div class="dverse">Because, forsooth, the king of Scots is crown’d.</div>
<div class="dverse">But your discretions better can persuade</div>
<div class="dverse">Than I am able to instruct or teach:</div>
<div class="dverse"><span class="lnum">160</span> And therefore, as we hither came in peace,</div>
<div class="dverse">So let us still continue peace and love.</div>
<div class="dverse">Cousin of York, we institute your grace</div>
<div class="dverse">To be our regent in these parts of France:</div>
<div class="dverse">And, good my Lord of Somerset, unite</div>
<div class="dverse"><span class="lnum">165</span> Your troops of horsemen with his bands of foot;</div>
<div class="dverse">And, like true subjects, sons of your progenitors,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada167" id="lnum-ada167">♦</a>
Go cheerfully together and digest</div>
<div class="dverse">Your angry choler on your enemies.</div>
<div class="dverse">Ourself, my lord protector and the rest</div>
<div class="dverse"><span class="lnum">170</span> After some respite will return to Calais;</div>
<div class="dverse">From thence to England; where I hope ere long</div>
<div class="dverse">To be presented, by your victories,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada173" id="lnum-ada173">♦</a>
 With Charles, Alençon and that traitorous rout.
 <span class="sd-verseend">[<i>Flourish. Exeunt all but York, Warwick, Exeter and Vernon.</i></span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 My Lord of York, I promise you, the king</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada175" id="lnum-ada175">175</a>
Prettily, methought, did play the orator.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 And so he did; but yet I like it not,</div>
<div class="dverse">In that he wears the badge of Somerset.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Tush, that was but his fancy, blame him not;</div>
<div class="dverse">I dare presume, sweet prince, he thought no harm.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ada180" id="lnum-ada180">180</a>
 <span class="sd-cn">York.</span>
An if I wist he did,—but let it rest;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada181" id="lnum-ada181">♦</a>
 Other affairs must now be managed.
 <span class="sd-verseend">[<i>Exeunt all but Exeter.</i></span></div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 Well didst thou, Richard, to suppress thy voice;</div>
<div class="dverse">For, had the passions of thy heart burst out,</div>
<div class="dverse">I fear we should have seen decipher’d there</div>
<div class="dverse"><span class="lnum">185</span> More rancorous spite, more furious raging broils,</div>
<div class="dverse">Than yet can be imagined or supposed.</div>
<div class="dverse">But howsoe’er, no simple man that sees</div>
<div class="dverse">This jarring discord of nobility,</div>
<div class="dverse">This shouldering of each other in the court,</div>
<div class="dverse"><span class="lnum">190</span> This factious bandying of their favourites,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada191" id="lnum-ada191">♦</a>
But that it doth presage some ill event.</div>
<div class="dverse">’Tis much when sceptres are in children’s hands;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada193" id="lnum-ada193">♦</a>
But more when envy breeds unkind division;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ada194" id="lnum-ada194">♦</a>
 There comes the ruin, there begins confusion.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">adb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>Before
Bourdeaux</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">T<span>ALBOT</span>,</span> <i>with trump and
drum</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adb001" id="lnum-adb001">♦</a>
 <span class="sd-cn">Tal.</span>
Go to the gates of Bourdeaux, trumpeter;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb002" id="lnum-adb002">♦</a>
Summon their general unto the wall.</div>

<div class="sd-entry"><i>Trumpet sounds. Enter</i> General <i>and others, aloft.</i></div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-adb003" id="lnum-adb003">♦</a>
English John Talbot, captains, calls you forth,</div>
<div class="dverse">Servant in arms to Harry King of England;</div>
<div class="dverse"><span class="lnum">5</span> And thus he would: Open your city-gates;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb006" id="lnum-adb006">♦</a>
Be humble to us; call my sovereign yours,</div>
<div class="dverse">And do him homage as obedient subjects;</div>
<div class="dverse">And I’ll withdraw me and my bloody power:</div>
<div class="dverse">But, if you frown upon this proffer’d peace,</div>
<div class="dverse"><span class="lnum">10</span> You tempt the fury of my three attendants,</div>
<div class="dverse">Lean famine, quartering steel, and climbing fire;</div>
<div class="dverse">Who in a moment even with the earth</div>
<div class="dverse">Shall lay your stately and air-braving towers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb014" id="lnum-adb014">♦</a>
If you forsake the offer of their love.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Gen.</span>  Thou ominous and fearful owl of death,</div>
<div class="dverse">Our nation’s terror and their bloody scourge!</div>
<div class="dverse">The period of thy tyranny approacheth.</div>
<div class="dverse">On us thou canst not enter but by death;</div>
<div class="dverse">For, I protest, we are well fortified</div>
<div class="dverse"><span class="lnum">20</span> And strong enough to issue out and fight:</div>
<div class="dverse">If thou retire, the Dauphin, well appointed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb022" id="lnum-adb022">♦</a>
Stands with the snares of war to tangle thee:</div>
<div class="dverse">On either hand thee there are squadrons pitch’d,</div>
<div class="dverse">To wall thee from the liberty of flight;</div>
<div class="dverse"><span class="lnum">25</span> And no way canst thou turn thee for redress,</div>
<div class="dverse">But death doth front thee with apparent spoil</div>
<div class="dverse">And pale destruction meets thee in the face.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb028" id="lnum-adb028">♦</a>
Ten thousand French have ta’en the sacrament</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb029" id="lnum-adb029">♦</a>
To rive their dangerous artillery</div>
<div class="dverse"><span class="lnum">30</span> Upon no Christian soul but English Talbot.</div>
<div class="dverse">Lo, there thou stand’st, a breathing valiant man,</div>
<div class="dverse">Of an invincible unconquer’d spirit!</div>
<div class="dverse">This is the latest glory of thy praise</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb034" id="lnum-adb034">♦</a>
That I, thy enemy, due thee withal;</div>
<div class="dverse"><span class="lnum">35</span> For ere the glass, that now begins to run,</div>
<div class="dverse">Finish the process of his sandy hour,</div>
<div class="dverse">These eyes, that see thee now well coloured,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb038" id="lnum-adb038">♦</a>
 Shall see thee wither’d, bloody, pale and dead.
 <span class="sd-verseend">[<i>Drum afar off.</i></span></div>
<div class="dverse">Hark! hark! the Dauphin’s drum, a warning bell,</div>
<div class="dverse"><span class="lnum">40</span> Sings heavy music to thy timorous soul;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb041" id="lnum-adb041">♦</a>
 And mine shall ring thy dire departure out.
 <span class="sd-verseend">[<i>Exeunt General, &amp;c.</i></span></div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 He fables not; I hear the enemy:</div>
<div class="dverse">Out, some light horsemen, and peruse their wings.</div>
<div class="dverse">O, negligent and heedless discipline!</div>
<div class="dverse"><span class="lnum">45</span> How are we park’d and bounded in a pale,</div>
<div class="dverse">A little herd of England’s timorous deer,</div>
<div class="dverse">Mazed with a yelping kennel of French curs!</div>
<div class="dverse">If we be English deer, be then in blood;</div>
<div class="dverse">Not rascal-like, to fall down with a pinch,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb050" id="lnum-adb050">50</a>
But rather, moody-mad and desperate stags,</div>
<div class="dverse">Turn on the bloody hounds with heads of steel</div>
<div class="dverse">And make the cowards stand aloof at bay:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb053" id="lnum-adb053">♦</a>
Sell every man his life as dear as mine,</div>
<div class="dverse">And they shall find dear deer of us, my friends.</div>
<div class="dverse"><span class="lnum">55</span> God and Saint George, Talbot and England’s right,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adb056" id="lnum-adb056">♦</a>
 Prosper our colours in this dangerous fight!
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">adc</span> <span class="smcaps">S<span>CENE</span></span> III. <i>Plains in
Gascony</i>.</h4>

<div class="sd-schg"><i>Enter a</i> Messenger <i>that meets</i> <span class="smcaps">Y<span>ORK</span>.</span> <i>Enter</i> <span class="smcaps">Y<span>ORK</span></span> <i>with trumpet and many</i>
Soldiers.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adc001" id="lnum-adc001">♦</a>
 <span class="sd-cn">York.</span>
Are not the speedy scouts return’d again,</div>
<div class="dverse">That dogg’d the mighty army of the Dauphin?</div>

<div class="dverse"><i>Mess</i>. They are return’d, my lord, and give it out</div>
<div class="dverse">That he is march’d to Bourdeaux with his power,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc005" id="lnum-adc005">5</a>
To fight with Talbot: as he march’d along,</div>
<div class="dverse">By your espials were discovered</div>
<div class="dverse">Two mightier troops than that the Dauphin led,</div>
<div class="dverse">Which join’d with him and made their march for Bourdeaux.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 A plague upon that villain Somerset,</div>
<div class="dverse"><span class="lnum">10</span> That thus delays my promised supply</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc011" id="lnum-adc011">♦</a>
Of horsemen, that were levied for this siege!</div>
<div class="dverse">Renowned Talbot doth expect my aid,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc013" id="lnum-adc013">♦</a>
And I am lowted by a traitor villain</div>
<div class="dverse">And cannot help the noble chevalier:</div>
<div class="dverse"><span class="lnum">15</span> God comfort him in this necessity!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc016" id="lnum-adc016">♦</a>
If he miscarry, farewell wars in France.</div>

<div class="sd-entry"><i>Enter</i> Sir <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">L<span>UCY</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adc017" id="lnum-adc017">♦</a>
 <span class="sd-cn">Lucy.</span>
Thou princely leader of our English strength,</div>
<div class="dverse">Never so needful on the earth of France,</div>
<div class="dverse">Spur to the rescue of the noble Talbot,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc020" id="lnum-adc020">20</a>
Who now is girdled with a waist of iron</div>
<div class="dverse">And hemm’d about with grim destruction:</div>
<div class="dverse">To Bourdeaux, warlike duke! to Bourdeaux, York!</div>
<div class="dverse">Else, farewell Talbot, France, and England’s honour.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 O God, that Somerset, who in proud heart</div>
<div class="dverse"><span class="lnum">25</span> Doth stop my cornets, were in Talbot’s place!</div>
<div class="dverse">So should we save a valiant gentleman</div>
<div class="dverse">By forfeiting a traitor and a coward.</div>
<div class="dverse">Mad ire and wrathful fury makes me weep,</div>
<div class="dverse">That thus we die, while remiss traitors sleep.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adc030" id="lnum-adc030">30</a>
 <span class="sd-cn">Lucy.</span>
O, send some succour to the distress’d lord!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 He dies, we lose; I break my warlike word;</div>
<div class="dverse">We mourn, France smiles; we lose, they daily get;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc033" id="lnum-adc033">♦</a>
All ’long of this vile traitor Somerset.</div>

<div class="dverse1"><span class="sd-cn">Lucy.</span>
 Then God take mercy on brave Talbot’s soul;</div>
<div class="dverse"><span class="lnum">35</span> And on his son young John, who two hours since</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc036" id="lnum-adc036">♦</a>
I met in travel toward his warlike father!</div>
<div class="dverse">This seven years did not Talbot see his son;</div>
<div class="dverse">And now they meet where both their lives are done.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Alas, what joy shall noble Talbot have</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc040" id="lnum-adc040">40</a>
To bid his young son welcome to his grave?</div>
<div class="dverse">Away! vexation almost stops my breath,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc042" id="lnum-adc042">♦</a>
That sunder’d friends greet in the hour of death.</div>
<div class="dverse">Lucy, farewell: no more my fortune can,</div>
<div class="dverse">But curse the cause I cannot aid the man.</div>
<div class="dverse"><span class="lnum">45</span> Maine, Blois, Poictiers, and Tours, are won away,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc046" id="lnum-adc046">♦</a>
 ’Long all of Somerset and his delay.
 <span class="sd-verseend">[<i>Exit, with his soldiers.</i></span></div>

<div class="dverse1"><span class="sd-cn">Lucy.</span>
 Thus, while the vulture of sedition</div>
<div class="dverse">Feeds in the bosom of such great commanders,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc049" id="lnum-adc049">♦</a>
Sleeping neglection doth betray to loss</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc050" id="lnum-adc050">50</a>
The conquest of our scarce cold conqueror,</div>
<div class="dverse">That ever living man of memory,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc052" id="lnum-adc052">♦</a>
Henry the Fifth: whiles they each other cross,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adc053" id="lnum-adc053">♦</a>
 Lives, honours, lands and all hurry to loss.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">add</span> <span class="smcaps">S<span>CENE</span></span> IV. <i>Other plains in
Gascony</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">S<span>OMERSET</span>,</span> <i>with his army; a</i> Captain
<i>of</i> <span class="smcaps">T<span>ALBOT’S</span></span>
<i>with him</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-add001" id="lnum-add001">♦</a>
 <span class="sd-cn">Som.</span>
It is too late; I cannot send them now:</div>
<div class="dverse">This expedition was by York and Talbot</div>
<div class="dverse">Too rashly plotted: all our general force</div>
<div class="dverse">Might with a sally of the very town</div>
<div class="dverse"><span class="lnum">5</span> Be buckled with: the over-daring Talbot</div>
<div class="dverse">Hath sullied all his gloss of former honour</div>
<div class="dverse">By this unheedful, desperate, wild adventure:</div>
<div class="dverse">York set him on to fight and die in shame,</div>
<div class="dverse">That, Talbot dead, great York might bear the name.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Cap.</span>  Here is Sir William Lucy, who with me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add011" id="lnum-add011">♦</a>
Set from our o’er-match’d forces forth for aid.</div>

<div class="sd-entry"><i>Enter</i> Sir William Lucy.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-add012" id="lnum-add012">♦</a>
 <span class="sd-cn">Som.</span>
How now, Sir William! whither were you sent?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-add013" id="lnum-add013">♦</a>
 <span class="sd-cn">Lucy.</span>
Whither, my lord? from bought and sold Lord Talbot;</div>
<div class="dverse">Who, ring’d about with bold adversity,</div>
<div class="dverse"><span class="lnum">15</span> Cries out for noble York and Somerset,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add016" id="lnum-add016">♦</a>
To beat assailing death from his weak legions:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add017" id="lnum-add017">♦</a>
And whiles the honourable captain there</div>
<div class="dverse">Drops bloody sweat from his war-wearied limbs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add019" id="lnum-add019">♦</a>
And, in advantage lingering, looks for rescue,</div>
<div class="dverse"><span class="lnum">20</span> You, his false hopes, the trust of England’s honour,</div>
<div class="dverse">Keep off aloof with worthless emulation.</div>
<div class="dverse">Let not your private discord keep away</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add023" id="lnum-add023">♦</a>
The levied succours that should lend him aid,</div>
<div class="dverse">While he, renowned noble gentleman,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add025" id="lnum-add025">25</a>
Yields up his life unto a world of odds:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add026" id="lnum-add026">♦</a>
Orleans the Bastard, Charles, Burgundy,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add027" id="lnum-add027">♦</a>
Alençon, Reignier, compass him about,</div>
<div class="dverse">And Talbot perisheth by your default.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 York set him on; York should have sent him aid.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Lucy.</span>  And York as fast upon your grace exclaims;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add031" id="lnum-add031">♦</a>
Swearing that you withhold his levied host,</div>
<div class="dverse">Collected for this expedition.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 York lies; he might have sent and had the horse:</div>
<div class="dverse">I owe him little duty, and less love;</div>
<div class="dverse"><span class="lnum">35</span> And take foul scorn to fawn on him by sending.</div>

<div class="dverse1"><span class="sd-cn">Lucy.</span>
 The fraud of England, not the force of France,</div>
<div class="dverse">Hath now entrapp’d the noble-minded Talbot:</div>
<div class="dverse">Never to England shall he bear his life;</div>
<div class="dverse">But dies, betray’d to fortune by your strife.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Som.</span>  Come, go; I will dispatch the horsemen straight:</div>
<div class="dverse">Within six hours they will be at his aid.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-add042" id="lnum-add042">♦</a>
 <span class="sd-cn">Lucy.</span>
Too late comes rescue: he is ta’en or slain;</div>
<div class="dverse">For fly he could not, if he would have fled;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-add044" id="lnum-add044">♦</a>
And fly would Talbot never, though he might.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Som.</span>  If he be dead, brave Talbot, then adieu!</div>

<div class="dverse1"><span class="sd-cn">Lucy.</span>
 His fame lives in the world, his shame in you.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">ade</span> <span class="smcaps">S<span>CENE</span></span> V. <i>The English camp near
Bourdeaux</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">T<span>ALBOT</span></span> <i>and</i> <span class="smcaps">J<span>OHN</span></span> <i>his son</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ade001" id="lnum-ade001">♦</a>
 <span class="sd-cn">Tal.</span>
O young John Talbot! I did send for thee</div>
<div class="dverse">To tutor thee in stratagems of war,</div>
<div class="dverse">That Talbot’s name might be in thee revived</div>
<div class="dverse">When sapless age and weak unable limbs</div>
<div class="dverse"><span class="lnum">5</span> Should bring thy father to his drooping chair.</div>
<div class="dverse">But, O malignant and ill-boding stars!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ade007" id="lnum-ade007">♦</a>
Now thou art come unto a feast of death,</div>
<div class="dverse">A terrible and unavoided danger:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ade009" id="lnum-ade009">♦</a>
Therefore, dear boy, mount on my swiftest horse;</div>
<div class="dverse"><span class="lnum">10</span> And I’ll direct thee how thou shalt escape</div>
<div class="dverse">By sudden flight: come, dally not, be gone.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 Is my name Talbot? and am I your son?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ade013" id="lnum-ade013">♦</a>
And shall I fly? O, if you love my mother,</div>
<div class="dverse">Dishonour not her honourable name,</div>
<div class="dverse"><span class="lnum">15</span> To make a bastard and a slave of me!</div>
<div class="dverse">The world will say, he is not Talbot’s blood,</div>
<div class="dverse">That basely fled when noble Talbot stood.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Fly, to revenge my death, if I be slain.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 He that flies so will ne’er return again.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Tal.</span>  If we both stay, we both are sure to die.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 Then let me stay; and, father, do you fly:</div>
<div class="dverse">Your loss is great, so your regard should be;</div>
<div class="dverse">My worth unknown, no loss is known in me.</div>
<div class="dverse">Upon my death the French can little boast;</div>
<div class="dverse"><span class="lnum">25</span> In yours they will, in you all hopes are lost.</div>
<div class="dverse">Flight cannot stain the honour you have won;</div>
<div class="dverse">But mine it will, that no exploit have done:</div>
<div class="dverse">You fled for vantage, every one will swear;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ade029" id="lnum-ade029">♦</a>
But, if I bow, they’ll say it was for fear.</div>
<div class="dverse"><span class="lnum">30</span> There is no hope that ever I will stay,</div>
<div class="dverse">If the first hour I shrink and run away.</div>
<div class="dverse">Here on my knee I beg mortality,</div>
<div class="dverse">Rather than life preserved with infamy.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Shall all thy mother’s hopes lie in one tomb?</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">John.</span>  Ay, rather than I’ll shame my mother’s womb.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Upon my blessing, I command thee go.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ade037" id="lnum-ade037">♦</a>
 <span class="sd-cn">John.</span>
To fight I will, but not to fly the foe.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Part of thy father may be saved in thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ade039" id="lnum-ade039">♦</a>
 <span class="sd-cn">John.</span>
No part of him but will be shame in me.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ade040" id="lnum-ade040">40</a>
 <span class="sd-cn">Tal.</span>
Thou never hadst renown, nor canst not lose it.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 Yes, your renowned name: shall flight abuse it?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ade042" id="lnum-ade042">♦</a>
 <span class="sd-cn">Tal.</span>
Thy father’s charge shall clear thee from that stain.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 You cannot witness for me, being slain.</div>
<div class="dverse">If death be so apparent, then both fly.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Tal.</span>  And leave my followers here to fight and die?</div>
<div class="dverse">My age was never tainted with such shame.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 And shall my youth be guilty of such blame?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ade048" id="lnum-ade048">♦</a>
No more can I be sever’d from your side,</div>
<div class="dverse">Than can yourself yourself in twain divide:</div>
<div class="dverse"><span class="lnum">50</span> Stay, go, do what you will, the like do I;</div>
<div class="dverse">For live I will not, if my father die.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ade052" id="lnum-ade052">♦</a>
 <span class="sd-cn">Tal.</span>
Then here I take my leave of thee, fair son,</div>
<div class="dverse">Born to eclipse thy life this afternoon.</div>
<div class="dverse">Come, side by side together live and die;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ade055" id="lnum-ade055">55</a>
 And soul with soul from France to heaven fly.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">adf</span> <span class="smcaps">S<span>CENE</span></span> VI. <i>A field of
battle</i>.</h4>

<div class="sd-schg"><i>Alarum: excursions, wherein</i> <span class="smcaps">T<span>ALBOT’S</span></span> Son <i>is hemmed about, and</i>
<span class="smcaps">T<span>ALBOT</span></span> <i>rescues him</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adf001" id="lnum-adf001">♦</a>
 <span class="sd-cn">Tal.</span>
Saint George and victory! fight, soldiers, fight:</div>
<div class="dverse">The regent hath with Talbot broke his word</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf003" id="lnum-adf003">♦</a>
And left us to the rage of France his sword.</div>
<div class="dverse">Where is John Talbot? Pause, and take thy breath;</div>
<div class="dverse"><span class="lnum">5</span> I gave thee life and rescued thee from death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adf006" id="lnum-adf006">♦</a>
 <span class="sd-cn">John.</span>
O, twice my father, twice am I thy son!</div>
<div class="dverse">The life thou gavest me first was lost and done,</div>
<div class="dverse">Till with thy warlike sword, despite of fate,</div>
<div class="dverse">To my determined time thou gavest new date.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Tal.</span>  When from the Dauphin’s crest thy sword struck fire,</div>
<div class="dverse">It warm’d thy father’s heart with proud desire</div>
<div class="dverse">Of bold-faced victory. Then leaden age,</div>
<div class="dverse">Quicken’d with youthful spleen and warlike rage,</div>
<div class="dverse">Beat down Alençon, Orleans, Burgundy,</div>
<div class="dverse"><span class="lnum">15</span> And from the pride of Gallia rescued thee.</div>
<div class="dverse">The ireful bastard Orleans, that drew blood</div>
<div class="dverse">From thee, my boy, and had the maidenhood</div>
<div class="dverse">Of thy first fight, I soon encountered,</div>
<div class="dverse">And interchanging blows I quickly shed</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf020" id="lnum-adf020">20</a>
Some of his bastard blood; and in disgrace</div>
<div class="dverse">Bespoke him thus; ‘Contaminated base</div>
<div class="dverse">And misbegotten blood I spill of thine,</div>
<div class="dverse">Mean and right poor, for that pure blood of mine</div>
<div class="dverse">Which thou didst force from Talbot, my brave boy:’</div>
<div class="dverse"><span class="lnum">25</span> Here, purposing the Bastard to destroy,</div>
<div class="dverse">Came in strong rescue. Speak, thy father’s care,</div>
<div class="dverse">Art thou not weary, John? how dost thou fare?</div>
<div class="dverse">Wilt thou yet leave the battle, boy, and fly,</div>
<div class="dverse">Now thou art seal’d the son of chivalry?</div>
<div class="dverse"><span class="lnum">30</span> Fly, to revenge my death when I am dead:</div>
<div class="dverse">The help of one stands me in little stead.</div>
<div class="dverse">O, too much folly is it, well I wot,</div>
<div class="dverse">To hazard all our lives in one small boat!</div>
<div class="dverse">If I to-day die not with Frenchmen’s rage,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf035" id="lnum-adf035">35</a>
To-morrow I shall die with mickle age:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf036" id="lnum-adf036">♦</a>
By me they nothing gain an if I stay;</div>
<div class="dverse">’Tis but the shortening of my life one day:</div>
<div class="dverse">In thee thy mother dies, our household’s name,</div>
<div class="dverse">My death’s revenge, thy youth, and England’s fame:</div>
<div class="dverse"><span class="lnum">40</span> All these and more we hazard by thy stay;</div>
<div class="dverse">All these are saved if thou wilt fly away.</div>

<div class="dverse1"><span class="sd-cn">John.</span>
 The sword of Orleans hath not made me smart;</div>
<div class="dverse">These words of yours draw life-blood from my heart:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf044" id="lnum-adf044">♦</a>
On that advantage, bought with such a shame,</div>
<div class="dverse"><span class="lnum">45</span> To save a paltry life and slay bright fame,</div>
<div class="dverse">Before young Talbot from old Talbot fly,</div>
<div class="dverse">The coward horse that bears me fall and die!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf048" id="lnum-adf048">♦</a>
And like me to the peasant boys of France,</div>
<div class="dverse">To be shame’s scorn and subject of mischance!</div>
<div class="dverse"><span class="lnum">50</span> Surely, by all the glory you have won,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf051" id="lnum-adf051">♦</a>
An if I fly, I am not Talbot’s son:</div>
<div class="dverse">Then talk no more of flight, it is no boot;</div>
<div class="dverse">If son to Talbot, die at Talbot’s foot.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Then follow thou thy desperate sire of Crete,</div>
<div class="dverse"><span class="lnum">55</span> Thou Icarus; thy life to me is sweet:</div>
<div class="dverse">If thou wilt fight, fight by thy father’s side;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adf057" id="lnum-adf057">♦</a>
 And, commendable proved, let’s die in pride.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">adg</span> <span class="smcaps">S<span>CENE</span></span> VII. <i>Another part of the
field</i>.</h4>

<div class="sd-schg"><i>Alarum: excursions. Enter old</i> <span class="smcaps">T<span>ALBOT</span></span> <i>led by a</i>
Servant.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg001" id="lnum-adg001">♦</a>
 <span class="sd-cn">Tal.</span>
Where is my other life? mine own is gone;</div>
<div class="dverse">O, where’s young Talbot? where is valiant John?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg003" id="lnum-adg003">♦</a>
Triumphant death, smear’d with captivity,</div>
<div class="dverse">Young Talbot’s valour makes me smile at thee:</div>
<div class="dverse"><span class="lnum">5</span> When he perceived me shrink and on my knee,</div>
<div class="dverse">His bloody sword he brandish’d over me,</div>
<div class="dverse">And, like a hungry lion, did commence</div>
<div class="dverse">Rough deeds of rage and stern impatience;</div>
<div class="dverse">But when my angry guardant stood alone,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg010" id="lnum-adg010">10</a>
Tendering my ruin and assail’d of none,</div>
<div class="dverse">Dizzy-eyed fury and great rage of heart</div>
<div class="dverse">Suddenly made him from my side to start</div>
<div class="dverse">Into the clustering battle of the French;</div>
<div class="dverse">And in that sea of blood my boy did drench</div>
<div class="dverse"><span class="lnum">15</span> His over-mounting spirit, and there died,</div>
<div class="dverse">My Icarus, my blossom, in his pride.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg017" id="lnum-adg017">♦</a>
 <span class="sd-cn">Serv.</span>
O my dear lord, lo, where your son is borne!</div>

<div class="sd-entry"><i>Enter</i> Soldiers, <i>with the body of young</i> <span class="smcaps">T<span>ALBOT</span></span>.</div>

<div class="dverse1"><span class="sd-cn">Tal.</span>
 Thou antic death, which laugh’st us here to scorn,</div>
<div class="dverse">Anon, from thy insulting tyranny,</div>
<div class="dverse"><span class="lnum">20</span> Coupled in bonds of perpetuity,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg021" id="lnum-adg021">♦</a>
Two Talbots, winged through the lither sky,</div>
<div class="dverse">In thy despite shall ’scape mortality.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg023" id="lnum-adg023">♦</a>
O thou, whose wounds become hard-favour’d death,</div>
<div class="dverse">Speak to thy father ere thou yield thy breath!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg025" id="lnum-adg025">25</a>
Brave death by speaking, whether he will or no;</div>
<div class="dverse">Imagine him a Frenchman and thy foe.</div>
<div class="dverse">Poor boy! he smiles, methinks, as who should say,</div>
<div class="dverse">Had death been French, then death had died to-day.</div>
<div class="dverse">Come, come and lay him in his father’s arms:</div>
<div class="dverse"><span class="lnum">30</span> My spirit can no longer bear these harms.</div>
<div class="dverse">Soldiers, adieu! I have what I would have,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg032" id="lnum-adg032">♦</a>
 Now my old arms are young John Talbot’s grave.
 <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>HARLES</span>,</span> <span class="smcaps">A<span>LENÇON</span>,</span> <span class="smcaps">B<span>URGUNDY</span>,</span> Bastard, <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <i>and forces</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg033" id="lnum-adg033">♦</a>
 <span class="sd-cn">Char.</span>
Had York and Somerset brought rescue in,</div>
<div class="dverse">We should have found a bloody day of this.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg035" id="lnum-adg035">35</a>
 <span class="sd-cn">Bast.</span>
How the young whelp of Talbot’s, raging-wood,</div>
<div class="dverse">Did flesh his puny sword in Frenchmen’s blood!</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Once I encounter’d him, and thus I said:</div>
<div class="dverse">‘Thou maiden youth, be vanquish’d by a maid:’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg039" id="lnum-adg039">♦</a>
But, with a proud majestical high scorn,</div>
<div class="dverse"><span class="lnum">40</span> He answer’d thus: ‘Young Talbot was not born</div>
<div class="dverse">To be the pillage of a giglot wench:’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg042" id="lnum-adg042">♦</a>
So, rushing in the bowels of the French,</div>
<div class="dverse">He left me proudly, as unworthy fight.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 Doubtless he would have made a noble knight:</div>
<div class="dverse"><span class="lnum">45</span> See, where he lies inhearsed in the arms</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg046" id="lnum-adg046">♦</a>
Of the most bloody nurser of his harms!</div>

<div class="dverse1"><span class="sd-cn">Bast.</span>
 Hew them to pieces, hack their bones asunder,</div>
<div class="dverse">Whose life was England’s glory, Gallia’s wonder.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 O, no, forbear! for that which we have fled</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg050" id="lnum-adg050">50</a>
During the life, let us not wrong it dead.</div>

<div class="sd-entry"><i>Enter</i> Sir <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">L<span>UCY</span>,</span> <i>attended;</i> Herald <i>of the</i>
French <i>preceding</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg051" id="lnum-adg051">♦</a>
 <span class="sd-cn">Lucy.</span>
Herald, conduct me to the Dauphin’s tent,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg052" id="lnum-adg052">♦</a>
To know who hath obtain’d the glory of the day.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 On what submissive message art thou sent?</div>

<div class="dverse1"><span class="sd-cn">Lucy.</span>
 Submission, Dauphin! ’tis a mere French word;</div>
<div class="dverse"><span class="lnum">55</span> We English warriors wot not what it means.</div>
<div class="dverse">I come to know what prisoners thou hast ta’en</div>
<div class="dverse">And to survey the bodies of the dead.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 For prisoners ask’st thou? hell our prison is.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg059" id="lnum-adg059">♦</a>
But tell me whom thou seek’st.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg060" id="lnum-adg060">60</a>
 <span class="sd-cn">Lucy.</span>
But where’s the great Alcides of the field,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg061" id="lnum-adg061">♦</a>
Valiant Lord Talbot, Earl of Shrewsbury,</div>
<div class="dverse">Created, for his rare success in arms,</div>
<div class="dverse">Great Earl of Washford, Waterford and Valence;</div>
<div class="dverse">Lord Talbot of Goodrig and Urchinfield,</div>
<div class="dverse"><span class="lnum">65</span> Lord Strange of Blackmere, Lord Verdun of Alton,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg066" id="lnum-adg066">♦</a>
Lord Cromwell of Wingfield, Lord Furnival of Sheffield,</div>
<div class="dverse">The thrice-victorious Lord of Falconbridge;</div>
<div class="dverse">Knight of the noble order of Saint George,</div>
<div class="dverse">Worthy Saint Michael and the Golden Fleece;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg070" id="lnum-adg070">70</a>
Great marshal to Henry the Sixth</div>
<div class="dverse">Of all his wars within the realm of France?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg072" id="lnum-adg072">♦</a>
 <span class="sd-cn">Puc.</span>
Here is a silly stately style indeed!</div>
<div class="dverse">The Turk, that two and fifty kingdoms hath,</div>
<div class="dverse">Writes not so tedious a style as this.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg075" id="lnum-adg075">75</a>
Him that thou magnifiest with all these titles</div>
<div class="dverse">Stinking and fly-blown lies here at our feet.</div>

<div class="dverse1"><span class="sd-cn">Lucy.</span>
 Is Talbot slain, the Frenchmen’s only scourge,</div>
<div class="dverse">Your kingdom’s terror and black Nemesis?</div>
<div class="dverse">O, were mine eye-balls into bullets turn’d,</div>
<div class="dverse"><span class="lnum">80</span> That I in rage might shoot them at your faces!</div>
<div class="dverse">O, that I could but call these dead to life!</div>
<div class="dverse">It were enough to fright the realm of France:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg083" id="lnum-adg083">♦</a>
Were but his picture left amongst you here,</div>
<div class="dverse">It would amaze the proudest of you all.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg085" id="lnum-adg085">85</a>
Give me their bodies, that I may bear them hence</div>
<div class="dverse">And give them burial as beseems their worth.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 I think this upstart is old Talbot’s ghost,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg088" id="lnum-adg088">♦</a>
He speaks with such a proud commanding spirit.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg089" id="lnum-adg089">♦</a>
For God’s sake, let him have ’em; to keep them here,</div>
<div class="dverse"><span class="lnum">90</span> They would but stink, and putrefy the air.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Go, take their bodies hence.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg092" id="lnum-adg092">♦</a>
 <span class="sd-cn">Lucy.</span>
I’ll bear them hence; but from their ashes shall be rear’d</div>
<div class="dverse">A phœnix that shall make all France afeard.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-adg094" id="lnum-adg094">♦</a>
 <span class="sd-cn">Char.</span>
So we be rid of them, do with ’em what thou wilt.</div>
<div class="dverse"><span class="lnum">95</span> And now to Paris, in this conquering vein:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-adg096" id="lnum-adg096">♦</a>
 All will be ours, now bloody Talbot’s slain.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT V.</h3>

<h4 class="h4main"><span class="dnavigate">aea</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>London. The
palace</i>.</h4>

<div class="sd-schg"><i>Sennet. Enter</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <i>and</i> <span class="smcaps">E<span>XETER</span>.</span></div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aea001" id="lnum-aea001">♦</a>
 <span class="sd-cn">King.</span>
Have you perused the letters from the pope,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea002" id="lnum-aea002">♦</a>
The emperor and the Earl of Armagnac?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 I have, my lord: and their intent is this:</div>
<div class="dverse">They humbly sue unto your excellence</div>
<div class="dverse"><span class="lnum">5</span> To have a godly peace concluded of</div>
<div class="dverse">Between the realms of England and of France.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aea007" id="lnum-aea007">♦</a>
 <span class="sd-cn">King.</span>
How doth your grace affect their motion?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Well, my good lord; and as the only means</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea009" id="lnum-aea009">♦</a>
To stop effusion of our Christian blood</div>
<div class="dverse"><span class="lnum">10</span> And stablish quietness on every side.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Ay, marry, uncle; for I always thought</div>
<div class="dverse">It was both impious and unnatural</div>
<div class="dverse">That such immanity and bloody strife</div>
<div class="dverse">Should reign among professors of one faith.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Glou.</span>  Beside, my lord, the sooner to effect</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea016" id="lnum-aea016">♦</a>
And surer bind this knot of amity,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea017" id="lnum-aea017">♦</a>
The Earl of Armagnac, near knit to Charles,</div>
<div class="dverse">A man of great authority in France,</div>
<div class="dverse">Proffers his only daughter to your grace</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea020" id="lnum-aea020">20</a>
In marriage, with a large and sumptuous dowry.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aea021" id="lnum-aea021">♦</a>
 <span class="sd-cn">King.</span>
Marriage, uncle! alas, my years are young!</div>
<div class="dverse">And fitter is my study and my books</div>
<div class="dverse">Than wanton dalliance with a paramour.</div>
<div class="dverse">Yet call the ambassadors; and, as you please,</div>
<div class="dverse"><span class="lnum">25</span> So let them have their answers every one:</div>
<div class="dverse">I shall be well content with any choice</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea027" id="lnum-aea027">♦</a>
Tends to God’s glory and my country’s weal.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">W<span>INCHESTER</span></span> <i>in Cardinal’s habit, a</i>
Legate <i>and two</i> Ambassadors.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 What! is my Lord of Winchester install’d,</div>
<div class="dverse">And call’d unto a cardinal’s degree?</div>
<div class="dverse"><span class="lnum">30</span> Then I perceive that will be verified</div>
<div class="dverse">Henry the Fifth did sometime prophesy,</div>
<div class="dverse">‘If once he come to be a cardinal,</div>
<div class="dverse">He’ll make his cap co-equal with the crown.’</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 My lords ambassadors, your several suits</div>
<div class="dverse"><span class="lnum">35</span> Have been consider’d and debated on.</div>
<div class="dverse">Your purpose is both good and reasonable;</div>
<div class="dverse">And therefore are we certainly resolved</div>
<div class="dverse">To draw conditions of a friendly peace;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea039" id="lnum-aea039">♦</a>
Which by my Lord of Winchester we mean</div>
<div class="dverse"><span class="lnum">40</span> Shall be transported presently to France.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And for the proffer of my lord your master,</div>
<div class="dverse">I have inform’d his highness so at large</div>
<div class="dverse">As liking of the lady’s virtuous gifts,</div>
<div class="dverse">Her beauty and the value of her dower,</div>
<div class="dverse"><span class="lnum">45</span> He doth intend she shall be England’s queen.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aea046" id="lnum-aea046">♦</a>
 <span class="sd-cn">King.</span>
In argument and proof of which contract,</div>
<div class="dverse">Bear her this jewel, pledge of my affection.</div>
<div class="dverse">And so, my lord protector, see them guarded</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea049" id="lnum-aea049">♦</a>
And safely brought to Dover; where inshipp’d</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea050" id="lnum-aea050">50</a>
 Commit them to the fortune of the sea.
 <span class="sd-verseend">[<i>Exeunt all but Winchester and Legate.</i></span></div>

<div class="dverse1"><span class="sd-cn">Win.</span>
 Stay, my lord legate: you shall first receive</div>
<div class="dverse">The sum of money which I promised</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea053" id="lnum-aea053">♦</a>
Should be deliver’d to his holiness</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea054" id="lnum-aea054">♦</a>
For clothing me in these grave ornaments.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aea055" id="lnum-aea055">55</a>
 <span class="sd-cn">Leg.</span>
I will attend upon your lordship’s leisure.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aea056" id="lnum-aea056">♦</a>
 <span class="sd-cn">Win.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Now Winchester will not submit, I trow,</div>
<div class="dverse">Or be inferior to the proudest peer.</div>
<div class="dverse">Humphrey of Gloucester, thou shalt well perceive</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea059" id="lnum-aea059">♦</a>
That, neither in birth or for authority,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea060" id="lnum-aea060">60</a>
The bishop will be overborne by thee:</div>
<div class="dverse">I’ll either make thee stoop and bend thy knee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aea062" id="lnum-aea062">♦</a>
 Or sack this country with a mutiny.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aeb</span> <span class="smcaps">S<span>CENE</span></span> II. <i>France.</i> <i>Plains in
Anjou</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">C<span>HARLES</span>,</span> <span class="smcaps">B<span>URGUNDY</span>,</span> <span class="smcaps">A<span>LENÇON</span>,</span> <span class="smcaps">B<span>ASTARD</span>,</span> <span class="smcaps">R<span>EIGNIER</span>,</span>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <i>and Forces</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aeb001" id="lnum-aeb001">♦</a>
 <span class="sd-cn">Char.</span>
These news, my lords, may cheer our drooping spirits:</div>
<div class="dverse">’Tis said the stout Parisians do revolt</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aeb003" id="lnum-aeb003">♦</a>
And turn again unto the warlike French.</div>

<div class="dverse1"><span class="sd-cn">Alen.</span>
 Then march to Paris, royal Charles of France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aeb005" id="lnum-aeb005">5</a>
And keep not back your powers in dalliance.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Peace be amongst them, if they turn to us;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aeb007" id="lnum-aeb007">♦</a>
Else, ruin combat with their palaces!</div>

<div class="sd-entry"><i>Enter</i> Scout.</div>

<div class="dverse1"><span class="sd-cn">Scout.</span>
 Success unto our valiant general,</div>
<div class="dverse">And happiness to his accomplices!</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Char.</span>  What tidings send our scouts? I prithee, speak.</div>

<div class="dverse1"><span class="sd-cn">Scout.</span>
 The English army, that divided was</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aeb012" id="lnum-aeb012">♦</a>
Into two parties, is now conjoin’d in one,</div>
<div class="dverse">And means to give you battle presently.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Somewhat too sudden, sirs, the warning is;</div>
<div class="dverse"><span class="lnum">15</span> But we will presently provide for them.</div>

<div class="dverse1"><span class="sd-cn">Bur.</span>
 I trust the ghost of Talbot is not there:</div>
<div class="dverse">Now he is gone, my lord, you need not fear.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Of all base passions, fear is most accursed.</div>
<div class="dverse">Command the conquest, Charles, it shall be thine,</div>
<div class="dverse"><span class="lnum">20</span> Let Henry fret and all the world repine.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Then on, my lords; and France be fortunate!
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aec</span> <span class="smcaps">S<span>CENE</span></span> III. <i>Before
Angiers</i>.</h4>

<div class="sd-schg"><i>Alarum. Excursions. Enter</i>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>.</span></div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec001" id="lnum-aec001">♦</a>
 <span class="sd-cn">Puc.</span>
The regent conquers, and the Frenchmen fly.</div>
<div class="dverse">Now help, ye charming spells and periapts;</div>
<div class="dverse">And ye choice spirits that admonish me</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec004" id="lnum-aec004">♦</a>
 And give me signs of future accidents.
 <span class="sd-verseend">[<i>Thunder.</i></span></div>
<div class="dverse"><span class="lnum">5</span>
 You speedy helpers, that are substitutes</div>
<div class="dverse">Under the lordly monarch of the north,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec007" id="lnum-aec007">♦</a>
Appear and aid me in this enterprise.</div>

<div class="sd-entry"><i>Enter</i> Fiends.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-aec008" id="lnum-aec008">♦</a>
This speedy and quick appearance argues proof</div>
<div class="dverse">Of your accustom’d diligence to me.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec010" id="lnum-aec010">10</a>
Now, ye familiar spirits, that are cull’d</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec011" id="lnum-aec011">♦</a>
Out of the powerful regions under earth,</div>
<div class="dverse">Help me this once, that France may get the field.
 <span class="sd-verseend">[<i>They walk, and speak not.</i></span></div>
<div class="dverse">O, hold me not with silence over-long!</div>
<div class="dverse">Where I was wont to feed you with my blood,</div>
<div class="dverse"><span class="lnum">15</span> I’ll lop a member off and give it you</div>
<div class="dverse">In earnest of a further benefit,</div>
<div class="dverse">So you do condescend to help me now.
 <span class="sd-verseend">[<i>They hang their heads.</i></span></div>
<div class="dverse">No hope to have redress? My body shall</div>
<div class="dverse">Pay recompense, if you will grant my suit.
 <span class="sd-verseend">[<i>They shake their heads.</i></span></div>
<div class="dverse"><span class="lnum">20</span> Cannot my body nor blood-sacrifice</div>
<div class="dverse">Entreat you to your wonted furtherance?</div>
<div class="dverse">Then take my soul, my body, soul and all,</div>
<div class="dverse">Before that England give the French the foil.
 <span class="sd-verseend">[<i>They depart.</i></span></div>
<div class="dverse">See, they forsake me! Now the time is come</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec025" id="lnum-aec025">25</a>
That France must vail her lofty-plumed crest</div>
<div class="dverse">And let her head fall into England’s lap.</div>
<div class="dverse">My ancient incantations are too weak,</div>
<div class="dverse">And hell too strong for me to buckle with:</div>
<div class="dverse">Now, France, thy glory droopeth to the dust.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Excursions. Re-enter</i>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span></span> <i>fighting hand to hand with</i> <span class="smcaps">Y<span>ORK</span>:</span>
<span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span></span> <i>is taken. The French fly</i>. </div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec030" id="lnum-aec030">30</a>
 <span class="sd-cn">York.</span>
Damsel of France, I think I have you fast:</div>
<div class="dverse">Unchain your spirits now with spelling charms</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec032" id="lnum-aec032">♦</a>
And try if they can gain your liberty.</div>
<div class="dverse">A goodly prize, fit for the devil’s grace!</div>
<div class="dverse">See, how the ugly wench doth bend her brows,</div>
<div class="dverse"><span class="lnum">35</span> As if with Circe she would change my shape!</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Changed to a worser shape thou canst not be.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 O, Charles the Dauphin is a proper man;</div>
<div class="dverse">No shape but his can please your dainty eye.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 A plaguing mischief light on Charles and thee!</div>
<div class="dverse"><span class="lnum">40</span> And may ye both be suddenly surprised</div>
<div class="dverse">By bloody hands, in sleeping on your beds!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Fell banning hag, enchantress, hold thy tongue!</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 I prithee, give me leave to curse awhile.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec044" id="lnum-aec044">♦</a>
 <span class="sd-cn">York.</span>
 Curse, miscreant, when thou comest to the stake.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="sd-entry"><i>Alarum. Enter</i> <span class="smcaps">S<span>UFFOLK</span>,</span> <i>with</i> <span class="smcaps">M<span>ARGARET</span></span> <i>in his hand</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec045" id="lnum-aec045">45</a>
 <span class="sd-cn">Suf.</span>
Be what thou wilt, thou art my prisoner.
<span class="sd-verseend">[<i>Gazes on her.</i></span></div>
<div class="dverse">O fairest beauty, do not fear nor fly!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec047" id="lnum-aec047">♦</a>
For I will touch thee but with reverent hands;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec048" id="lnum-aec048">♦</a>
I kiss these fingers for eternal peace,</div>
<div class="dverse">And lay them gently on thy tender side.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec050" id="lnum-aec050">50</a>
Who art thou? say, that I may honour thee.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Margaret my name, and daughter to a king,</div>
<div class="dverse">The King of Naples, whosoe’er thou art.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec053" id="lnum-aec053">♦</a>
 <span class="sd-cn">Suf.</span>
An earl I am, and Suffolk am I call’d.</div>
<div class="dverse">Be not offended, nature’s miracle,</div>
<div class="dverse"><span class="lnum">55</span> Thou art allotted to be ta’en by me:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec056" id="lnum-aec056">♦</a>
So doth the swan her downy cygnets save,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec057" id="lnum-aec057">♦</a>
Keeping them prisoner underneath her wings.</div>
<div class="dverse">Yet, if this servile usage once offend,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec059" id="lnum-aec059">♦</a>
 Go and be free again as Suffolk’s friend.
 <span class="sd-verseend">[<i>She is going.</i></span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec060" id="lnum-aec060">60</a>
O, stay! I have no power to let her pass;</div>
<div class="dverse">My hand would free her, but my heart says no.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec062" id="lnum-aec062">♦</a>
As plays the sun upon the glassy streams,</div>
<div class="dverse">Twinkling another counterfeited beam,</div>
<div class="dverse">So seems this gorgeous beauty to mine eyes.</div>
<div class="dverse"><span class="lnum">65</span> Fain would I woo her, yet I dare not speak:</div>
<div class="dverse">I’ll call for pen and ink, and write my mind.</div>
<div class="dverse">Fie, de la Pole! disable not thyself;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec068" id="lnum-aec068">♦</a>
Hast not a tongue? is she not here?</div>
<div class="dverse">Wilt thou be daunted at a woman’s sight?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec070" id="lnum-aec070">70</a>
Ay, beauty’s princely majesty is such,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec071" id="lnum-aec071">♦</a>
Confounds the tongue and makes the senses rough.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Say, Earl of Suffolk,—if thy name be so—</div>
<div class="dverse">What ransom must I pay before I pass?</div>
<div class="dverse">For I perceive I am thy prisoner.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec075" id="lnum-aec075">75</a>
 <span class="sd-cn">Suf.</span>
How canst thou tell she will deny thy suit,</div>
<div class="dverse">Before thou make a trial of her love?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec077" id="lnum-aec077">♦</a>
 <span class="sd-cn">Mar.</span>
Why speak’st thou not? what ransom must I pay?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 She’s beautiful and therefore to be woo’d;</div>
<div class="dverse">She is a woman, therefore to be won.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Wilt thou accept of ransom? yea, or no.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Suf.</span>  Fond man, remember that thou hast a wife;</div>
<div class="dverse">Then how can Margaret be thy paramour?</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 I were best to leave him, for he will not hear.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec083" id="lnum-aec083">♦</a>
 <span class="sd-cn">Suf.</span>
There all is marr’d; there lies a cooling card.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 He talks at random; sure, the man is mad.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec085" id="lnum-aec085">85</a>
 <span class="sd-cn">Suf.</span>
And yet a dispensation may be had.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 And yet I would that you would answer me.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I’ll win this Lady Margaret. For whom?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec089" id="lnum-aec089">♦</a>
Why, for my king: tush, that’s a wooden thing!</div>

<div class="dverse1"><span class="lnum">90</span>
 <span class="sd-cn">Mar.</span>  He talks of wood: it is some carpenter.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Yet so my fancy may be satisfied,</div>
<div class="dverse">And peace established between these realms.</div>
<div class="dverse">But there remains a scruple in that too;</div>
<div class="dverse">For though her father be the King of Naples,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec095" id="lnum-aec095">95</a>
Duke of Anjou and Maine, yet is he poor,</div>
<div class="dverse">And our nobility will scorn the match.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec097" id="lnum-aec097">♦</a>
 <span class="sd-cn">Mar.</span>
Hear ye, captain, are you not at leisure?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 It shall be so, disdain they ne’er so much:</div>
<div class="dverse">Henry is youthful and will quickly yield.</div>
<div class="dverse"><span class="lnum">100</span> Madam, I have a secret to reveal.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 What though I be enthrall’d? he seems a knight,</div>
<div class="dverse">And will not any way dishonour me.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Lady, vouchsafe to listen what I say.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Perhaps I shall be rescued by the French;</div>
<div class="dverse"><span class="lnum">105</span> And then I need not crave his courtesy.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec106" id="lnum-aec106">♦</a>
 <span class="sd-cn">Suf.</span>
Sweet madam, give me hearing in a cause—</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Tush, women have been captivate ere now.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec108" id="lnum-aec108">♦</a>
 <span class="sd-cn">Suf.</span>
Lady, wherefore talk you so?</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 I cry you mercy, ’tis but Quid for Quo.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec110" id="lnum-aec110">110</a>
 <span class="sd-cn">Suf.</span>
Say, gentle princess, would you not suppose</div>
<div class="dverse">Your bondage happy, to be made a queen?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec112" id="lnum-aec112">♦</a>
 <span class="sd-cn">Mar.</span>
To be a queen in bondage is more vile</div>
<div class="dverse">Than is a slave in base servility;</div>
<div class="dverse">For princes should be free.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 <span class="i12"> </span>  And so shall you,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec115" id="lnum-aec115">115</a>
If happy England’s royal king be free.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Why, what concerns his freedom unto me?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I’ll undertake to make thee Henry’s queen,</div>
<div class="dverse">To put a golden sceptre in thy hand</div>
<div class="dverse">And set a precious crown upon thy head,</div>
<div class="dverse">If thou wilt condescend to be my—</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec120" id="lnum-aec120">120</a>
 <span class="sd-cn">Mar.</span>
<span class="i16"> </span>  What?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 His love.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 I am unworthy to be Henry’s wife.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 No, gentle madam; I unworthy am</div>
<div class="dverse">To woo so fair a dame to be his wife</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec125" id="lnum-aec125">125</a>
And have no portion in the choice myself.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec126" id="lnum-aec126">♦</a>
How say you, madam, are ye so content?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec127" id="lnum-aec127">♦</a>
 <span class="sd-cn">Mar.</span>
An if my father please, I am content.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec128" id="lnum-aec128">♦</a>
 <span class="sd-cn">Suf.</span>
Then call our captains and our colours forth.</div>
<div class="dverse">And, madam, at your father’s castle walls</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec130" id="lnum-aec130">130</a>
We’ll crave a parley, to confer with him.</div>

<div class="sd-entry"><i>A parley sounded. Enter</i> <span class="smcaps">R<span>EIGNIER</span></span> <i>on the walls.</i></div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-aec131" id="lnum-aec131">♦</a>
See, Reignier, see, thy daughter prisoner!</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 To whom?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 <span class="i05"> </span>  To me.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 <span class="i08"> </span> Suffolk, what remedy?</div>
<div class="dverse">I am a soldier and unapt to weep</div>
<div class="dverse">Or to exclaim on fortune’s fickleness.</div>

<div class="dverse1"><span class="lnum">135</span>
 <span class="sd-cn">Suf.</span>  Yes, there is remedy enough, my lord:</div>
<div class="dverse">Consent, and for thy honour give consent,</div>
<div class="dverse">Thy daughter shall be wedded to my king;</div>
<div class="dverse">Whom I with pain have woo’d and won thereto;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec139" id="lnum-aec139">♦</a>
And this her easy-held imprisonment</div>
<div class="dverse"><span class="lnum">140</span> Hath gain’d thy daughter princely liberty.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 Speaks Suffolk as he thinks?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 <span class="i16"> </span>Fair Margaret knows</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec142" id="lnum-aec142">♦</a>
That Suffolk doth not flatter, face, or feign.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 Upon thy princely warrant, I descend</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec144" id="lnum-aec144">♦</a>
 To give thee answer of thy just demand.
 <span class="sd-verseend">[<i>Exit from the walls.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec145" id="lnum-aec145">145</a>
 <span class="sd-cn">Suf.</span>
And here I will expect thy coming.</div>

<div class="sd-entry"><i>Trumpets sound. Enter</i>
<span class="smcaps">R<span>EIGNIER</span>,</span> <i>below</i>.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 Welcome, brave earl, into our territories:</div>
<div class="dverse">Command in Anjou what your honour pleases.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec148" id="lnum-aec148">♦</a>
 <span class="sd-cn">Suf.</span>
Thanks, Reignier, happy for so sweet a child,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec149" id="lnum-aec149">♦</a>
Fit to be made companion with a king:</div>
<div class="dverse"><span class="lnum">150</span> What answer makes your grace unto my suit?</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 Since thou dost deign to woo her little worth</div>
<div class="dverse">To be the princely bride of such a lord;</div>
<div class="dverse">Upon condition I may quietly</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec154" id="lnum-aec154">♦</a>
Enjoy mine own, the country Maine and Anjou,</div>
<div class="dverse"><span class="lnum">155</span> Free from oppression or the stroke of war,</div>
<div class="dverse">My daughter shall be Henry’s, if he please.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 That is her ransom; I deliver her;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec158" id="lnum-aec158">♦</a>
And those two counties I will undertake</div>
<div class="dverse">Your grace shall well and quietly enjoy.</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">Reig.</span>  And I again, in Henry’s royal name,</div>
<div class="dverse">As deputy unto that gracious king,</div>
<div class="dverse">Give thee her hand, for sign of plighted faith.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Reignier of France, I give thee kingly thanks,</div>
<div class="dverse">Because this is in traffic of a king.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec165" id="lnum-aec165">165</a>
 <span class="sd-inline">[<i>Aside</i>]</span>
 And yet, methinks, I could be well content</div>
<div class="dverse">To be mine own attorney in this case.</div>
<div class="dverse">I’ll over then to England with this news,</div>
<div class="dverse">And make this marriage to be solemnized.</div>
<div class="dverse">So farewell, Reignier: set this diamond safe</div>
<div class="dverse"><span class="lnum">170</span> In golden palaces, as it becomes.</div>

<div class="dverse1"><span class="sd-cn">Reig.</span>
 I do embrace thee, as I would embrace</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec172" id="lnum-aec172">♦</a>
 The Christian prince, King Henry, were he here.</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Farewell, my lord: good wishes, praise and prayers</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec174" id="lnum-aec174">♦</a>
Shall Suffolk ever have of Margaret.
 <span class="sd-verseend">[<i>Going.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec175" id="lnum-aec175">175</a>
 <span class="sd-cn">Suf.</span>
Farewell, sweet madam: but hark you, Margaret;</div>
<div class="dverse">No princely commendations to my king?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec177" id="lnum-aec177">♦</a>
 <span class="sd-cn">Mar.</span>
 Such commendations as becomes a maid,</div>
<div class="dverse">A virgin and his servant, say to him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec179" id="lnum-aec179">♦</a>
 <span class="sd-cn">Suf.</span>
 Words sweetly placed and modestly directed.</div>
<div class="dverse"><span class="lnum">180</span> But, madam, I must trouble you again;</div>
<div class="dverse">No loving token to his majesty?</div>

<div class="dverse1"><span class="sd-cn">Mar.</span>
 Yes, my good lord, a pure unspotted heart,</div>
<div class="dverse">Never yet taint with love, I send the king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec184" id="lnum-aec184">♦</a>
 <span class="sd-cn">Suf.</span>
And this withal.
 <span class="sd-verseend">[<i>Kisses her.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aec185" id="lnum-aec185">185</a>
 <span class="sd-cn">Mar.</span>
That for thyself: I will not so presume</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec186" id="lnum-aec186">♦</a>
To send such peevish tokens to a king.
<span class="sd-verseend">[<i>Exeunt Reignier and Margaret.</i></span></div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 O, wert thou for myself! But, Suffolk, stay;</div>
<div class="dverse">Thou mayst not wander in that labyrinth;</div>
<div class="dverse">There Minotaurs and ugly treasons lurk.</div>
<div class="dverse"><span class="lnum">190</span> Solicit Henry with her wondrous praise:</div>
<div class="dverse">Bethink thee on her virtues that surmount,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec192" id="lnum-aec192">♦</a>
And natural graces that extinguish art;</div>
<div class="dverse">Repeat their semblance often on the seas,</div>
<div class="dverse">That, when thou comest to kneel at Henry’s feet,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aec195" id="lnum-aec195">195</a>
Thou mayst bereave him of his wits with wonder.
<span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aed</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>Camp of the</i>
 <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
 <span class="smcaps">Y<span>ORK</span></span> <i>in Anjou</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <i>and others</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed001" id="lnum-aed001">♦</a>
 <span class="sd-cn">York.</span>
Bring forth that sorceress condemn’d to burn.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">L<span>A</span></span> <span class="smcaps">P<span>UCELLE</span>,</span> <i>guarded, and a</i> Shepherd. </div>

<div class="dverse1"><span class="sd-cn">Shep.</span>
 Ah, Joan, this kills thy father’s heart outright!</div>
<div class="dverse">Have I sought every country far and near,</div>
<div class="dverse">And, now it is my chance to find thee out,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed005" id="lnum-aed005">5</a>
Must I behold thy timeless cruel death?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed006" id="lnum-aed006">♦</a>
Ah, Joan, sweet daughter Joan, I’ll die with thee!</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Decrepit miser! base ignoble wretch!</div>
<div class="dverse">I am descended of a gentler blood:</div>
<div class="dverse">Thou art no father nor no friend of mine.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed010" id="lnum-aed010">10</a>
 <span class="sd-cn">Shep.</span>
Out, out! My lords, an please you, ’tis not so;</div>
<div class="dverse">I did beget her, all the parish knows:</div>
<div class="dverse">Her mother liveth yet, can testify</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed013" id="lnum-aed013">♦</a>
She was the first fruit of my bachelorship.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Graceless! wilt thou deny thy parentage?</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">York.</span>  This argues what her kind of life hath been,</div>
<div class="dverse">Wicked and vile; and so her death concludes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed017" id="lnum-aed017">♦</a>
 <span class="sd-cn">Shep.</span>
Fie, Joan, that thou wilt be so obstacle!</div>
<div class="dverse">God knows thou art a collop of my flesh;</div>
<div class="dverse">And for thy sake have I shed many a tear:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed020" id="lnum-aed020">20</a>
Deny me not, I prithee, gentle Joan.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Peasant, avaunt! You have suborn’d this man,</div>
<div class="dverse">Of purpose to obscure my noble birth.</div>

<div class="dverse1"><span class="sd-cn">Shep.</span>
 ’Tis true, I gave a noble to the priest</div>
<div class="dverse">The morn that I was wedded to her mother.</div>
<div class="dverse"><span class="lnum">25</span> Kneel down and take my blessing, good my girl.</div>
<div class="dverse">Wilt thou not stoop? Now cursed be the time</div>
<div class="dverse">Of thy nativity! I would the milk</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed028" id="lnum-aed028">♦</a>
Thy mother gave thee when thou suck’dst her breast,</div>
<div class="dverse">Had been a little ratsbane for thy sake!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed030" id="lnum-aed030">30</a>
Or else, when thou didst keep my lambs a-field,</div>
<div class="dverse">I wish some ravenous wolf had eaten thee!</div>
<div class="dverse">Dost thou deny thy father, cursed drab?</div>
<div class="dverse">O, burn her, burn her! hanging is too good.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Take her away; for she hath lived too long,</div>
<div class="dverse"><span class="lnum">35</span> To fill the world with vicious qualities.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 First, let me tell you whom you have condemn’d:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed037" id="lnum-aed037">♦</a>
Not me begotten of a shepherd swain,</div>
<div class="dverse">But issued from the progeny of kings;</div>
<div class="dverse">Virtuous and holy; chosen from above,</div>
<div class="dverse"><span class="lnum">40</span> By inspiration of celestial grace,</div>
<div class="dverse">To work exceeding miracles on earth.</div>
<div class="dverse">I never had to do with wicked spirits:</div>
<div class="dverse">But you, that are polluted with your lusts,</div>
<div class="dverse">Stain’d with the guiltless blood of innocents,</div>
<div class="dverse"><span class="lnum">45</span> Corrupt and tainted with a thousand vices,</div>
<div class="dverse">Because you want the grace that others have,</div>
<div class="dverse">You judge it straight a thing impossible</div>
<div class="dverse">To compass wonders but by help of devils.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed049" id="lnum-aed049">♦</a>
No, misconceived! Joan of Arc hath been</div>
<div class="dverse"><span class="lnum">50</span> A virgin from her tender infancy,</div>
<div class="dverse">Chaste and immaculate in very thought;</div>
<div class="dverse">Whose maiden blood, thus rigorously effused,</div>
<div class="dverse">Will cry for vengeance at the gates of heaven.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed054" id="lnum-aed054">♦</a>
 <span class="sd-cn">York.</span>
Ay, ay: away with her to execution!</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">War.</span>  And hark ye, sirs; because she is a maid,</div>
<div class="dverse">Spare for no faggots, let there be enow:</div>
<div class="dverse">Place barrels of pitch upon the fatal stake,</div>
<div class="dverse">That so her torture may be shortened.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Will nothing turn your unrelenting hearts?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed060" id="lnum-aed060">60</a>
Then, Joan, discover thine infirmity,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed061" id="lnum-aed061">♦</a>
That warranteth by law to be thy privilege.</div>
<div class="dverse">I am with child, ye bloody homicides:</div>
<div class="dverse">Murder not then the fruit within my womb,</div>
<div class="dverse">Although ye hale me to a violent death.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">York.</span>  Now heaven forfend! the holy maid with child!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed066" id="lnum-aed066">♦</a>
 <span class="sd-cn">War.</span>
The greatest miracle that e’er ye wrought:</div>
<div class="dverse">Is all your strict preciseness come to this?</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 She and the Dauphin have been juggling:</div>
<div class="dverse">I did imagine what would be her refuge.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed070" id="lnum-aed070">70</a>
 <span class="sd-cn">War.</span>
Well, go to; we’ll have no bastards live;</div>
<div class="dverse">Especially since Charles must father it.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 You are deceived; my child is none of his:</div>
<div class="dverse">It was Alençon that enjoy’d my love.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed074" id="lnum-aed074">♦</a>
 <span class="sd-cn">York.</span>
Alençon! that notorious Machiavel!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed075" id="lnum-aed075">75</a>
It dies, an if it had a thousand lives.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 O, give me leave, I have deluded you:</div>
<div class="dverse">’Twas neither Charles nor yet the duke I named,</div>
<div class="dverse">But Reignier, king of Naples, that prevail’d.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 A married man! that’s most intolerable.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">York.</span>  Why, here’s a girl! I think she knows not well,</div>
<div class="dverse">There were so many, whom she may accuse.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed082" id="lnum-aed082">♦</a>
 <span class="sd-cn">War.</span>
It’s sign she hath been liberal and free.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 And yet, forsooth, she is a virgin pure.</div>
<div class="dverse">Strumpet, thy words condemn thy brat and thee:</div>
<div class="dverse"><span class="lnum">85</span> Use no entreaty, for it is in vain.</div>

<div class="dverse1"><span class="sd-cn">Puc.</span>
 Then lead me hence; with whom I leave my curse:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed087" id="lnum-aed087">♦</a>
May never glorious sun reflex his beams</div>
<div class="dverse">Upon the country where you make abode;</div>
<div class="dverse">But darkness and the gloomy shade of death</div>
<div class="dverse"><span class="lnum">90</span> Environ you, till mischief and despair</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed091" id="lnum-aed091">♦</a>
Drive you to break your necks or hang yourselves!
<span class="sd-verseend">[<i>Exit, guarded.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Break thou in pieces and consume to ashes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed093" id="lnum-aed093">♦</a>
Thou foul accursed minister of hell!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>ARDINAL</span></span> <span class="smcaps">B<span>EAUFORT</span>,</span> Bishop of Winchester, <i>attended</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed094" id="lnum-aed094">♦</a>
 <span class="sd-cn">Car.</span>
Lord regent, I do greet your excellence</div>
<div class="dverse"><span class="lnum">95</span> With letters of commission from the king.</div>
<div class="dverse">For know, my lords, the states of Christendom,</div>
<div class="dverse">Moved with remorse of these outrageous broils,</div>
<div class="dverse">Have earnestly implored a general peace</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed099" id="lnum-aed099">♦</a>
Betwixt our nation and the aspiring French;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed100" id="lnum-aed100">100</a>
And here at hand the Dauphin and his train</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed101" id="lnum-aed101">♦</a>
Approacheth, to confer about some matter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed102" id="lnum-aed102">♦</a>
 <span class="sd-cn">York.</span>
Is all our travail turn’d to this effect?</div>
<div class="dverse">After the slaughter of so many peers,</div>
<div class="dverse">So many captains, gentlemen and soldiers,</div>
<div class="dverse"><span class="lnum">105</span> That in this quarrel have been overthrown</div>
<div class="dverse">And sold their bodies for their country’s benefit,</div>
<div class="dverse">Shall we at last conclude effeminate peace?</div>
<div class="dverse">Have we not lost most part of all the towns,</div>
<div class="dverse">By treason, falsehood and by treachery,</div>
<div class="dverse"><span class="lnum">110</span> Our great progenitors had conquered?</div>
<div class="dverse">O, Warwick, Warwick! I foresee with grief</div>
<div class="dverse">The utter loss of all the realm of France.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Be patient, York: if we conclude a peace,</div>
<div class="dverse">It shall be with such strict and severe covenants</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed115" id="lnum-aed115">115</a>
As little shall the Frenchmen gain thereby.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>HARLES</span>,</span> <span class="smcaps">A<span>LENÇON</span>,</span> Bastard, <span class="smcaps">R<span>EIGNIER</span>,</span> <i>and others</i>.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 Since, lords of England, it is thus agreed</div>
<div class="dverse">That peaceful truce shall be proclaim’d in France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed118" id="lnum-aed118">♦</a>
We come to be informed by yourselves</div>
<div class="dverse">What the conditions of that league must be.</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">York.</span>  Speak, Winchester; for boiling choler chokes</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed121" id="lnum-aed121">♦</a>
The hollow passage of my poison’d voice,</div>
<div class="dverse">By sight of these our baleful enemies.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Charles, and the rest, it is enacted thus:</div>
<div class="dverse">That, in regard King Henry gives consent,</div>
<div class="dverse"><span class="lnum">125</span> Of mere compassion and of lenity,</div>
<div class="dverse">To ease your country of distressful war,</div>
<div class="dverse">And suffer you to breathe in fruitful peace,</div>
<div class="dverse">You shall become true liegemen to his crown:</div>
<div class="dverse">And, Charles, upon condition thou wilt swear</div>
<div class="dverse"><span class="lnum">130</span> To pay him tribute, and submit thyself,</div>
<div class="dverse">Thou shalt be placed as viceroy under him,</div>
<div class="dverse">And still enjoy thy regal dignity.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed133" id="lnum-aed133">♦</a>
 <span class="sd-cn">Alen.</span>
Must he be then as shadow of himself?</div>
<div class="dverse">Adorn his temples with a coronet,</div>
<div class="dverse"><span class="lnum">135</span> And yet, in substance and authority,</div>
<div class="dverse">Retain but privilege of a private man?</div>
<div class="dverse">This proffer is absurd and reasonless.</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 ’Tis known already that I am possess’d</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed139" id="lnum-aed139">♦</a>
With more than half the Gallian territories,</div>
<div class="dverse"><span class="lnum">140</span> And therein reverenced for their lawful king:</div>
<div class="dverse">Shall I, for lucre of the rest unvanquish’d,</div>
<div class="dverse">Detract so much from that prerogative,</div>
<div class="dverse">As to be call’d but viceroy of the whole?</div>
<div class="dverse">No, lord ambassador, I’ll rather keep</div>
<div class="dverse"><span class="lnum">145</span> That which I have than, coveting for more,</div>
<div class="dverse">Be cast from possibility of all.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Insulting Charles! hast thou by secret means</div>
<div class="dverse">Used intercession to obtain a league,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed149" id="lnum-aed149">♦</a>
And, now the matter grows to compromise,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed150" id="lnum-aed150">150</a>
Stand’st thou aloof upon comparison?</div>
<div class="dverse">Either accept the title thou usurp’st,</div>
<div class="dverse">Of benefit proceeding from our king</div>
<div class="dverse">And not of any challenge of desert,</div>
<div class="dverse">Or we will plague thee with incessant wars.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed155" id="lnum-aed155">155</a>
 <span class="sd-cn">Reig.</span>
My lord, you do not well in obstinacy</div>
<div class="dverse">To cavil in the course of this contract:</div>
<div class="dverse">If once it be neglected, ten to one</div>
<div class="dverse">We shall not find like opportunity.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed159" id="lnum-aed159">♦</a>
 <span class="sd-cn">Alen.</span>
To say the truth, it is your policy</div>
<div class="dverse"><span class="lnum">160</span> To save your subjects from such massacre</div>
<div class="dverse">And ruthless slaughters as are daily seen</div>
<div class="dverse">By our proceeding in hostility;</div>
<div class="dverse">And therefore take this compact of a truce,</div>
<div class="dverse">Although you break it when your pleasure serves.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aed165" id="lnum-aed165">165</a>
 <span class="sd-cn">War.</span>
 How say’st thou, Charles? shall our condition stand?</div>

<div class="dverse1"><span class="sd-cn">Char.</span>
 It shall;</div>
<div class="dverse">Only reserved, you claim no interest</div>
<div class="dverse">In any of our towns of garrison.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Then swear allegiance to his majesty,</div>
<div class="dverse"><span class="lnum">170</span> As thou art knight, never to disobey</div>
<div class="dverse">Nor be rebellious to the crown of England,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed172" id="lnum-aed172">♦</a>
Thou, nor thy nobles, to the crown of England.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed173" id="lnum-aed173">♦</a>
So, now dismiss your army when ye please;</div>
<div class="dverse">Hang up your ensigns, let your drums be still,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aed175" id="lnum-aed175">175</a>
 For here we entertain a solemn peace.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">aee</span> <span class="smcaps">S<span>CENE</span></span> V. <i>London. The royal
palace</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">S<span>UFFOLK</span></span> <i>in conference with
the</i> <span class="smcaps">K<span>ING</span>,</span> <span class="smcaps">G<span>LOUCESTER</span></span> <i>and</i> <span class="smcaps">E<span>XETER</span></span>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aee001" id="lnum-aee001">♦</a>
 <span class="sd-cn">King.</span>
Your wondrous rare description, noble earl,</div>
<div class="dverse">Of beauteous Margaret hath astonish’d me:</div>
<div class="dverse">Her virtues graced with external gifts</div>
<div class="dverse">Do breed love’s settled passions in my heart:</div>
<div class="dverse"><span class="lnum">5</span> And like as rigour of tempestuous gusts</div>
<div class="dverse">Provokes the mightiest hulk against the tide,</div>
<div class="dverse">So am I driven by breath of her renown</div>
<div class="dverse">Either to suffer shipwreck or arrive</div>
<div class="dverse">Where I may have fruition of her love.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Suf.</span>  Tush, my good lord, this superficial tale</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee011" id="lnum-aee011">♦</a>
Is but a preface of her worthy praise;</div>
<div class="dverse">The chief perfections of that lovely dame,</div>
<div class="dverse">Had I sufficient skill to utter them,</div>
<div class="dverse">Would make a volume of enticing lines,</div>
<div class="dverse"><span class="lnum">15</span> Able to ravish any dull conceit:</div>
<div class="dverse">And, which is more, she is not so divine,</div>
<div class="dverse">So full-replete with choice of all delights,</div>
<div class="dverse">But with as humble lowliness of mind</div>
<div class="dverse">She is content to be at your command;</div>
<div class="dverse"><span class="lnum">20</span> Command, I mean, of virtuous chaste intents,</div>
<div class="dverse">To love and honour Henry as her lord.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 And otherwise will Henry ne’er presume.</div>
<div class="dverse">Therefore, my lord protector, give consent</div>
<div class="dverse">That Margaret may be England’s royal queen.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Glou.</span>  So should I give consent to flatter sin.</div>
<div class="dverse">You know, my lord, your highness is betroth’d</div>
<div class="dverse">Unto another lady of esteem:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee028" id="lnum-aee028">♦</a>
How shall we then dispense with that contract,</div>
<div class="dverse">And not deface your honour with reproach?</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Suf.</span>  As doth a ruler with unlawful oaths;</div>
<div class="dverse">Or one that, at a triumph having vow’d</div>
<div class="dverse">To try his strength, forsaketh yet the lists</div>
<div class="dverse">By reason of his adversary’s odds:</div>
<div class="dverse">A poor earl’s daughter is unequal odds:</div>
<div class="dverse"><span class="lnum">35</span> And therefore may be broke without offence.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Why, what, I pray, is Margaret more than that?</div>
<div class="dverse">Her father is no better than an earl,</div>
<div class="dverse">Although in glorious titles he excel.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aee039" id="lnum-aee039">♦</a>
 <span class="sd-cn">Suf.</span>
Yes, my lord, her father is a king,</div>
<div class="dverse"><span class="lnum">40</span> The King of Naples and Jerusalem;</div>
<div class="dverse">And of such great authority in France</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee042" id="lnum-aee042">♦</a>
As his alliance will confirm our peace</div>
<div class="dverse">And keep the Frenchmen in allegiance.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And so the Earl of Armagnac may do,</div>
<div class="dverse"><span class="lnum">45</span> Because he is near kinsman unto Charles.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aee046" id="lnum-aee046">♦</a>
 <span class="sd-cn">Exe.</span>
Beside, his wealth doth warrant a liberal dower,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee047" id="lnum-aee047">♦</a>
Where Reignier sooner will receive than give.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 A dower, my lords! disgrace not so your king,</div>
<div class="dverse">That he should be so abject, base and poor,</div>
<div class="dverse"><span class="lnum">50</span> To choose for wealth and not for perfect love.</div>
<div class="dverse">Henry is able to enrich his queen</div>
<div class="dverse">And not to seek a queen to make him rich:</div>
<div class="dverse">So worthless peasants bargain for their wives,</div>
<div class="dverse">As market-men for oxen, sheep, or horse.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee055" id="lnum-aee055">55</a>
Marriage is a matter of more worth</div>
<div class="dverse">Than to be dealt in by attorneyship;</div>
<div class="dverse">Not whom we will, but whom his grace affects,</div>
<div class="dverse">Must be companion of his nuptial bed:</div>
<div class="dverse">And therefore, lords, since he affects her most,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee060" id="lnum-aee060">60</a>
It most of all these reasons bindeth us,</div>
<div class="dverse">In our opinions she should be preferr’d.</div>
<div class="dverse">For what is wedlock forced but a hell,</div>
<div class="dverse">An age of discord and continual strife?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee064" id="lnum-aee064">♦</a>
Whereas the contrary bringeth bliss,</div>
<div class="dverse"><span class="lnum">65</span> And is a pattern of celestial peace.</div>
<div class="dverse">Whom should we match with Henry, being a king,</div>
<div class="dverse">But Margaret, that is daughter to a king?</div>
<div class="dverse">Her peerless feature, joined with her birth,</div>
<div class="dverse">Approves her fit for none but for a king:</div>
<div class="dverse"><span class="lnum">70</span> Her valiant courage and undaunted spirit,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee071" id="lnum-aee071">♦</a>
More than in women commonly is seen,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee072" id="lnum-aee072">♦</a>
Will answer our hope in issue of a king;</div>
<div class="dverse">For Henry, son unto a conqueror,</div>
<div class="dverse">Is likely to beget more conquerors,</div>
<div class="dverse"><span class="lnum">75</span> If with a lady of so high resolve</div>
<div class="dverse">As is fair Margaret he be link’d in love.</div>
<div class="dverse">Then yield, my lords; and here conclude with me</div>
<div class="dverse">That Margaret shall be queen, and none but she.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Whether it be through force of your report,</div>
<div class="dverse"><span class="lnum">80</span> My noble Lord of Suffolk, or for that</div>
<div class="dverse">My tender youth was never yet attaint</div>
<div class="dverse">With any passion of inflaming love,</div>
<div class="dverse">I cannot tell; but this I am assured,</div>
<div class="dverse">I feel such sharp dissension in my breast,</div>
<div class="dverse"><span class="lnum">85</span> Such fierce alarums both of hope and fear,</div>
<div class="dverse">As I am sick with working of my thoughts.</div>
<div class="dverse">Take, therefore, shipping; post, my lord, to France;</div>
<div class="dverse">Agree to any covenants, and procure</div>
<div class="dverse">That Lady Margaret do vouchsafe to come</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee090" id="lnum-aee090">90</a>
To cross the seas to England and be crown’d</div>
<div class="dverse">King Henry’s faithful and anointed queen:</div>
<div class="dverse">For your expenses and sufficient charge,</div>
<div class="dverse">Among the people gather up a tenth.</div>
<div class="dverse">Be gone, I say; for, till you do return,</div>
<div class="dverse"><span class="lnum">95</span> I rest perplexed with a thousand cares.</div>
<div class="dverse">And you, good uncle, banish all offence:</div>
<div class="dverse">If you do censure me by what you were,</div>
<div class="dverse">Not what you are, I know it will excuse</div>
<div class="dverse">This sudden execution of my will.</div>
<div class="dverse"><span class="lnum">100</span> And so, conduct me where, from company,</div>
<div class="dverse">I may revolve and ruminate my grief.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-aee102" id="lnum-aee102">♦</a>
 <span class="sd-cn">Glou.</span>
 Ay, grief, I fear me, both at first and last.
 <span class="sd-verseend">[<i>Exeunt Gloucester and Exeter.</i></span></div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Thus Suffolk hath prevail’d; and thus he goes,</div>
<div class="dverse">As did the youthful Paris once to Greece,</div>
<div class="dverse"><span class="lnum">105</span> With hope to find the like event in love,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-aee106" id="lnum-aee106">♦</a>
But prosper better than the Trojan did.</div>
<div class="dverse">Margaret shall now be queen, and rule the king;</div>
<div class="dverse">But I will rule both her, the king and realm.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="right toppada"><small><a href="#idtoc" class="pginternal">toc</a></small></div>

